-- GENERATED by `wfj generate` from data/quest/quest-0002.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [2038] = { "Binglesの失われた道具", "Binglesの道具を見つけて返す：\n\nBingles' Wrench、Bingles' Screwdriver、Bingles' Hammer、Bingles' Blastencapper。", "Lochに墜落しただけでも十分ひどいのに、近くの島のtroggどもが襲ってきて、僕の道具と特製のBlastenheimer Blastencapper爆薬を盗んでいったんだ。ジャイロコプターも爆薬もなしじゃ、運動に勝ち目はないよ！\n\n僕の道具を取り返して、Blastencapper爆薬を見つけてくれ、{name}。Gnomereganのために！", "{name}! 僕の持ち物はどこなんだ?!", "君はこの運動に大きく貢献してくれたよ、{name}。Gnomereganにはびこるtroggとleper gnomeどもは、もうすぐノームの空襲の衝撃を思い知ることになる！", 0xf9774368, 0x792008cf, 0xd09399c8, 0x1dd7bb2d, 0x5ee96793, "....." },
  [2039] = { "Binglesを捜せ", "Loch ModanにいるBingles Blastenheimerを捜してください。", "Binglesとの連絡が途絶えた！Gnomereganの上空を偵察する任務に出たきり、一週間以上も報告がないんだ。きっと自爆しちゃったに違いないよ。\n\n最後に目撃されたのはLochの上を飛んでいるところだ。調べてみてくれないか、{name}。", nil, "それで、Gnoarnは私の偵察能力を信頼していないとな？何故だろう...\n\nそれは気にしないでくれ。私は君の助けが必要だ！いや！この任務に必要だ！", 0x615905ca, 0x3376ba72, 0x0eb9eb85, nil, 0xe10b4d25, "...m." },
  [2040] = { "地下攻撃", "DeadminesからGnoam Sprecklesprocketを取り戻し、StormwindのShoni the Shilentに返して下さい。", "Gnomereganがあの卑劣なtroggどもに支配されてしまった! 事態は深刻だが、もしかしたら君なら力になれるかもしれない、{name}。\n\nDeadminesの奥深くに、まだ動くゴブリン製のシュレッダーがある。そのシュレッダーを見つけて、無傷の動力装置を持ち帰ってくれ。シュレッダーの動力装置があれば、我々のジャイロドリルマチック掘削機に必要な力を与えて、Gnomereganの岩だらけの地下の境界を突き破り、ノームの突撃への道を開けるんだ!", "Gnoam Sprecklesprocketは見つかったかい、{name}?", "よくやったわ、{name}。感謝するわ。Gnomereganはまた一歩、解放の日へ近づいた!", 0x80a0cba5, 0xea953ef0, 0x63b95920, 0x9b272279, 0x733d0acf, "....." },
  [2041] = { "Shoniとの対話", "StormwindにいるShoni the Shilentと話して下さい。", "もしかしたら……もしかしたら、あなたならGnomereganをめぐる戦いで私たちを助けてくれるかもしれない。\n\nStormwindに、私たちの地下突撃隊の司令官、Shoni the Shilentがいるわ。Shoniは彼女のgyrodrillmatic excavationatorsのことで手助けを必要としているの。\n\nたぶん、Stormwindのドワーフたちの中にいるはずよ。\n\n幸運を、{name}。", nil, "中央からの指令を運んできたの?", 0xf9384378, 0xe35660ac, 0xa17f2e67, nil, 0xc9cd2431, "...m." },
  [2078] = { "Gyromastの復讐", "GelkakのFirst MateであるThreshwackonator 4100を見つけ、Gelkakのところへ連れ帰る。", "陸者よ、俺の一等航海士を見つけてくんな。\n\nこの鍵を持ってって、奴の頭に差し込んで、ここへ連れ戻して船長に仕えさせるんだ。\n\n俺の一等航海士が奴らを捕まえたら、あのmurlocどもとその頭目はさぞかし面白くねえだろうよ！", "わしの一等航海士はどこだ、{name}? 急がねえと、すぐに手枷と鮫の餌食だぜ!", "ヤーッ……お前さん、ただの臆病な海の犬っころ以上だってことを証明しつつあるな、陸者よ。\n\nこの調子で続けりゃ、船長がお前さんを船尾甲板の甲板磨きに昇進させてくれるかもしれねえぞ……", 0xd9963931, 0xd2b23f5c, 0x7ec45f79, 0x4a2ccf6d, 0xa5444273, "....." },
  [2098] = { "Gyromastの回収", "Gelkak's Keyの3つの欠片を見つけ、Gelkak Gyromastのところへ持って行く。", "海賊稼業ってのは楽じゃねえんだ、陸者よ。略奪と酒ばかりじゃねえ！ 悲しいかな、あの厄介なThreshadonsのせいで、俺の船はすぐ沖で沈んじまった。\n\n俺に必要なのは、一等航海士を元通り動けるようにすることだ！\n\n岸に打ち上げられた時、一等航海士の鍵が岩にぶつかって壊れて、Darkshoreの獣どもにかっさらわれちまった。目の端で、Ragin' CrawlersやFerocious Foreststrider、それにmurlocが残骸をあさってるのが見えたぜ……", "わしの壊れた鍵は見つかったか、陸者め?", "おい、この汚ねえ海の犬め！やりやがったな！もうすぐわしの一等航海士もまた働けるようになって、あの獣どもは何が起きたかも分からねえだろうよ！\n\nうーむ、わしの一等航海士を見なかったか？", 0xfb8edee7, 0xb52c5a6e, 0x1f7e89e6, 0x5badcb40, 0x8453295d, "....." },
  [2118] = { "疫病に冒された地", "生きたRabid Thistle Bearを捕まえ、Tharnariunのところへ連れて行く。\n\nRabid Thistle Bearを捕まえられずに罠を失った場合は、Tharnariun Treetenderのところへ戻って別の罠をもらう。", "病がDarkshore一帯に広がり、触れるものすべての心と体をむしばんでいます。\n\nこの疫病で最もひどい打撃を受けたのはThistle Bearsです。かつては気高かった獣が、今では狂暴で荒れ狂う破壊の道具となってしまいました。私はこの病の治療法を持っているかもしれません。\n\nこの罠を森へ持っていき、地面に仕掛けてください。光を横切ったRabid Thistle Bearは、少しの間おとなしくなります。熊がおとなしくなれば、あなたについてくるでしょう。その熊をここまで連れてきてください、{name}。", "病気の動物を連れてきてくれましたか、{name}?\n\n罠を作動させられなくても、心配はいりません――Tharnariun's Hopeは永遠です。別の罠が必要なら、任務を破棄して私のところへ報告に戻ってきてください。", "我々の仕事はまだ始まったばかりだ、{name}。次の任務への準備はできているか？", 0xfa0a3a70, 0x3807aa6c, 0xe76e9858, 0xcaf47f66, 0xb17abac8, "....." },
  [2138] = { "感染者の浄化", "Rabid Thistle Bearを20体倒して森を浄化し、DarkshoreのTharnariun Treetenderのところへ戻る。", "恐れていた通り、治療法は効きませんでした。\n\n自然の獣を殺せと命じるのは本当に悲しいことですが、病に冒され汚れたthistle bearは始末しなければなりません。\n\n森へ戻り、rabid thistle bearを20頭倒してください、{name}。それで疫病が止まることは決してないでしょうが、あの動物たちが私たちの森とそこに住む者たちに与えている被害を、しばらくは食い止められるでしょう。", "任務は終わりましたか?", "あなたはAuberdineに大きな貢献をしてくれました、{name}。ですが、あなたの務めはまだ終わっていません。\n\n休んだら、私のところへ戻ってきてください。\n\n……それと{name}、さらなる流血に備えて、心と魂を整えておいてください。", 0x6f6f3496, 0x02dfdd6a, 0x7195c76b, 0x79783cba, 0x6c182eed, "....." },
  [2139] = { "Tharnariun's Hope", "Den Motherを見つけて倒す。", "私たちの民と土地が生き延びるには、不幸な代償が伴うのです、{name}。\n\nあなたは自然の僕たちの血を流しました。多くの病んだ動物を倒したのです。Auberdineの人々はあなたに恩があります。森の痛みが和らいだのですから――たとえほんの一時のことだとしても。\n\n最後の仕事を一つお願いしますが、覚悟してください。また殺さなければならないのです。あなたに頼るのはこれが最後になることを願っています、{name}。\n\n北東の、Bashal'Aranの近くの洞窟にDen Motherが棲んでいます。彼女を倒してください。", "感染したDen Motherが倒されれば、我らの地に入り込むRabid Thistle Bearsの数は減ります。時間を無駄にしないでください、{name}。", "あなたは勇敢に、そして名誉をもってAuberdineのために戦ってくれました、{name}。戦に引き裂かれた我らの地では、死と絶望はありふれたものです。多くの者はこの新たな故郷での暮らしという試練に立ち向かわず、家に閉じこもるか、より守りの固いAllianceの地へ逃れることを選ぶでしょう。\n\nありがとう、{name}。近いうちに、別の敵を相手に戦友として肩を並べて戦える日が来るかもしれませんね。", 0xf10fef91, 0x4766c644, 0xe4256bfb, 0x3c698219, 0x8e54a76e, "....." },
  [2158] = { "休息", "Lion's Pride InnにいるInnkeeper Farleyに話しかける。", "冒険をしていると、疲れて、休む必要性もでてくるよ。\n\nそんな時には、Lion's Pride Innがオススメ！\n\n親友のInnkeeper Farleyがそこを経営しているんだ。\n\n僕が紹介したって彼に言えば、きっと特別価格で食べ物を提供してくれるよ。\n\nLion's Pride Innは、この道を南に沿って行けばあるよ。ぜひ立ち寄ってね！", nil, "疲れた時には休息が一番!　暖炉の近くに座って、体を癒してね。\n\nついでに美味しい食事でもつまんどく？", 0xf6b2744d, 0xf61951e2, 0xff0677e6, nil, 0x6e2b261e, "...m." },
  [2159] = { "Dolanaar への配達物", "Innkeeper Keldamyr に Dolanaar Delivery を渡して下さい。", "ご機嫌よう、若き {class} 。手伝ってはもらえないか? Dolanaar の町へ届けなくてはならない薬草の包みがあるんだが、私はまだ Shadowglen のドルイドとの仕事があるから離れるわけにいかないんだ。\n\n包みを届けてもらえないかい? Dolanaar の宿にいるInnkeeper Keldamyr に届けるものなんだが。Dolanaar の宿は道に沿って南へ行くとある。", "何かご用ですか、若い方? 宿屋で休んでいかれますか? hearthstoneが必要ですか?", "ああそうか、Shadowglen から薬草の届け物だね。話すことがたくさんあったから、Porthannius 本人が届けに来られなかったのは残念だ。とはいえ、薬草が手に入ったし君が来てくれて嬉しいよ。\n\nここにいるあいだはくつろいでくれ。英雄たるもの、力と精神を最高の状態に保っておかねばならないのだから、休める時は休まなくてはならない。己の心身の休息を無視することは確実な失敗への道だ。\n\nだから……休むんだよ。", 0x1821b05c, 0x63d50e5c, 0xc4d46c8a, 0x4944e9aa, 0x1a7ac861, "....." },
  [2160] = { "Tannokへの補給", "KharanosにいるTannok FrosthammerにCrate of Inn Suppliesを届けろ。", "おい！ 元気のいい冒険者みたいだな。峠を越えるつもりなら、Kharanosの宿屋に荷物を届けてもらえないか？\n\n宿屋には寄るつもりだったんだろ？ 峠を抜けられたら、きっとそこで一息つきたくなるさ。\n\nとにかく、これを宿屋の主人の助手、Tannok Frosthammerに届けてくれ。俺自身は峠を越えられないし、Mountaineerの護衛が通りかかるのは何日も先なんだ！", "やあ! 入って、火のそばに座りなよ。エールを一杯やって温まるといい。", "ああ、ようやくHandsからの物資だ! 心配し始めていたところでね。troggが峠を占拠して以来、Anvilmarからの便りもほとんど途絶えていたんだ。\n\nここまで運んでくれてありがとう、{name}。どうか、ゆっくりしていってくれ。旅の後で疲れているだろう。", 0x1a599de9, 0xec5c9fbf, 0x3e311c16, 0xd1d47487, 0xe882bc33, "....." },
  [2161] = { "ピオンの重荷", "Ukor's BurdenをRazor HillのInnkeeper Groskに渡してください。", "ちょっといいかな? 手伝ってくれないか?\n\nおいらここに食料の荷物を持ってるんだ。おいらScorpidsやSpiderやら悪い奴等に勇敢に立ち向かって道沿いに歩いてきたんだよ! おいらその食料をValley of Trialsに持っていったんだ。あの人たちに必要だと思ったし、手伝いたかったしね。 でも、あの人たちは少しの食料も必要じゃなかったんだ!\n\n今、それをRazor Hillに持って帰らなくちゃいけなくなったんだけど、道中の獣どもが怖いのよ…\n\nおいらの代わりにそれ持っていってくれない? おいらはただのピオン（一般労働者）だけど、あんたは英雄じゃないか。 怖いものなんてないさ!\n\nRazor Hillの宿屋のInnkeeper Groskにそれを渡してよ。 ありがとね!", "Razor Hillへようこそ!", "ああ、これはUkorがValley of Trialsに持っていった食料じゃないか。 あいつらいらなかったのか? まぁ、多分あいつらはあんた方英雄をトレーニングで飢えさせたいんだろうさ。 精神を鍛えろって言ってるしな!\n\n食料を返してくれてありがとうよ。 棚に片付けるとするかな…しかしここでまずは何か軽い食事でもどうかね!\n\nそれで、ここ、宿屋で休息するのを忘れちゃだめだよ。 あんたはこの世界で活躍する準備ができてる勇敢な{class}かもしれんが、あんたの気力がじわじわ低下させられると、あんた自身、またはHordeにとってあまり良くないだろうからな。", 0x7aa7b221, 0xde148f6a, 0xcd75d4e8, 0x4bc9da1c, 0xef14d510, "....." },
  [2178] = { "お気楽Strider生活", "AuberdineのAlanndarian NightsongのところへStrider Meat 5つを持ち帰って下さい。", "このおいしそうな香りがしますか？ 私の秘伝のレシピですよ、{name}。新鮮なstriderのシチューです。おいしいですよ！\n\nもしかして、このレシピを覚えてみたいですか？\n\nレシピを教える前に、あなたがあの獣たちを扱えることを証明してもらわなければなりません。\n\nいえ、出かけていって一頭を飼い慣らし、それに乗って戻ってこいとは言いません。けれども、何頭か倒して、そのジューシーなmeatを持ってきてくれたら、striderのシチューの作り方を教える気になるかもしれませんね。", "鍋は空っぽで腹ぺこだ! 何をそんなに手間取っているんだ?", "素晴らしい! 作ったら、どう感じたか教えて下さいね。{name}!", 0xfb77df5a, 0xccc0962f, 0x0abb668a, 0xe34f9c3e, 0x42580f7f, "....." },
  [2198] = { "Shattered Necklace", "壊れた首飾りに秘められた本来の価値を知るため、製作者を探して下さい。", "あなたは曇ったネックレスを見つけた。曇ってはいるものの、その下には精巧で魔法のこもった細工が隠れている。ネックレスは壊れており、台座からは3つの宝石が失われているようだ。ネックレスの裏には、Ironforgeの市章がかすかに刻印されている。その刻印の下には、小さな3つの文字が彫られている。「TdK」。\n\nこのネックレスから何か分かることがあるとすれば、その由来を知る必要があるだろう。刻印と頭文字が手がかりになるかもしれない……", "ノーム違いだぜ、あんた! 俺はそこには一度も行ってない! 何も証明なんかできないぞ!\n\nちょっと待て……お前は誰だ? なんだこれ……このネックレスをどこで見つけたんだ?", "ああ……私がこの首飾りを作った宝石職人だよ。だけどタダで情報を渡す仕事はしてないんだ。情報ってのはタダじゃないんだよ。協力させるつもりなら、まず君が私に協力しないとね。", 0xb1327827, 0xeeb9407b, 0xb9a1fb6d, 0x0b9a539d, 0x82358beb, "....." },
  [2199] = { "価格に見合う知識", "Ironforge の Talvash del Kissel に silver bar 5本を渡して下さい。", "私は Ironforge じゃ広く名の知られた宝石職人なんだ! まあ、「元」だけど……とにかく、競争相手の汚いやり方のせいで落ちぶれたんだ! この商売での悪い評判ってのは、資金繰りに困ることを意味する。結果として、自分の名前が地に落ちて泥にまみれ、一文無しになってるのに気付いたのさ。\n\nsilver barsを5本持ってきてほしい。受けた注文を終わらせたい……本当に久しぶりの注文なんだ。\n\nsilver bars 5本を持ってきてくれたら、首飾りに関する疑問に答えてあげよう。", "頼んでおいた銀の延べ棒5本は持ってきたかい? 君が今持っているネックレスにまつわる、俺の悲しい身の上話を聞かせてやるよ……でも延べ棒を受け取ってからだ! 頼むよ、ノームを助けると思ってさ、な?", "君は見たところ大丈夫だな。誰が何を言おうが私は気にせんよ……ウソ、ウソ! 真面目に、君には感謝してるんだ。\n\nさてと、その首飾りは私の最高傑作なんだけど、魔法の力をとどめるのに使っていた三つの宝石が無くなっているね。それはいつだったか、あるパラディンに作ったものなんだ。彼は Badlands の Uldaman と呼ばれる発掘現場で「邪悪な穢れ」を片付けるために、自ら志願して行ったんだよ。\n\nで……そのパラディンは Uldaman で死んだ。それがまさに私の悲哀の始まりだったんだ。", 0x99934f46, 0x01df1a41, 0xf6b25bc5, 0x5573d0cc, 0x592dece0, "....." },
  [2200] = { "Uldamanへ", "Talvashの首飾りが流通した経路に関する手掛かりをUldamanで探して下さい。殺されたパラディンは首飾りを最後に所持していた人物です。", "商売敵が、私のネックレスがパラディンに呪いをかけたという噂を流したんだ。言うまでもないけど、宝石職人から呪われた品を買いたがる人なんていないよ。\n\n{name}、取引しよう。宝石を見つけてくれたらネックレスを組み直してあげる。その代わり、私は呪われた品なんか絶対に作っていないって宣伝してほしいんだ！\n\nUldamanで手がかりを探してみて。パラディンの遺体がそこにあるか確かめてみるといい。最後にそれを持っていたと分かっているのは彼なんだから！ 宝石を見つけたら、これを使って。ここIronforgeにいる私と連絡が取れるよ。", nil, "パラディンの亡骸。日誌を読むと、そのパラディンは多大な労力の末、失われた3つの宝石すべての在り処を突き止めていたことが分かる。\n\nShadowforgeのドワーフたちは、Uldamanの支配を巡ってTroggと戦う中、ルビーを自分たちの防柵の中に隠した。\n\ntroggたちはトパーズを、Uldamanの風変わりな住人——Allianceのドワーフたち——の近くにある壺に隠した。\n\n最後に、troggの長老自身がサファイアを自分のものとして奪った。", 0x0a4fff55, 0x2968a0a2, 0x8111f254, nil, 0x4fa0e3d8, "...m." },
  [2201] = { "宝石を発見せよ", "Uldamanのあちこちに散らばっているルビー、サファイア、トパーズを見つける。手に入れたら、以前Talvash del Kisselから渡されたPhial of Scryingを使って、離れた場所から彼に連絡して下さい。\n\n日誌から分かっていること……\n\n* ルビーは、バリケードで封鎖されたShadowforgeの区域に隠されている。\n\n* トパーズは、Troggの区域の一つで、Allianceのドワーフたちの近くにある壺の中に隠されている。\n\n* サファイアは、troggの首領Grimlokが自分のものにしている。", "パラディンの日誌は、ネックレスの宝石のありかについてUldamanが与えてくれるおそらく唯一の手がかりとなった。パラディンの書き記したことが今も正確であるならば、発掘現場の支配を争うShadowforgeのドワーフとtroggsに対処する必要があるだろう。\n\nこの知識を手に、宝石の本格的な捜索が始まる。すべての宝石を手に入れたら、Talvashの指示どおり、Phial of Scryingを通じてIronforgeのTalvashに知らせなければならない。", "占い鉢の水面から、Talvashの姿が浮かび上がってくる。\n\n「わあ、まだ生きてたんだ! 宝石は見つかった? 本当にあなたが、私の評判を救ってくれると期待していた人なのかい? お喋りするためだけにphialの力を一回分無駄にしたんじゃないって言ってちょうだい。あれは安くないし、私はもう金銭的にひどく困ってるんだから。", "うむ、確かにそれが3つの宝石だ。よくやった! 残念ながら、君の仕事はまだ完全には終わっていないがね。\n\nいや、騙そうとしているわけじゃないぞ、おかしな{class}だな。これは魔法の装飾品を作る話なんだ——Talvash del Kissel品質の装飾品をね! それに力を与えるには強力な動力源が要る。だが、あのネックレスにはもう与える力が残っていない。", 0xb51d5b0d, 0xf4b144bc, 0x4c6f3add, 0x60210ab2, 0x8762b2b9, "....." },
  [2202] = { "Uldaman リエージェント・ラン", "Magenta Fungus Cap 12個をKargathのJarkal Mossmeldに渡して下さい。", "新しく見つかったmagenta fungus capsという植物の話を聞いたんだ。群生していて、Uldamanの発掘現場の奥深くに生えている。他の場所にもあるかもしれないが、今のところ生えていると分かっているのはそこだけだ。錬金術に使えるかどうか研究したくてね、そこで君の出番というわけだ。\n\nmagenta capの群生を見つけて、capsを12個持ってきてくれ。気をつけて、群生を揺らすと毒の胞子を吹き出すかもしれないよ。\n\nこれをやってくれたら、私の自慢の回復のエリクサーをひと瓶こしらえてあげよう！", "錬金術の研究に必要なmagenta fungus capsは手に入れてくれたかい？capsがなければ報酬もなしだよ！", "よくやった{name}、また己の価値を証明してみせたな! そのcapは興味深い研究対象になるぞ、間違いない。\n\nさて約束どおり、私個人の蓄えから、特に効き目の強い回復薬を一口味わってくれ……\n\n腕のいい錬金術師なら、もう少し取引ができるかもしれんな。いずれにせよ、助力に感謝する!", 0xec9c87f2, 0xb16c00d4, 0xf40372d4, 0x3dc33ca7, 0x81d175bc, "....." },
  [2203] = { "Badlands リエージェント・ラン II", "BadlandsのScorched GuardianにEmpty Thaumaturgy Vesselを使って下さい。容器がいっぱいになったら、KargathのJarkal Mossmeldに渡して下さい。", "あなたには大いに助けられました、{class}。先ほどお渡しした酒のレシピそのものをお礼に差し上げたいのですが……かなり危険な務めをお願いしたいのです。私の頼みを聞いてください。\n\nこの金庫には空の魔術の器が3つ入っています。それには、scorched guardian dragonの血を吸い取る同調のオーラが込められています。あの獣に使うとひどく怒らせることになるので、気をつけてください。3つとも満たしたら、私のところへ持ってきてください。\n\nこれを果たせば、レシピはあなたのものです。", "私が必要としているscorched guardianの竜の血を、容器を使って手に入れてくれたかな? ああ、危険な仕事なのは分かっている……だが私の回復の醸造酒のレシピは、君の成功を待っているのだ。危険と報酬だよ、友よ……危険と報酬……", "一人の錬金術師から錬金術師へ、敬意を表する。さあ、レシピを手に取ってあんたの知識に加えてくれ。長いあいだ成功と報酬とを俺にもたらしてくれたこのレシピが、あんたにも成功と報酬をもたらしますように。", 0x883768bc, 0x12a43ea3, 0x37649b9e, 0x0cf00f74, 0xb7d7a9b7, "....." },
  [2204] = { "首飾りの修復", "Uldamanで見つけた最も強力な石像から動力源を手に入れ、IronforgeのTalvash del Kisselに届けて下さい。", "ネックレスには何か「パンチ」が必要になるね。実はそれには、たぶんUldamanが一番いい場所だよ。あそこには人造兵がたくさんうろついてるんだろ？ だったら、あそこで一番でかくて一番凶悪な人造兵を倒して、その動力源を取ってきて！ その動力源ならネックレスに融合できると、かなり自信があるんだ。\n\nその動力源がなければ、ネックレスを直すのは無理だよ。手に入れたら、ここIronforgeの私のところへ戻ってきて。全部ちゃんと直してあげるから！", "Uldamanを出てから身なりを整えもしなかったんだろう? ダンジョンの臭いが残ってようがお構いなしに、まっすぐここへ来たわけだ。まあ、今回の訪問が臭いだけで済んで、おまけに無駄足にまでならないことを祈ろうじゃないか。\n\nネックレスの動力源は持っているのか?", "これは驚いた——君とこの動力源が無事な姿で見られて何よりだ。宝石が戻ってきた今、動力源とネックレスを魔法で融合させるのに少し時間がかかる。だが、それが済めばネックレスは君のものだ!\n\nわくわくしているだろう? 期待でうずうずしているかな? さて、あの呪文の焦点具をどこに置いたかな……", 0xd9740d79, 0xa02feecf, 0x905848a6, 0xc5dc9fc2, 0xf81ff10a, "....." },
  [2205] = { "SI:7を探せ", "Stormwind BarracksにいるMaster Mathias Shawに、Sylviusからの荷物を届ける。", "バッジ？ ああ、何でもないさ、ひよっこ――どのみちお前の手に負えるもんじゃない。その見た目じゃ、Mathiasはお前をまともなローグじゃなく、チーズの配達係と間違えるだろうな。ともかく、俺は仕事を任されたし、その仕事をやり遂げると約束したんだ。\n\nそういえば、この包みをMathiasに届けてくれ。そうすれば、ちょっとした仕事を一つか二つくれるかもしれない。\n\nさっさと取りかかれ。", "何かご用かな、{class}?", "よくここがわかったな。見たところ、ここを発見するのにすごく体力を消費してしまったようだな。精神的にも肉体的にも疲労が溜まっているぞ。\n\nRenzikに宿屋を案内させようか？それとも、もう任務についてみるか？", 0xcaa7a9f9, 0x07f738a1, 0xfb528bff, 0x01686e7d, 0xde7424bd, ".....", nil, nil, 0x454725db, nil, nil },
  [2206] = { "ひったくり任務", "Defias DockmasterからShipping Scheduleを盗み、Master Mathias Shawに渡す。", "現地の工作員から、Goldshireの南でDefiasの活動が活発になっているとの報告が入っている。報告によれば、DefiasはJerod's Landingを占拠し、RedridgeからWestfallへ大量の禁制品を密輸する拠点として使っているらしい。\n\n波止場の小屋に潜入し、輸送予定表を手に入れてきてほしい、{name}。おそらくDockmasterのポケットの奥深くにしまわれているだろう。\n\n……それから{name}、もし見つかった場合、SI:7は君の存在について一切関知しない。", "兵舎でぶらぶらと時間を無駄にするたびに、お前の定命の身は刻一刻と衰えていくのだぞ、{class}。", "驚いた……Kerynがついに、本物のローグになる素質があるかもしれない新兵を見つけてきたとは、まったく驚きだ。この刃を受け取れ、{name}。いつかまた、SI:7に仕えるよう呼び出される日が来るだろう。腕を磨き、目を開けておけ。そしてその刃も鋭くしておくんだ。\n\n我々が来るのは見えないだろうが、来たときには感じるはずだ……", 0x1787987c, 0x494cbf92, 0xb285531c, 0xcd220e78, 0x0bc8224c, "....." },
  [2218] = { "救済への道", "IronforgeのHulfdan Blackbeardと話して下さい。", "また迷える魂が導きを求めてやって来たってわけか？ 目的を見つけたいんだろう、自分自身の目的をな。千回は見てきたよ、仕事を探すまた一人の英雄ってやつをな。\n\nまあ、今日はついてるぞ、友よ。Hogralがお前さんの悩みに効く薬を持ってる。\n\nやることはこうだ。この道を上ってIronforgeへ行き、Forlorn Cavernへ向かえ。着いたら盗賊ギルドを見つけて、Hulfdan Blackbeardと話すんだ。あいつが救いへの道に乗せてくれる。", nil, "それで、自分は一人前の悪党だとでも思っとるのか? Blackbeardの選ばれし少数の一人——Hidden Circleの士官になる運命だと?\n\nそんなに自惚れるのは、ろくでなしのごろつきくらいのもんだ。\n\nまさにそういう奴を探しとったんだ! ようこそ、{name}!", 0x7deeb917, 0xc16240a1, 0x238604cf, nil, 0x3b3483ab, "...m." },
  [2238] = { "単純な言い訳", "Gnomeregan付近にいるOnin MacHammarを探して下さい。", "いいか、王は鉱石と宝石を求めて石切り場を露天掘りしておるのさ。どんなドワーフだって10回生まれ変わっても拝めないほどの富だ。\n\nHidden Circleにも信条ってもんがある、{name}。わしらは価値あるものに価値を置く。わかるか？\n\nで、わしらは王がそのお宝を少しは分け合うべきだと思っとる。だが「Stinkbeard」の奴には分け合ってると気づかれたくない。わしの言いたいこと、わかるだろ？\n\nGnomereganのそばにいるOnin MacHammarと話して、報告を持ち帰ってほしい。あの抜け目ないドワーフは、lepersの中に身を隠しておる。気をつけるんだぞ。", nil, "シーーーー! 静かにしろよバカ野郎。あいつらに聞こえるだろ。", 0xc34a099a, 0xba2a3a79, 0xad153087, nil, 0xab2bb692, "...m." },
  [2239] = { "Onin's Report", "IronforgeにいるHulfdanのところへOnin's Reportを持ち帰って下さい。", "石切り場か？ ああ、あのばかでかい装甲蒸気戦車がほぼ毎日この詰所のそばを通るのを見てるよ。\n\n東の連絡員によると、戦車はIronforgeを出発して、Gol'Bolar Quarryで荷を積み、Kharanosに立ち寄って燃料を補給し、それからどういうわけか遠回りしてGnomereganを通り過ぎ、Ironforgeに戻って荷を下ろすそうだ。\n\n全部報告書に書いてある、{race}。Hulfdanのところへ持ち帰って、次の手を練ってもらえ。", "leper gnomeの悪臭は楽しかったか? いや、お前さんがやけにおかしな笑みを浮かべとるもんでな。\n\nOninからはどんな知らせを持ってきた?", "長い道のりだと? わしの髭にかけて!\n\nよくやった、{name}。この短剣を持って行きな。段階3を動かす準備が整ったら、Circleがまたお前を呼ぶ。\n\n段階3とは何かって? 段階2のすぐ後に来るものさ——わしの長靴をお前の尻にぶち込むのがな。\n\n興味はあるか?", 0xfee6746a, 0xb2b73a1a, 0x6d453b17, 0x7416d656, 0x6c9c93b3, "....." },
  [2240] = { "隠し部屋", "Baelog's Journalを読み、隠し部屋を探索してProspector Stormpikeに報告して下さい。", "さて、目の前の仕事に取りかかろう。\n\n探索しなければならない秘密の部屋、Chamber of Khaz'mulがある。問題は、その部屋が巨大な鍵のかかった扉の奥にあることだ！ 運のいいことに、私はその開け方を知っている。\n\nすべてこのテーブルの上にある日誌に書いておいた。私の一団と私はしばらくここから動けない……だから{name}、君が私たちの代わりにChamber of Khaz'mulを見つけてくれ！\n\n日誌を読んで部屋を探索したら、IronforgeのExplorers' LeagueにいるProspector Stormpikeに報告してくれ。", "何か報告があるのか?", "Chamber of Khaz'mulを見たのか? 驚いたな! Baelogは存在を確信していたが、正直なところ私は疑っていた。\n\nありがとう、{name}。運が良ければ、君の発見が指導者たちを動かし、Uldaman奪還への努力を新たにさせるだろう。そしてそこが再びIronforgeの支配下に入れば、Chamber of Khaz'mulの秘密は我々のものだ!", 0x715ec1d2, 0x426bb2d5, 0xd19acc6b, 0x0c101615, 0x1bbdd389, "....." },
  [2241] = { "りんごは落ちて", "DarnassusのSyurnaにJannok's Roseを渡して下さい。", "みんな僕のことを『恋煩い』だって言うんだ。それがどういう意味かは知らないけどね。\n\nそりゃあ、起きている間はずっとSyurnaのことを考えてるさ。そりゃあ、僕の家はSyurnaの絵や素描でいっぱいさ。そりゃあ、何日も食べず、眠らず、飲まずに過ごして、手に入ったかもしれない二人の愛を嘆くこともよくある。それってそんなにいけないことかい？\n\nなのに彼女は僕に会ってくれない！ この僕に！ 伝言を送ってみたけど、ローグでもない限り、彼女は誰とも口をきこうとしないんだ。\n\nこの花を彼女に届けてくれないか？ Jannokからだって伝えるのを忘れないでくれよ。", "おや、これは素晴らしい。自分の葬式用の花を持ってきたとはな。", "あの間抜けなJannokが送ってきた花を全部取っておいたなら、店を開けるだけの元手にはなっただろうね。それはともかく、Jannokの最新の使いは役に立ちそうじゃないか。\n\n仕事に興味はあるかしら、{class}?", 0x1e34b4e5, 0x539618ee, 0xb5594b87, 0x9279e6d4, 0x640f88b7, "....." },
  [2242] = { "運命が呼んでいる", "Sethir the Ancientを探し、発見した手掛かりをSyurnaのところへ持ち帰って下さい。", "Teldrassilの森に何が起きているのかを理解する手助けになりそうな存在が一人いると、私たちは考えています。けれども残念ながら、その者に協力させようとする試みは悲惨な結果に終わりました。\n\n彼はOracle Gladeの外れにある枝に隠れています。力ずくであれ交渉であれ、これまでそのsatyrに近づいた者は皆、破滅を迎えました。もしかすると、隠密こそが答えなのかもしれません、{name}。\n\nSethir the Ancientが荷物の中に何を持っているのかを突き止めて、私に報告してください。", "Sethir the Ancientから何か報告はあるか、{name}?", "これは暗い知らせです、{name}。Darkshoreの森と川を蝕んできた病が、我らの故郷をも穢し始めたようです。\n\nあなたはよく尽くしてくれました。ですが、ここであなたにできることはもうありません。Teldrassilへの奉仕の報酬として、この刃を受け取ってください。", 0x8c35f2ae, 0xe9faceef, 0xccf34b01, 0x274bca56, 0x1dda5b8b, "....." },
  [2258] = { "Badlandsの秘薬材料集め", "Buzzard Gizzardsを$N1個、Crag Coyote Fangsを$N2個、Rock Elemental Shardsを$N3個、BadlandsのKargathにいるJarkal Mossmeldのところへ持って行って下さい。", "{name}、その気があるなら、お前さんの力を借りたいんだがね。わしはちょっとは名の知れた錬金術師でな、Badlandsで手に入る試薬を集めるのにお前さんの手を借りたいんじゃ。\n\n在庫を補充するのに、次の品が要る。buzzard gizzardsを五つ、crag coyote fangsを十本、rock elemental shardsを五つだ。言うまでもないが、獣どもそのものから取れる。お前さんが戦う性分じゃないなら、戦う仲間を見つけるといい。\n\nこの品を集めてくれたら、いくらか金を払うよ。どうするね？", "頼んだ物はもう手に入れたかい? その試薬を持ってこない限り、金は払わないよ。", "ああ、よくやってくれた！少なくともしばらくはこれで持つだろう。約束どおり、これが報酬だ。\n\nもし興味があるなら、他にも欲しい試薬がある。ただしそれはUldamanの発掘現場の奥深くでしか見つからない。手に入れるのは簡単ではないが、また手伝ってくれるなら、それに見合うだけの礼はしよう。\n\nぴかぴかの硬貨より良いものかもしれないよ、どうだい？", 0xaca0069d, 0x317ed567, 0x58ee6bec, 0x5be9782d, 0xdcc1d162, "....." },
  [2259] = { "Erion Shadewhisper", "DarnassusのErion Shadewhisperと接触して下さい。", "{name}、心配しなくていい。Syurnaのところへ行かせたりしないから。ErionがCenarion Enclaveで君を待ってる。急いでくれ!", nil, "枝を広げる時がきた。{race}よ……世界がお前を待っている。", 0x372c4f19, 0x1eb27f12, 0x7bffcd48, nil, 0x1d5a0e27, "...m." },
  [2260] = { "Erionの依頼", "Stormwind Cityへ行き、Renzik 'The Shiv'の助言を求めて下さい。", "君の功績の噂は遠く広く伝わっているぞ、{name}。実際、Stormwind Intelligenceが君を名指しで求めてきたほどだ。\n\n道のりは厳しく危険もあるが、SI:$N1のもとで訓練を受ける機会を軽く考えるべきではない。\n\n新たな世界が君を待っている、{name}。StormwindのOld Townへ行き、SI:$N2本部にいるRenzik \"The Shiv\"と話すのだ。", nil, "{name}、SI:7の呼び出しに応えて遙かかなたの海辺から仲間に加わりに来てくれたんだな。だが、あんたの学ぶべきことは多いぞ。", 0x01bdb2d2, 0x370fd4f0, 0xa7be2c4d, nil, 0xd5283d8b, "...m." },
  [2278] = { "プラチナディスク", "stone watcher と話し、stone watcher の持つ古代知識を学んで下さい。stone watcher の提供する知識を学んだら、Discs of Norgannon を起動して下さい。", "宝物室の中心に置かれているのは四枚の巨大なディスクだ。各ディスクは起源不明の無数の印で飾られている。触ると手にしびれが走った。ディスクに触れた直後、巨大なstone watcherの顔が前に出現した。\n\n「ご挨拶つかまつります。私は知識の番人。創造者(The Creators)による Earthen の合成は、この世界のために年代順に記録され Discs of Norgannon の中に収められています。」\n\n今まで未知であった世界の知識という財産を発見したのだ!", "stone watcherの声が、あなたの内なる存在そのものに響き渡るようだ。\n\n「まずDiscs of Norgannonのデータ同化の前提条件を満たさなければなりません。この要件を満たせば、保存されたデータの携帯版を入手することが許可されます。まずこの保管庫内の情報を十分に調べ尽くしてください。」", "stone watcherの指示に従い、Earthen ・troggs・ドワーフの歴史について学んだので再度 Discs of Norgannon にアクセスした。弱く微かな唸りがディスクから聞こえてきた。するとstone watcherは語った。\n\n「ディスクが合成されました。個人用複製ディスクを受け取るには再度ディスクにアクセスして下さい。」", 0xd5650943, 0x2e1dcb31, 0xfcf9c537, 0x065395e0, 0xadf3d52f, "....." },
  [2279] = { "プラチナディスク", "Discs of NorgannonのミニチュアバージョンをIronforgeのExplorers' Leagueへ持って行って下さい。", "再びDiscs of Norgannonに触れると、手がしびれるような感覚がある。だが今回は、ディスクの内部から奇妙な軋むような音が聞こえてくる。\n\n突然、背負い袋が前より重くなった。中を見ると、ディスクの小型版が入っている！\n\n間違いなく、このような品はAzerothの古代史に関心のある者にとって計り知れない価値があるだろう。IronforgeのExplorers' Leagueはまさにそうした集団であり、Alliance中に知られている。彼らならこれを役立ててくれるかもしれない。", "はい、何かご用ですか? 言っておきますが、今はとても忙しいのです。ですが、Explorers' Leagueにとって重大な用件なら、しっかりお聞きしましょう!", "そこに持っているのは……おや、まあ。これをどこで見つけたと?\n\nいや、本当か?\n\n誰に何を話しただと?\n\nいや、本当か!?\n\n素晴らしい{class}よ、君は今年最大の考古学的発見をしたのかもしれん! Godsにかけて、何を言っているんだ、今世紀最大の発見だ! この円盤が私の思っているものなら、我々が探し求めてきたまさにその鍵かもしれん! これはドワーフの魔法で作られしものの正当性を、決定的に一度きりで証明することになるだろう!", 0xd5650943, 0x7540c2d4, 0x73154522, 0x7f85817c, 0xac58b5d8, "....." },
  [2280] = { "プラチナディスク", "Discs of Norgannonのミニチュア版を、Thunder Bluffの賢者の一人のところへ持って行って下さい。", "Discs of Norgannonに再び触れると、手がひりひりとうずく。だが今回は、ディスクの内側から奇妙なきしむような音が聞こえてくる。\n\n突然、背負い袋が前よりも重くなった。中を見ると、ディスクの小型版が入っていた！\n\n間違いなく、この種の品はAzerothの古代の歴史に関心を持つ者にとってはこの上なく貴重なものだろう。Thunder Bluffの賢者たちはまさにそうした歴史家であり、Horde中に知られている。彼らならこれを役立ててくれるかもしれない。", "うむ、若き者よ。そなたが力強い足取りで……固い決意を胸に、我が天幕へと進み入ってくるのが見えるぞ。Hordeにとって重大な件について、我の助言を求めて来たのか? それとも、宇宙の神秘を明かしてほしいのであろうか?", "これはいったい何かね？\n\n見事だ、若き者よ！この円盤からは、大地が長年固く守り続けてきた秘密の気配がする。これらを私のところへ持ってきたのは実に賢明だったな。", 0xd5650943, 0xc11f337c, 0x9fd11efc, 0x69e7ec1f, 0x54c80929, "....." },
  [2281] = { "Redridgeでの待ち合わせ", "Redridge MountainsのLakeshireへ向かい、Luciusと話して下さい。", "今お前を現場に送り出すのは自殺行為だ。Renzikはこれ以上ローグの死体を抱えたくはない。だが心配するな、{name}。Renzikがお前を一人前に鍛えてやる。\n\nRedridge Mountainsへ行き、SI:$N1の協力者であるLuciusという男と話せ。Lakeshireの波止場で、他のいかがわしいろくでなしどもと一緒にうろついているはずだ。", nil, "ああ、だからあんたの指はちょっと太いんだな。心配しなくていいぞ、{name}。俺はあんたより役に立たないコソ泥どもを優秀なローグに変えてきたんだ。", 0x1179ca1d, 0x8ce09cc7, 0x72050bd6, nil, 0xf1b6dc03, "...m." },
  [2282] = { "Alther's Mill", "Lucius's Lockboxを開けてToken of Thieveryを手に入れ、LakeshireにいるLuciusのところへ戻って下さい。", "俺たちはもう何年もここで盗賊を育ててるんだ！ なにしろ、ならず者が皆、この老いぼれLuciusみたいな優雅さと手際を持って生まれてくるわけじゃないからな。\n\nこの道を外れて上っていくとAlther's Millがある。そこに大事なものを入れた箱を置いてある。取ってきてくれ！ そのtokenを持ち帰れば、Certificate of Thieveryがもらえるぞ！", "オークのことを言い忘れてたかな?\n\n製粉所のあたりを嗅ぎ回ってるって話だ。", "こじ開けたってわけか？よくやった、{name}。\n\nこれでお前が死んでも、経験不足のせいではなくお前自身の愚かさのせいだと分かって、俺たちは安心していられる。", 0xe7ba8f99, 0x26100448, 0xb5640ee8, 0xe82c551e, 0x0465ee25, "....." },
  [2283] = { "首飾りの回収", "Uldaman発掘現場で価値のある首飾りを探し、OrgrimmarのDran Droffersのところへ持ってきて下さい。首飾りは損傷しているはずです。", "仕事があるぞ。もっとも、お前にやり遂げる度胸があればの話だがな！\n\nBadlandsの奥にUldamanの発掘現場がある。最近そこで死んだ間抜けなパラディンの話を耳にしてな。なんで俺たちが気にするかっていうと、そいつがすごく価値のあるネックレスを身につけてたからさ。大きな宝石が3つ付いてるらしい。ルビーと、サファイアと、トパーズだ。\n\n要するに、俺たちはそいつが欲しいし、手に入れるためなら銀貨をたんまり払うってことだ。傷んでるかもしれないが、そんなことはどうでもいい。どんな傷だって俺たちが直してやる。", "で、ネックレスは持ってるのか? ネックレスがなけりゃ、俺たちからは銅貨一枚だって出ないぞ!", "うーん、サルベージだ！ここからでもネックレスの匂いがするよ。さあ、そのお宝を見せてもらおうか……\n\nおい、いったい何のつもりだ？このネックレスは宝石がなくなっているじゃないか！俺たちが気づかないとでも思ったのか？宝石がないことくらいMaltonにだって分かるぞ。\n\nまあ、お前が盗んだんじゃないのかもしれん……だがな、宝石のないこのネックレスなんて何の価値もないんだ！お前の仕事はまだ終わっちゃいない、全然な！", 0xd7ab4e5f, 0xfc569f24, 0x086a8e78, 0x1e95a75b, 0x9025e8b5, "....." },
  [2284] = { "首飾りの回収　2回目", "Uldamanの奥で宝石の行方に関する手掛かりを見つけて下さい。", "Maltonが間抜けなのと同じくらい確かに、宝石はまだUldamanのどこかにある。お前はもう一度あそこへ戻って探さなきゃならない。\n\n前にも言ったが、俺たちの情報が正しければ、そのネックレスにはルビー、サファイア、トパーズが付いてるはずだ。見つけてネックレスにはめ込んでくれ。\n\n宝石がどこにあるかって？ 誰にもわからんさ。運がよければ、そのパラディンの死体が見つかるかもしれない。まだ身ぐるみ剥がされてなけりゃ、宝石をまだ身につけてるかもしれないぞ。", nil, "以前Dranが話していたパラディンの亡骸を見つけたようだ。遺体を調べると、彼の日誌らしきものが出てきた。本の状態はひどく、乾いた血が文章の大半を汚している。しかし読み取れる部分も意味をなさない。知る限り、これは人間の言葉で書かれているのだ。\n\nこの本から何かを知りたいのなら、翻訳してもらう必要があるだろう。", 0x8c69a332, 0x9db927d1, 0xd72891ee, nil, 0xc5cbc3fd, "...m." },
  [2298] = { "堂々とした脅し", "Stormwindへ行き、Renzik 'The Shiv'と話して下さい。", "そんなわけで、わしらが第III段階の計画を練り始めようとしたところへ、Magniの石頭どもが二人ばかり乗り込んできて、なんとかいう強盗の話をして、Hidden Circleの連中を何人かしょっぴいていきやがった。\n\nだがな、このBlackbeardに手錠をかけられる奴なんておらん！ 言い合いが激しくなって、どういうわけかお前さんの名前が口から飛び出しちまったのさ！\n\nわしの助言か？ Ironforgeから最初のGryphonに乗ってStormwindへ行け。Old Townに着いたら、わしの古い友人のRenzik \"The Shiv\"と話すんだ。", nil, "Hulfdanのローグを仲間にするのはいいもんだね!", 0xd942bb73, 0xbbb8bc4a, 0x640cf402, nil, 0x4704075e, "...m." },
  [2299] = { "Hulfdanのところへ!", "Ironforgeへ行き、Hulfdan Blackbeardと話して下さい。", "どこに行っていたんだ、{name}？ Hulfdanがあちこち君を探していたぞ。王に投獄されたんじゃないかと思っていたところだ。\n\nできるだけ早くIronforgeへ行ってHulfdanと話してくれ！", nil, "声を落とせ、{name}。衛兵に聞こえるぞ。", 0x612d5545, 0x995810c1, 0x7e2c7b3a, nil, 0x03d4865c, "...m." },
  [2300] = { "SI:7", "Stormwindへ行き、Renzik 'The Shiv'を探し出して下さい。", "Renzikがお前を探していたぞ、新入り。\n\n俺ならMathiasの副官を待たせたりはしないがな。", nil, "仕事にかかる支度はできたかい。それとも、始める前に昼寝が必要かな?", 0x0b3264b7, 0xbbb8bc4a, 0xf9063657, nil, 0x6f885d66, "...m." },
  [2318] = { "日記の翻訳", "パラディンの日記を翻訳できる人を探して下さい。翻訳できそうな人がいる最も近い場所は、BadlandsのKargathです。", "ちょっと行き詰まり、本を理解できる言葉へ翻訳する必要があると分かった。それができる者がいることは確かだが、できそうな者がいる最も近い位置はBadlandsのKargath前哨基地だ。探し始めるには良い場所だろう。", nil, "偉大なる{class}よ、お前がここBadlandsで何をしているかは知っている。俺の言語の才を求めているのだろう。Uldamanで見つけたあのネックレスの部品を探しているな。\n\n驚いたか？驚くことはない。そういうことを知るのが俺の仕事だからな。それより、翻訳した日誌のためにお前が何をするかを話し合おうじゃないか。信じろ、これを翻訳できるのは俺だけだ。\n\nいや、もっといい話がある。Dran Droffersよりいい条件を出してやろう。それでいて、あいつらとの取引も果たせるようにな。興味が出てきただろう？", 0x0fba366a, 0x3f90420d, 0x7bf166bf, nil, 0xd391c145, "...m." },
  [2338] = { "日記の翻訳", "Jarkalに首飾りを貸して下さい。その代わり、彼が日記を翻訳してくれます。", "Droffers and Son Salvageの連中は、ネックレスに魔力を戻せるほど賢くないが、私ならできる。私はただネックレスを研究して、自分でも作れるようになりたいだけなんだ。そのためには、あんたのネックレスが必要だ。貸してくれれば、研究させてもらう時間と引き換えに、あんたのために日誌を翻訳してやろう。あんたが宝石を探している間に、必要なことを学ぶ時間は十分あるはずだ。\n\n簡単な取引だし、誰にも気づかれやしない。どうする？", "考えてくれたんだろう? この取引に乗るなら、お前は賢い{class}だ。お前も俺も望むものを手に入れ、Droffers and Son Salvageの連中は自分たちが望むものを手に入れたと思い込むってわけさ。", "いい取引が分かるやつだな。お前なら頼りになると思っていたよ。\n\n少し待て。呪文を唱えて、人間の言葉をお前に分かる形にすぐ訳してやる。俺は約束を守るトロールだ。Jarkal MossmeldのことはHordeの誰にでも聞いてみろ。さあ、始めるとしよう……", 0x0fba366a, 0x71c6ceb6, 0x1de510c3, 0x7b4404a4, 0x721e2a04, "....." },
  [2339] = { "宝石と動力源を発見せよ", "Uldamanから3つの宝石すべてと、首飾りの動力源を回収し、KargathのJarkal Mossmeldのところへ持って行って下さい。Jarkalは、動力源はUldamanにいる最も強力な構造体が持っているかもしれないと考えています。\n\n日誌から分かっていること……\n\n* ルビーは、バリケードで封鎖されたShadowforgeの区域に隠されている。\n\n* トパーズは、Troggの区域の一つで、Allianceのドワーフたちの近くにある壺の中に隠されている。\n\n* サファイアは、troggの首領Grimlokが自分のものにしている。", "ほら、翻訳した日誌だ。自分で読めるようにしておいた。要点をいえば、ルビーはドワーフが隠し、トパーズはtroggsが隠し、サファイアはGrimlokというtroggが持っているそうだ。\n\nいいか、ネックレスをまた動かすには動力源が必要になる。Dran Droffersはそのことを知らない。手に入れるなら、私ならこうする。Uldamanのできるだけ奥まで行って、そこにいる一番強い構造体を倒すんだ。何であれ、そいつが持っているのは間違いない。\n\n全部集まったら、ここへ戻ってきてくれ！", "宝石と、ネックレスに魔力を再び流し込めるだけの動力源を持っていないなら、またUldamanの深部へ行く羽目になるぞ。\n\n宝石は返してやるから、Orgrimmarのごろつきどもに届けるといい。動力源は俺が預かっておく。そもそもネックレスを動かすのはそいつなんだからな……", "実によくやった、{class}。これで俺たちの横取りの成果がたっぷり実ることになる。ネックレス自体はもう仕上げた。作りの工程を何度でも再現できる自信がある。\n\nだがその前に、お前が宝石とネックレスをOrgrimmarへ持ち帰る前に、特別に用意した呪文であの宝石をざっと分析させてもらう。ほんの少しで済むことだ。", 0x30e6ddb1, 0x28647b79, 0x50d630eb, 0x253eacd6, 0x834beb73, "....." },
  [2340] = { "宝石の配達", "Necklace and Gem SalvageをOrgrimmarのDran Droffersに届けて下さい。", "同じ素材でさえあれば、どんなネックレスの台座と宝石でも使える。だが、ネックレスに魔力を取り戻すのはこの動力源なんだ……たぶんね。\n\n動力源がちゃんと働くなら、あんたのネックレスに必要な宝石は喜んで用意しよう。\n\nOrgrimmarへ行って、Droffers and Son Salvageとの約束を果たしてきな。私たちの取引については口をつぐんでおくんだよ。戻ってきたら、すばらしい驚きを用意しておけるかもしれない。", "おやおや、誰かと思えば! ずいぶんのんびり来たもんだな。俺の時間の無駄にならないことを祈るぜ! 頼んだ物が全部揃ってなけりゃ金は払わないからな。それと、これは信じてくれていい。何もかも二重、三重にチェックさせてもらうぞ!", "うむ、全部揃っているな。なあ、この袋ももらっていいか？だめじゃない？ありがたい、助かるよ！ハッ！\n\nこのネックレスは今までで最高の稼ぎになるぞ！まあそう気を落とすな。どうせお前には似合わなかっただろうしな。またハッ！\n\n取引は取引だ、サルベージの報酬だ、受け取れ。俺たちの商売はこれで一区切りだ。また仕事があるかどうか、後で寄ってみろ。それまでは、失せな！", 0xa6e01d8e, 0x45a474af, 0x9eac5fd0, 0x8e68c5fa, 0xbfd9badc, "....." },
  [2341] = { "首飾りの回収　3回目", "Jarkal Mossmeldが上手くいったかどうか調べるため、Kargathにいる彼の元を訪れて下さい。", "DranとMalton Droffersが新しいサルベージ品を巡って言い争いになり、取引の半分はこれで終了した。KargathのJarkal Mossmeldが特別な報酬を用意して待ってくれている。Badlandsへの旅が最後の仕上げだ。", nil, "お前がくれた動力源は、俺の期待をすべて上回るものだった。お前の分と俺の分のネックレスを作れたうえ、少なくともあと3つ作れるだけ余っている。Droffers and Son Salvageには気づかれないまま、いい値で売れるだろう。\n\nほら、受け取れ、友よ。見事な働きに感謝する……それと、手間をかけた分の特別なものもな。", 0x8c69a333, 0x18d75125, 0x335e1a01, nil, 0xe95ab0ac, "...m." },
  [2342] = { "取り戻された宝物", "UldamanのSouth Common Hallにある収納箱からPatrick Garrettの家宝を手に入れ、UndercityにいるPatrick Garrettに渡して下さい。", "この箒でコウモリの囲いを掃くなど、Garrettの者にふさわしくない！ この忌々しい仕事で少しばかり金を稼いだから、私の境遇を良くするために、それをあなたに払うつもりだ。\n\nGarrett家伝来の武器は、我らGarrettの者が発掘人としてUldamanで働いていた頃から、UldamanのSouth Common Hallにある我が家の箱にしまい込まれている。それがなければ、私は永遠にここに縛られたままだ――文字通りにな――この忌々しいコウモリどもの後始末をしながら。\n\n我が家の宝を取り戻して、私のところへ持ってきてくれ！ 私の生得の権利を取り戻す手助けをしてくれ！", "掃いても掃いても終わらない……このコウモリどもときたら、私と私のほうきを嫌というほど馬鹿にしてくる。どうか、我が家の宝を取り戻したと言ってくれ! 銀貨を出すと言ったじゃないか。それでは足りないのか?!", "ついに――Garrettの名にふさわしい箒だ。俺が払った銀貨の一枚一枚に見合う値打ちがあるとも、本当にな！\n\n聞こえるか、汚らわしいコウモリども？俺は今やGarrett家伝来の武器を手にしたのだ！震えろ、コウモリども、震えるがいい！！", 0x029286ee, 0xda30ae15, 0x53650d5c, 0x18629af4, 0x43d5b24d, "....." },
  [2358] = { "Horns of Nez'ra", "Horns of Nez'raをLakeshireのArantir's Shadowのところへ持ち帰って下さい。", "何年も前、Horns of Nez'raがRavenholdtの館から盗まれた。大陸を越え、海を越えて探し回った末に、ずっとこのちっぽけな獣どもの手にあったと知ったのだ。\n\nHorns of Nez'raを取り戻すまで、出くわすBlackrockのオークを一人残らず斬り捨てろ。hornsを取り戻したら、Lakeshireにいる私を訪ねてこい。\n\nこれを成し遂げれば、お前の名はRavenholdtに知られることになるだろう、{name}。", "悪魔の王子の角は持っているか?", "Ravenholdtにこの遺物を渡さぬことは、己の存在を否定することに等しい。よくやった、ローグよ。お前はいずれRavenholdtの暗殺者たちと肩を並べられるかもしれん。\n\n若いローグとしてDarkshoreを冒険していた頃、戦闘中に活力を回復させる茶を見つけた。長年私の役に立ってきたが、今そのアザミ茶の味をお前に伝えよう。疲れたときに飲むがいい、{name}。そして再び活力をもって戦え！", 0xd52ec603, 0x3b5ab7d3, 0x4584825e, 0xe35c152d, 0x1f0b2efd, "....." },
  [2359] = { "Klavenの塔", "Defias Tower Keyを盗み、Defias Towerに侵入してDuskwood Chestの中身をあばいて下さい。発見した情報はすべてStormwindにいるMathias Shawのところへ持ち帰って下さい。塔に関する洞察を得るには、Kearnen's Journalを読んで下さい。", "もう何週間もこの塔を見張っているの、{name}。最近、Duskwoodから大きな積荷が届いて、それと一緒にあの見張りたちもやって来たわ。\n\nあれが何なのかって？ 私にもさっぱりわからない。一つだけ言えるのは、あれは人間じゃないってことよ。\n\nとにかく、積荷の中には箱があったの。あの化け物たちが守っているのはそれだと思う。棘の生えたゾンビが、私たちに必要なkeyを持っているわ。\n\nそのkeyを手に入れて塔に入り、箱の中身を突き止めて。見つけたものはMathiasのところへ持ち帰ってちょうだい。", "Agent Kearnenから何か知らせは?", "これで、お前とKearnenが塔の外で見たDefiasの手下どもの説明がつくな、{name}。Venture CompanyがDefiasと関わっていることや、Duskwoodから出ていく妙な荷の説明にもなる。\n\nこの本によれば、StranglethornのZanzilのトロールたちは、薬によって死者を蘇らせる方法を見つけたらしい……いや、正確に言えば毒によってだ。\n\n毒をしっかり理解していなければ、お前はSI:7の役には立たん、{name}。不死を生み出す製法が我々の手の届くところにあるならなおさらだ。", 0x7a0fe55b, 0x84c572ed, 0xffbbc189, 0x6bdfdca0, 0xea54e6be, "....." },
  [2360] = { "MathiasとDefias団", "Westfallへ行き、報告するためにAgent Kearnenを探して下さい。", "ちょうどいいところに来た、{name}。SI:$N1の偵察隊が、WestfallでDefiasの活動が異常に活発になっていると報告している。\n\nどうやらDefiasは、Sentinel Hillの南東にある放棄されたAllianceの見張り塔を乗っ取り、Redridgeの補給路から物資を密輸する活動拠点にしているようだ。\n\nWestfallへ行き、Agent Kearnenと接触して状況説明を受けろ。彼女は塔の近くに隠れている。\n\n……それと{name}、もし正体が露見した場合、SI:$N2は君の存在について一切関知しない。", nil, "Mathiasがようやく新しい支援要員を寄越したのね? 彼、悪い知らせを聞く覚悟はできてると思うわ。", 0x105ec7f9, 0x8fda0905, 0xcc62850d, nil, 0x167ae4df, "...m." },
  [2361] = { "首飾りの修復", nil, nil, nil, "このネックレスは喜んでお前にやろう、偉大なる{class}よ。計り知れないほどの働きをしてくれた、それには感謝している。誇りを持って身につけ、誰が作ったのかを大きな声で何度も言ってくれよ！\n\nそれと、本当に呪われてなどいないということも付け加えてくれると助かるな。", 0xd9740d79, nil, nil, nil, 0x00ee2344, ".mmm." },
  [2378] = { "Shattered Handを探せ", "Orgrimmarへ行き、Cleft of ShadowのShenthulと話して下さい。", "お前はDeathstalkersによく仕えてくれた、{name}。だが、そろそろ外の世界へ踏み出す時かもしれん。隠密と欺きの術には素質を見せたが、まだ多くの訓練が必要だ。\n\nDeathstalkersはShattered Handの中に味方を持っている。我らを助けてくれる者たちを探し出せ。OrgrimmarにいるShenthulを訪ねるのだ。", nil, "それで、我らの強力な同盟者がShenthulに寄越してきたのが、お前か? なんてパッとしない……", 0x4edc9e9f, 0xb842824b, 0x66a5c788, nil, 0x38cd9abf, "...m." },
  [2379] = { "Zando'zan", "Cleft of ShadowのZando'zanと話して下さい。", "お前の決意だけでは、我らの前に立ちはだかる障害を乗り越えるには足りん。\n\nZando'zanと話して、Shattered Handの工作員としての訓練を始めるのだ。\n\n隠密と盗みの技を極めて初めて、お前は運命へ向けて次の一歩を踏み出せる。", nil, "Zando'zanは誤解してたと思う。Zando'zan、謝るよ。", 0xb5f8d527, 0x72e5b430, 0x5267d5d0, nil, 0x1bd8647f, "...m." },
  [2380] = { "Orgrimmarへ!", "OrgrimmarのCleft of ShadowにいるShenthulと話して下さい。", "お前は隠密と欺きの達人ではない。だが、それはすべて変えられるし、変わっていくだろう。そのわずかな腕前で上の者たちを感心させたらしいな。偉大なるShenthulが、お前を名指しで呼んでいる。\n\nここから北の道を通ってOrgrimmarへ行き、Cleft of ShadowにいるShenthulと話せ。", nil, "ThrallがHordeにもたらしたいと望む変化を目前にして、Shattered Handが警戒を怠らずにいるのは大切なことなのだ。我らの仲間だけでは、Thrallの支配に打ち勝つには足りないだろう……隠密と欺瞞を習得せねばならん。", 0x2374baca, 0x53b81ad0, 0x7f04c7de, nil, 0x065d936e, "...m." },
  [2381] = { "略奪者からの略奪", "Southsea Treasureを持ってRatchetのWrenix the Wretchedのところに戻ってくること。Wrenix's Gizmotronic ApparatusからE.C.A.CとThieves' Toolsをもらうことを忘れないように。これら二つのアイテムはこのミッションをこなすのに必要になる。\n\n仮に敵対心を持った異常なオウムに攻撃されたら、E.C.A.Cを使え！", "{name}、私はあなたを怖がらせようとは思わないが、southsea treasureを盗むために送り込んだ５人の盗賊はバラバラになって帰ってきました。\n\n海岸線を南に行くと、southsea freebooterの船であるTide Razorを見つけるでしょう。船倉にあるのは、southsea treasure-お宝です。船の二層目は、海賊が盗みの訓練をするための部屋です。\n\n船に乗り込み、宝を盗んで、私のところに戻ってきてください。あなたの盗みの技術を磨く必要があるなら、海賊達の部屋を使ってください。気をつけて！", "まあ、少なくとも体のどこも欠けてはいないようだな。宝は見つかったか?", "信じられない！あり得ない！ただ、ただ驚くだけです！あなたは才能があります、{name}。そうでなければ、あなたは世界一運の良い人です！\n\nあなたの分け前です。あなたは私よりも有効にこれを利用すると確信しています。", 0xee0557f2, 0x3ff88d8f, 0xbebe5cc4, 0x738c0a5e, 0x11243ac4, ".....", nil, nil, nil, nil, 0xe028f305 },
  [2382] = { "RatchetのWrenix", "Ratchetへ行き、Wrenix the Wretchedと話して下さい。", "Zando'zanは見たぞ！ そうだ、その日は来る！ Thrallの死……背中に突き立つ短剣、毒があらゆる血管に染み渡っていく……Zando'zanは喋りすぎた。\n\n{name}！ Zando'zanは{name}に仕事がある！ {name}はCrossroadsの東にあるRatchetへ行き、Wrenix the Wretchedと話さねばならん。行け！", nil, "また別のか? おかしなトロルがオレんとこに寄越してきた最後の5人は、結局サメの餌になったぞ。お前がもうちっとマシにやってくれることを願おうじゃないか。", 0x05456afd, 0x578f4c54, 0xc9799e26, nil, 0xa433399d, "...m." },
  [2383] = { "Simple Parchment", "Simple Parchmentを読み、Valley of TrialsにいるFrangに話しかけて下さい。", "ああ、お前が留守の間に、お前宛ての羊皮紙が届いたぞ、{name}。\n\n時間のあるときに読んでおけ。俺の思い違いでなければ、ウォリアーのトレーナーのFrangからだ。準備ができたら、話があるそうだ。Denの外で、日陰に身を寄せているはずだ。", "そこに持っているのは何だ? parchmentか? まさか学者じゃないだろうな……", "ああ、それは俺の羊皮紙だ。{name}、お前がこの谷に来ていると聞いてな。会えて嬉しいよ……この先にある試練を生き抜いていけることを願おう。さっき言った通り、力をつけたいのなら、俺のとこへ来い……{class}の道において教えられることを教えてやる。\n\n頑張れよ、{name}。準備ができたらいつでも戻ってこい。", 0x1d01cad6, 0x159b5995, 0xb9d4e50a, 0xbf9315ae, 0x818eae1e, "....." },
  [2398] = { "迷子のドワーフ", "UldamanでBaelogを探して下さい。", "Uldamanの発掘現場は、昔から荒らされていたわけじゃない。以前はわしらIronforgeのドワーフがあの一帯を押さえていたんだが……それもtroggsが来るまでの話だ。奴らはあまりに素早く、あまりに大勢で押し寄せたもんで、ドワーフの力をもってしても止められなかった！\n\n実際、奴らの攻撃はあまりに突然だったから、わしらの仲間の何人かが敵陣の向こうに取り残されているんじゃないかと心配しておる。\n\nわしの友人のBaelogが、troggsが現れる直前に、ドワーフの小隊を率いて現場の奥深くへ入っていった。あいつとその仲間が生きているなら、見つけてやってほしい。", nil, "やっと来てくれたか！危うくOlafとの賭けに負けるところだったぞ！\n\nあいつは、次に生きた{race}を見るより先に自分のヒゲが膝まで伸びると賭けたんだ。だがお前がこうして来た。見ての通り、Olafのヒゲはまだ少し足りないな。\n\nありがとう、{name}。賞金は山分けだ。", 0x826b7a46, 0x194d79a7, 0x1cc327cb, nil, 0xc693cc2f, "...m." },
  [2399] = { "芽生えた葉", nil, nil, nil, "Denalan がプランターに植えた葉が芽を出して成長した。葉は震え、抜かれたがっている……。", 0xd9520005, nil, nil, nil, 0x87fc0eaa, ".mmm." },
  [2418] = { "パワーストーン", "Dentrium Power Stone 8つ・An'Alleum Power Stone 8つをBadlandsのRigglefuzzに渡して下さい。", "少し前、Shadowforge Dwarvesとちょっとした揉め事があってね。奴らは私をAngor Fortressへ連れていき、Uldamanで見つかった2種類の奇妙な石を調べさせたんだ。正しく扱えば、その石は持続的で安定した動力源になることがわかった。あの古い発掘現場では驚くようなものが見つかるものだね！\n\nともかく、石の秘密を教えたら、奴らは私をAngor Fortressから追い出して、Uldamanでもっと掘り始めたんだ。\n\nその石は私のものにしたい！ 両方の種類を持ってきてくれたら、たっぷり払うよ！", "power stoneは持ってきたかい、{name}? 動力源が必要なロボットのネズミがいるんだよ……", "すごいぞ、見つけてくれたんだな！本当にありがとう、{name}。今まで会った中で一番頼りになる{race}だよ！\n\nいじっている装置でこれを早く試したくてたまらない。条件さえ整えば、この石で動く装置はいつまでも、いつまでも、動き続けるはずだ……", 0x2a8fd07d, 0xf6808489, 0x69dbb206, 0x8950568a, 0xa4af47c3, "....." },
  [2438] = { "Emerald Dreamcatcher", "Emerald DreamcatcherをDolanaarのTallonkai Swiftrootに渡して下さい。", "私は以前、 Ban'ethil Barrow Denのドルイドの監視人である Gaerolas Talvethen から emerald dreamcatcher を貰いました。\n\nこの強力なお守りはEmerald Dreamからエネルギーを吸い上げ、その持ち主に幸運を与えてくれるという物です。\n\nStarbreeze はかつて静穏な場所でしたが、今ではそこに住む furbolg によって荒らされてしまい、  私は Starbreeze Village のドレッサーからそれを回収できませんでした……。\n\n{class}。\n\nもしよければ、Dreamcatcher を取り戻してきてくれませんか？", "どうか急いでください。私のemerald dreamcatcherがfurbolgに傷つけられていないことを祈るばかりです。\n\nもう取り戻せましたか、{name}?", "dreamcatcher は私にとって数少ない大切な贈り物なのです。\n\n取り戻してくださってありがとうございます、{name}。", 0x15f1c399, 0x52a2d29e, 0xfe33a929, 0x164e94f7, 0x1efbac0d, "....." },
  [2439] = { "プラチナディスク", "報酬引換証(reward voucher)をVault of IronforgeにいるDinita Stonemantleに渡して下さい。", "この品は驚くべき発見だ。古のTitans、このディスクによれば創造主と呼ばれる者たちは、ここに記された伝承が正しければ、我々の魔法に満ちた創造へとつながる鍵なのだ！ これにはできる限り多くの研究時間を注ぎ込まねばならんな。\n\nさて君だ、勇敢なる{class}よ。この引換券を金庫のDinita Stonemantleのところへ持っていきなさい。これほどの大発見にふさわしいと私が考えるものがもらえるはずだ！\n\n準備ができたら、まっすぐ私のところへ戻ってきてくれ。Explorers' Leagueのためにやるべきことはまだたくさんある！", "Vault of Ironforgeへようこそ、{name}。本日はどのようなご用件でしょうか?", "ああ、なるほど、Explorers' Leagueの引換証か……しかも、かなり価値のあるものだと言っておこう。\n\nExplorers' Leagueは、彼らの宝物庫から直接お前に報酬を選ばせる権限を私に与えている。お前はこの品を受け取ることになり、報酬としては5つのsuperior healing potionか5つのgreater mana potionかを選べる。", 0xd5650943, 0x5d43047f, 0x819d9adb, 0xa99640aa, 0x38a04709, "....." },
  [2440] = { "白銀のディスク", "Thunder BluffのBena Winterhoofにreward voucherを渡して下さい。", "私はこのディスクに精力を注ぐつもりです。いずれ、本来の動作も分かることでしょう。\n\n{name}、あなたについては、骨を折って私に知らせて下さったことに報いたいと思っています。この証書をもって、錬金術指導者Bena Winterhoofのところへ行って下さい。特別な良い品をくれるはずです。それと、私が個人的に取り置きしているポーションから、選んだものを提供してくれるでしょう。\n\nすぐ戻ってきて下さい。私が感じているように、この発見について成すべきことはより多く、差し迫っているのです。", "ごきげんよう、{class}! 錬金術の訓練に来たのかな、それとも他の用かな?", "なるほど、{name}。この品をあなたにあげるほどSage Truthseekerは大喜びだったわけですね。あと、彼の備蓄ポーションから贈り物を受け取れます。superior healing potion5つとgreater mana potion5つのどちらかを報酬として選んで下さい。", 0xd5650943, 0x5bcf3865, 0x279b2c71, 0xd39babcd, 0x44a13553, "....." },
  [2458] = { "潜入捜査", "Sludge Fenの北にあるVenture Co. Towerへ行き、Shattered Handの密偵、Taskmaster Fizzuleと接触して下さい。\n\n塔が見えたら、Flare Gunを使ってTaskmaster Fizzuleに到着を知らせて下さい。照明弾を2発撃ち、それからTaskmaster Fizzuleに近づいてShattered Handの敬礼（/salute）をして下さい。\n\nFizzuleは見覚えのない者を攻撃して始末してしまうので、これらの行動は正しい順番で行わなければなりません。", "Venture Company……聞いたことがあるか？\n\n我らは1年がかりで、奴らの組織の奥深くに工作員を送り込もうとしてきた。多大な努力と周到な計画の末、それに成功した。\n\n最近、Venture Co.が大規模な何かを計画しているという知らせが届いた。Sludge Fenの北にあるVenture Co.の塔へ行き、潜入工作員のTaskmaster Fizzuleと接触しろ。\n\n塔を見つけたら、このflare gunを使え。それからFizzuleに近づき、Shattered Handの敬礼をして見せるのだ。", nil, "この辺りでShattered Handのもう一人の工作員に会えるのは嬉しいが、あの信号弾は少しやりすぎだったかもしれんな！\n\n次に私と話す必要があるときは、この笛を二度吹け。そうすればお前が味方だと分かる。", 0x379ff3f0, 0x8c974479, 0x9977ca74, nil, 0xc03a9821, "...m." },
  [2459] = { "Ferocitas the Dream Eater", "Gnarlpine Mystic 7頭を殺し、Missing Jewelを見つけて下さい。", "エメラルドが……なくなっている！私のドリームキャッチャーが傷つけられてしまいました！\n\nStarbreezeの北に、Gnarlpineの神秘家の一団がいます。その首領であるFerocitas the Dream Eaterが、夜に緑色に光る首飾りを身につけているという報告を聞きました。こうしてドリームキャッチャーを見て、彼が私のエメラルドを盗んだのだと確信しました……その力が彼には何の役にも立たないということに、彼は決して気づかないでしょう。\n\nなくなった宝石を探してください、{name}。それと、そこにいる間に、堕落した神秘家たちも何体か片付けてください。", "FerocitasとGnarlpine mysticたちは、私のものを返さねばなりません。どうかエメラルドを取り戻してください。そうすれば私のemerald dreamcatcherを直せるのです。", "これでdreamcatcherを直せます。ありがとうございます、{name} 。", 0x236ef724, 0x4c50de14, 0x837c9efe, 0x9c2bf253, 0x00d792cf, "....." },
  [2460] = { "Shattered Salute", "ShenthulにShattered Saluteを行って下さい。", "Shattered Handのローグとして、Shattered Saluteを身につけることは不可欠だ。それが、Handの仲間を確かに見分ける唯一の方法なのだ。\n\n見て、覚えて、繰り返せ。", "練習だ!", "よくできたぞ、{name}。次に進む準備ができたようだな。", 0xe29bc468, 0xbc1b393c, 0x21bdbb05, 0xa5a697be, 0xc8d80fd4, "....." },
  [2478] = { "ミッション: 可能だが望み薄", "Foreman SilixizからSilixiz's Tower Keyを盗み、Mutated Venture Co. Dronesを2体、Venture Co. Patrollersを2体、Venture Co. Lookoutsを2体倒す。\n\nGrand Foreman Gallywixを暗殺してその首を取り、Gallywixの手提げ金庫の錠を開けてCache of Zanzil's Altered Mixtureを盗む。CacheとGallywix's HeadをOrgrimmarのShenthulのところへ持ち帰り、次の指示を受けて下さい。", "Foreman Silixizからtower keyを盗み出さねばならん、{name}。keyを手に入れたら、持っておけ。後で必要になるかもしれん。\n\n忘れるな、毒がこの塔のあらゆるものを弱らせている。お前の能力を使って、住人どもに混乱と破壊をもたらせ。皆殺しにしろ――情けはかけるな！\n\n中の者どもが皆、血まみれの山になったら、Gallywixの錠前箱をこじ開けて、中にあるcache of Zanzil's mixtureを盗め。Gallywixの首とmixtureの両方を、OrgrimmarのShenthulのところへ持っていけ。", "何か報告はあるか、{name}?", "気の毒なFizzule、彼は良い工作員だった。我々の中でも指折りのな。だが、それが我々の払う代償なのだ、{name}。Shattered Handの現地工作員であるということは危険な仕事だ。\n\nお前は務めをよく果たした、{class}。再び我々のために働けぬまま死なれては惜しいからな。", 0x889d9a10, 0x323252b6, 0xc695e02b, 0xd8f33c29, 0x2c36763c, "....." },
  [2479] = { "Hinottの手伝い", "Hillsbrad FoothillsのTarren Millへ行き、Sample of Zanzil's MixtureをSerge Hinottに届けて下さい。\n\nTarren Millへ行くには、ZeppelinでUndercityへ行き、道を南へ進んでSilverpineを抜け、Hillsbradへ向かって下さい。標識に従って下さい!", "mixtureのサンプルをTarren MillのSerge Hinottのところへ持っていけ。\n\nお前を治せる者がいるとすれば、それはSergeだ。それまで生き延びられれば、Sergeが毒の作り方と使い方を教えてくれるだろう。", "これは何だ???", "気持ちいいほど青ざめているぞ、{class}。あと、お前が放っているこの気色悪い臭いは何だ? 教えろ!", 0x59895e49, 0xe1eb607d, 0x1bcf7a9f, 0x1de2dddb, 0x558ebfce, "....." },
  [2480] = { "Hinottの手伝い", "Serge Hinottが治療を終えるまで待って下さい。", "毒がこれほど見事な効果を上げるのは見たことがない！ Zanzilと言ったか？ 聞いたことのない名だが、この調合物を作り上げたことは称えねばなるまい。\n\nそれで、私はお前を治療し、そのうえでこの毒の使い方を教えればいいのだな？\n\n毒素を調べるから少し時間をくれ、{name}。", nil, "治療薬ができたぞ! この解毒薬を飲めば、緩効性の錯乱も収まるだろう。だが、その臭いに関しては何もしてやれんぞ。", 0x59895e49, 0xd6da9379, 0x9ead8b00, nil, 0x37216e45, "...m." },
  [2498] = { "Denalanのもとへ", "Lake Al'AmethのDenalanと話してほしいとRellian Greenspyreは言っています。", "Lake Al'AmethにいるDenalanが、timberlingを苦しめている腫瘍の原因かもしれないものを突き止めたと、たった今知らせがありました。彼と話して、私の紹介で来たと伝えてください。\n\n急いでください、{name}。彼には私たちの助けが必要なのです。", nil, "ああ、Rellianが私を助けるためにあなたを遣わしたのですね。こんなに早く来てくれて嬉しいです。\n\n実に不穏なことを発見したのです！", 0x86434b8b, 0x01cfe979, 0x16e96e4d, nil, 0xbdb97620, "...m." },
  [2499] = { "Oakenscowl", "Oakenscowl から Gargantuan Tumor を手に入れて下さい。", "湖の南岸沿いの洞窟で、Oakenscowlという名のtimberlingが、Lake Al'Amethをすみかとするあらゆる生き物に堕落を広めています。\n\n私はあまり近づく勇気がありませんでしたが、遠くからでも明らかでした。Oakenscowlは、私がこれまでに見た中で最も大きな腫瘍に毒されているのです……巨大と言ってもいいほどです。\n\n{name}、あなたはすでに私の取り組みに大いに力を貸してくれましたが、もう一つだけお願いがあります。Oakenscowlを追い詰めて、その腫瘍を取ってきてください。私のすみかからこの堕落の源を取り除いてほしいのです。", "もうOakenscowlは見つけたか、{race}?", "君には湖の恐ろしい化け物を取り除く以上の力があると分かってたよ。\n\n悩ましい状況だな。Oakenscowl は timberling の偉大な指導者だった……しかし穢れは地位の上下などお構いなしだ。\n\nこのサイズの腫瘍は実に不安なものだが、timberling の生息数を狂わせる病を詳しく知るには、これを研究しなくてはならん。\n\nありがとう、{name} 。", 0xa9dba359, 0x0d86e120, 0x1f483fdc, 0x5c25b955, 0x92662c82, "....." },
  [2500] = { "Badlandsの秘薬材料集め", "Ghak Healtouchが必要としている秘薬の材料をBadlandsで手に入れ、Thelsamarの彼のところへ戻って下さい。", "{class}、お前さんの腕を借りたい。わしはちょっとは名の知れた錬金術師でな、Badlandsで手に入る試薬を集めるのにお前さんの手を借りたいんじゃ。\n\n在庫を補充するのに、次の品が要る。buzzard gizzardsを五つ、crag coyote fangsを十本、rock elemental shardsを五つだ。言うまでもないが、獣どもそのものから取れる。お前さんが戦う性分じゃないなら、戦う仲間を見つけるといい。\n\nこの品を集めてくれたら、いくらか金を払うよ。\n\nさて、どうするね？", "頼んだ物はもう手に入れたかい? その試薬を持ってこない限り、金は払わないよ。", "ああ、よくやってくれた、{name}。少なくともしばらくはこれで持つだろう。約束どおり、これが報酬だ。\n\nもし興味があるなら、他にも欲しい試薬がある。ただしそれはUldamanの発掘現場の奥深くでしか見つからない。手に入れるのは簡単ではないが、また手伝ってくれるなら、それに見合うだけの礼はしよう。\n\nぴかぴかの硬貨より良いものかもしれないよ、どうだい？", 0xaca0069d, 0xf4c53465, 0xe9758759, 0x5be9782d, 0xf953efd3, "....." },
  [2501] = { "Badlands リエージェント・ラン II", "BadlandsのScorched GuardianにEmpty Thaumaturgy Vesselを使って下さい。容器がいっぱいになったら、ThelsamarのGhak Healtouchに渡して下さい。", "あなたには大いに助けていただきました、{name}。以前お渡しした醸造酒のレシピそのものをお礼に差し上げたいのですが、その前に、かなり危険なお願いをしなければなりません。\n\nこの錠前箱には、空の魔術容器が3つ入っています。これらには同調のオーラが込められていて、灼熱の守護竜の血を吸い取ることができます。その獣に使えばひどく怒らせることになるので、気をつけてください。3つすべてを満たしたら、私のところへ持ってきてください。\n\nこれをやり遂げてくだされば、レシピはあなたのものです。", "私が必要としているscorched guardianの竜の血を、容器を使って手に入れてくれたかな? ああ、危険な仕事なのは分かっている……だが私の回復の醸造酒のレシピは、君の成功を待っているのだ。危険と報酬だよ、友よ……危険と報酬……", "一人の錬金術師から錬金術師へ、敬意を表する。さあ、レシピを手に取って君の知識に加えてくれ。長いあいだ成功と報酬とを私にもたらしてくれたこのレシピが、君にも成功と報酬をもたらしますように!", 0x883768bc, 0xb97f5a02, 0x928aded5, 0x0cf00f74, 0xb7d7a9aa, "....." },
  [2518] = { "月の涙", "Lady SathrahのSilvery Spinneretsを取り戻して下さい。", "Lady Sathrahはかつて女神Eluneの愛し子でした。優美で清らかな蜘蛛Sathrahは月明かりの下で銀の糸を紡ぎ、夜露を集めていました。その銀色の雫は強い癒しの力を持っており、近くの神殿に収められていたのです。\n\nところが最近、Sathrahは狂気に身を落としてしまいました。Sathrahの子孫も今同じように危機に瀕しています。\n\n{name}、Lady Sathrahを見つけて、その苦しみを終わらせて下さい。SathrahはTeldrassilの北の境、Wellspring Lakeの近くに住んでいます。SathrahのSilvery Spinneretsを手に入れて、私のところへ持ってきて下さい。", "あなたにこの務めを頼んだことを悔やんでいます。ですが、Lady Sathrahにはもう望みがないのです。\n\n私たちは、糸疣を捧げ物としてEluneに捧げたいと願っています。この捧げ物によって、EluneがSathrahを祝福し、彼女が生まれ変わって安らぎを得られるように。", "森がLady Sathrahの死を悼んでいます。けれど、やらねばならなかったことなのです。\n\nありがとうございます、{name}。", 0x590caf7f, 0x6c622142, 0x20922da4, 0x35d5c5a2, 0x309445ea, "....." },
  [2519] = { "Temple of the Moon", "Sister Aquinneが、Temple of the MoonにいるPriestess A'mooraに会って話すよう依頼しています。", "{race}よ、森に住まう偉大なる生物であったものが危機に瀕しています。\n\n困難な使命ですが、誰かが為さねばなりません。\n\nPriestess A'mooraさまにお会いください。事情をお話しくださるでしょう。ここから南東にあるTemple of the Moonにおいでのはずです。", nil, "Sister Aquinneがあなたを遣したのですね。", 0xbf995b33, 0xfccb6f52, 0xb532fd45, nil, 0x4f3a53a8, "...m." },
  [2520] = { "Sathrah's Sacrifice", "Priestess A'mooraが、Lady Sathrahのsilvery spinneretsを寺院の泉に浸して戻ってくるよう依頼しています。", "使命を完遂させるのです。そのspinneretsを用い、Lady Sathrahの死をEluneに捧げなさい。そして偉大なる蜘蛛に平穏をもたらすのです。\n\n寺院の中央に泉があります。そこで捧げると良いでしょう。Sathrahを狂気に堕とした穢れも聖水により清められます。\n\nそれが終わったら私のところへお戻りなさい。", "泉に捧げ物を置いてきてくれましたか、{name}?", "Lady Sathrahを亡くしたのは悲しい出来事でした。しかし彼女が新しい生命として生まれ変わる、これが唯一の方法だったのですよ。\n\nあなたの捧げた彼女の命を、Eluneが迎え入れてくださいますよう。", 0x5a3cb37c, 0x6736b09f, 0x7b40ee6c, 0xf5b1c4b7, 0xbd5ac00f, "....." },
  [2521] = { "Kum'ishaに仕える", "Blasted Landsを旅する中でFlawless Draenethyst Sphereを見つけることがあれば、その品をKum'isha the Collectorのところへ持ち帰って下さい。\n\n注意すること。この宝石はAzeroth全土でも最も希少な水晶の一つだ。この地のどんな生き物がFlawless Draenethyst Sphereを持っていてもおかしくない。\n\n集めたFlawless Draenethyst Sphere一つごとに報酬がもらえます。", "{race}よ、お前のちっぽけな脳みそで、flawless sphere of draenethystがどれほど稀少か理解できるか？ Draeneiはたった一つのその結晶を探して生涯を費やし、目的を果たせぬまま、恐ろしい最期を遂げてきたのだ。\n\nそれでもお前は、Kum'ishaが何を求めているか知ったうえでKum'ishaの前に立ち、なお力を貸したいというのか？ よかろう、{race}よ……この地を旅する間にいつでも、flawless sphere of draenethystを見つけたなら、我のもとへ持ってくるがよい。そうすれば、お前の想像をはるかに超える富で報いよう。", "私はflawless draenethyst sphereの探索に人生を捧げてきたのだ。一生だぞ、{race}!", "私の目は欺かれているのか？ありえない！どこでそれを……どうやって……\n\nこれで裂け目を開き、我らの故郷へ戻れるかもしれない。", 0x81cce1f7, 0x009332b5, 0xa4c5c9f1, 0x71ae7976, 0xf92902be, "....." },
  [2541] = { "眠れるドルイド", "Ban'ethil Barrow Den にいる Oben Rageclaw に Shaman Voodoo Charm を渡して下さい。", "眠っているドルイドの精神を肉体から切り離す方法を、ここに住む Gnarlpine 族のシャーマンが見つけたのだ。furbolgは私の体を操り、Ban'ethil Barrow Den を探索せんとする者を襲うのに用いている。私は今 Emerald Dream で動けず、止めることができない。\n\nどうか手を貸してくれ。Gnarlpine 族のシャーマンが持ち歩いている奇妙な護符はこの儀式を行うために使われている。それを調べたいのだ。頼む、{name} 。ひとつ持ってきてくれ。", "charmを調べることができれば、魔法を解く方法が分かるかもしれない。見つけてきてくれたか?", "ありがとう、{name} 。\n\nなんて奇妙な品なんだ……発せられている邪悪なオーラが感じられる。これはとても強力な魔法だよ。", 0xf13c0bd8, 0xb6182866, 0xcd3565db, 0x8fcb5c05, 0x37128c11, "....." },
  [2561] = { "鉤爪のドルイド", "魂を失った Oben Rageclaw の肉体を滅ぼし、Voodoo Charm を使って下さい。", "この護符を調べて、{name}、何をすべきかが分かりました。どうかこれを受け取って、私の言うとおりにしてください。\n\nBan'ethil Barrow Denの最も深い場所を探索してください。そこで魂の抜けた私の体が見つかるはずです……これから言うことは心苦しいのですが、Gnarlpineの支配から自らを解き放つには、ほかに方法がないのです。\n\n彼らから逃れるために、あなたは私の肉体を殺さなければなりません。それが済んだら、倒れた私の体にvoodoo charmを使ってください。この務めを果たしたら、私のもとへ戻ってきてください。", "{name}、私の肉体に近づく時は用心してくれ。それにかけられている魔法はかなり強力なのだ。", "ついに Gnarlpine 族の支配から自由になった。ありがとう、{name} 。\n\n私の精神は永遠に Emerald Dream で安らかに眠れる。\n\nいつかまた会うかもしれないな、若き {class} よ。だが、今はひとまずこれを感謝の印として受け取って欲しい。", 0xdcee0406, 0x31a8c3fe, 0x9102b8db, 0x56e2ee75, 0x992edece, "....." },
  [2581] = { "Snickerfang Jowls", "Snickerfang Jowlsを三つ、Blasted Boar Lungsを二つ、Scorpok Pincerを一つ、Bloodmage Drazialのところへ持って行って下さい。", "ハイエナの顎にとてつもない力があることはよく知られた事実です。しかし、三インチもの厚さのthorium鋼を噛み砕くほどの力とは？ ありえない、ありそうもない。それなのに、私は自分の目でそれを見たのです。\n\nBlasted Landsへ踏み出して、snickerfang jowlsを三つ持ってきてください。snickerfangを探す間、boarsとscorpoksにも目を光らせていてください。最初の分析を完成させるには、blasted boar lungsが二つとscorpok pincerが一つ必要なのです。", "ひどい臭いだな、{name}。硫黄の原でもうろついていたのか? それで、私の材料はどこだ?!", "気分はどうだ、{name}？snickerfangのオーラがお前から放たれている……お前の力は、定命の者には並ぶものがない！\n\n残念ながら、持ってきてくれた材料では、錠剤1つ分の調合薬しか作れなかった。もう一つ錠剤が欲しいなら、さらに材料が必要だ。", 0xf7f16d26, 0xb51443a6, 0x3ee63bcd, 0xd475d33e, 0x0973a15f, "....." },
  [2583] = { "猪の生命力", "Blasted Boar Lungsを三つ、Scorpok Pincersを二つ、Basilisk Brainを一つ、Bloodmage Drazialのところへ持って行って下さい。", "このblasted landsには、二種類のboarが棲んでいます。ash-mane boarとhelboarです。\n\nこの獣たちの持久力は、彼らをほとんど傷つかないものにしているようです。他の動物たちは彼らを殺すのが難しすぎると感じ、その結果、苦労するだけの価値がないと見ているのです。\n\nさらに分析をしなければなりません、{name}。blasted boar lungsを三つ、scorpok pincersを二つ、basilisk brainを一つ持ってきてくれたら、分析の残りかすから神聖なエリクサーを作りましょう。あなたが私の最初の被験者です！", "臓器はどこだ、{name}!?", "boarの精気がお前の身を照らしているぞ、{name}！どうだ、お前は自分がこの獣たちと同じくらい不死身だと思うか？", 0x9a4e1685, 0x97393e8f, 0x2a64bd84, 0x307f3aa2, 0x73abbfa6, "....." },
  [2585] = { "決定打を放つ者", "Scorpok Pincersを三つ、Vulture Gizzardsを二つ、Blasted Boar Lungを一つ、Bloodmage Drazialのところへ持って行って下さい。", "戦っている彼らを見たことがありますか、{name}？ scorpoksのことです。彼らの動きの優雅さと敏捷さを見たことは？ その一撃の迷いのなさを？\n\nあの敏捷さをどうにかして取り出し、閉じ込めることができれば、我々は想像も及ばぬほどの富を……いえ、その……科学界にとって大きな恩恵となるでしょう。\n\n私を手伝ってください、{name}。そうすれば分析の試料を少し分けてあげましょう。\n\n安定した試料を作るには、scorpok pincersを三つ、vulture gizzardsを二つ、blasted boar lungを一つ必要とします。", "臓器はどこだ、{name}!?", "興味深い。これは全ての調合の中で最も分析が難しいものだった。\n\nこの残留塩をひとつまみ取って、舌の下に置くといい。軽い高揚感に続いて、かつてない敏捷さと素早さを感じるはずだ。", 0x0a859cb2, 0xab76c31d, 0xc7ff6f5a, 0x307f3aa2, 0xf5293056, "....." },
  [2601] = { "Basiliskの牙", "Basilisk Brainsを十個とVulture Gizzardsを二つ、Bloodmage Lynnoreのところへ持って行って下さい。", "この荒れ地にはredstone basiliskがうようよしています、{name}。このbasiliskたちは、この地域の他のどんな野生生物よりもうまく適応し、繁栄してきたのです。\n\n私は遠くから、彼らが狩りをし、日々の営みを送る様子を観察してきました。この獣たちは、一部の人型の種族よりも複雑な思考をしているのです。\n\n彼らのbrainsを研究しなければなりません！\n\nbrainsを十個取ってきてください、{name}。ただし、溶液の基剤となるvulture gizzardsが二つなければ、この調合物は完成しません。", "頼んだ臓器を持って戻ってきたのか?", "これは素晴らしい、{name}！私からの贈り物は、redstone basiliskの内なる働きを味わえるものだ。\n\nこの調合物が気に入ったら、いつでもまた作れる……代価次第でな。", 0x20ee9432, 0xa6edac7a, 0xafb93fc0, 0x7cfd6e6c, 0x0b5fda6b, "....." },
  [2603] = { "ハゲワシの活力", "Vulture Gizzardsを十個とSnickerfang Jowlsを二つ、Bloodmage Lynnoreのところへ持って行って下さい。", "このblasted landsでは、死はまさに翼を持っています、{race}。black slayersやbonepickersが、倒れた探検者の亡骸をむさぼるのを私は目にしてきました。時には、最もおぞましく病に冒された死骸さえ食らうのです。とすれば、この地を蝕む疫病に、彼らの体内の仕組みがどうやって打ち勝っているのか、驚くべきことです。\n\n私の研究を手伝ってください、{name}！ gizzardsが必要なのです！ 調合物の基剤には、snickerfang jowlsも二つ必要になります。\n\nあなたの努力には二倍の報酬で報いましょう。", "私の時間を無駄にするな、{name}。頼んだ品を取り戻してきたのでなければ、話すことは何もない。", "実に素晴らしい！すぐに取りかかろう。世の多くの病を癒す薬が見つかるかもしれん！\n\nああそうだ、報酬だな……もちろん、ガムがもっと必要なら、私のところへ戻ってくるといい。また別の仕事を与えよう。", 0xf578d486, 0x341217f6, 0x95cfa89c, 0xb053bb62, 0x33e80ed6, "....." },
  [2605] = { "からからのゴブリン", "Laden Dew Glandを集め、GadgetzanのMarin Noggenfoggerに渡して下さい。", "いい考えがあるんだ。南西にdew collectorsっていう妙な生き物が住んでいるって聞いたんだけど……そいつらは特別な腺に水を蓄えられるんだってさ。\n\nそのglandsの一つが手に入れば、このひどい喉の渇きを癒やす飲み物が作れると思うんだ！ 手伝ってくれるかい、{name}？\n\nサボテン園を探してくれ、{name}。そこにdew collectorsがいるよ。", "頼むよ、dew collectorを見つけたって言ってくれるかい?", "おお、素晴らしい! 渡してくれ……飲ませろ!", 0x805d477a, 0xa5a9ca3d, 0xbd452d01, 0x899d1b38, 0x4e1b216e, "....." },
  [2606] = { "いい趣味", "Marin NoggenfoggerはGadgetzanのSprinkleと話すよう求めています。", "うえっ！ こいつはひどい味だ！ この考えもこれまでか……\n\n待てよ、なんだって？ ああ、わかってる、わかってるよ、これを諦めるべきじゃないって思ってるんだろ。じゃあ、わかったよ。\n\nうーん、いい考えがある！ 名案だ！ この露を僕の友達のSprinkleのところへ持っていってくれ――彼女は腕のいい料理人なんだ。僕らがここで何をしようとしているか話して、もう少し飲みやすくしたいって伝えてくれ。\n\nつまりさ、こんなにひどい味なら、せめてちょっとはガツンとくるものがあるべきだろ……なのに全然感じないんだよ……", "老いぼれMarinがまたやらかしてるってわけか、え? この調合物は何でできてるんだ?", "Marinは悪いやつじゃない、誤解しないでくれ。ただ少し……変わり者だとは言えるがな。\n\nそしてもちろん、またしても私の助けが要るというわけだ。", 0x82179d87, 0x0808dc2a, 0xd3943384, 0x956f77b1, 0x5fbd62fd, "....." },
  [2607] = { "The Touch of Zanzil", "Barracksの地下室にいるDoc Mixilpixilと話して下さい。", "どうやら、私が期待していた以上の情報を持ち帰ってきたようだな。これは確かに奇妙な成り行きだ、{name}。\n\n治療法？ ふむ……地下室へ行ってDoc Mixilpixilと話してみろ。彼なら力になれるかもしれん。", nil, "そろそろ来ると思ってたぞ! そこのテーブルにチーズを置いて出ていきな。帰りがけにOsborneが払ってくれるだろ。", 0x11470d66, 0xad163fb8, 0x32b769f3, nil, 0x006a9227, "...m." },
  [2608] = { "The Touch of Zanzil", "Doc Mixilpixilの診察を受けるために横になって(/Lay)下さい。彼が原因を見つけられなければ、どうやって治療薬を見つけられましょうか?", "おやまあ、死人みたいな顔をしているね。訂正しよう――死なら見たことがあるが、君は死よりもひどい顔だ。君はさしずめ、死神が最後の健康診断で吐き出したものってところだな。\n\nハハ！ 聞いたかい、Noarm？ 今のを書き留めておいてくれ！\n\n*ゴホン* うむ、そうだ、君を助けるためには血を採らなければならない。心配いらない、痛いのは最初の数回……まあ50回かそこらだけだ……治療の準備ができたら/layで横になってくれ、{name}。", "検査の準備ができたら、/lay で地面に横になってくれ。瀉血を始めるから。", "{name}、同僚と相談するからちょっと待っててくれ。Dr. Montgomery、Mr. Noarm、始めましょう!", 0x11470d66, 0xc7da4c18, 0x83e14b94, 0x27c52fde, 0x5baee4be, ".....", nil, nil, 0x0305c147, nil, nil },
  [2609] = { "The Touch of Zanzil", "Simple Wildflowers ひと束・Leaded Vial 1本・Bronze Tube 1本・Spool of Light Chartreuse Silk Thread ひと巻きをDoc Mixilpixilに渡して下さい。「熱」が勝手に治ることはありません。", "満場一致だ、{name}。君は『なんとか炎』にかかっている。\n\n幸い、私は『なんとか炎』の治療法を持っている。\n\n必要なのはこれだ。simple wildflowersを1束、leaded vialを1つ、bronze tubeを1本、そして最後に大事なのが、light chartreuse silk threadを1巻き。老Emmaが『The Finest Thread』に一巻き置いていってくれた。店は運河沿いにあるよ。\n\nさあ急いで、{name}。治るまでは誰にも触らないようにね。ああ、それとDr. Montgomeryが、君はシャワーを浴びる必要があると言っているよ――彼の言葉だ、私のじゃない。", "'itis'を治したいなら、それじゃ努力が足りないよ、{name}。治療のための試薬はどこだい?", "何をしているかって？何をしているように見える？君の「イタイタ病」の治療薬を作っているんだよ！今さら怒らないでくれ、{name}！\n\nあと数秒だ。よし！この、えーと、素晴らしい匂いの薬を自分に吹きかければ、すっかり元通りになるさ。", 0x11470d66, 0xd6faf98a, 0xdeee9d37, 0x82beeccc, 0xfb99b7cf, ".....", nil, 0x6c5f6143, nil, nil, nil },
  [2621] = { "不名誉な者", "StonardのDispatch Commander Ruagと話して下さい。", "後悔。今の私にあるのはそれだけだ。一つの誤った判断が、いくつもの恐ろしい結果を招いた。あの命令書を待ってさえいれば。そこには、あの呪われた地で我々を待ち受けていた恐怖が詳しく書かれていたかもしれん！ 我々を別の任務へ振り向けるものだったかもしれん！ 結局のところ、私のせいだ。すべて私のせいなのだ。\n\nだから私はここに立ち、命令書を待っている。知らねばならん。あの命令書がどうしても要るのだ。\n\nDispatch Commander RuagはStonardにいる。彼を探し、命令書がどうなったのか突き止めてくれ。", nil, "Thrall's Grasp……あの話は今も私の心に鮮明に残っている。\n\n<Commander Ruagは首を振る。>\n\nあの連隊に起きたことは恐ろしいものだった。あの大隊が壊滅したとき、Hordeは最も優れた兵士たちの一部を失ったのだ。", 0xbda27292, 0x0b66b2f4, 0xcd14fa37, nil, 0xcac5f462, "...m." },
  [2622] = { "消えた命令書", "Bengorと話して下さい。", "命令書だと？ 命令書などを一体どうしようというのだ？\n\n何が言いたい、{name}？ 当然、あの命令書は伝えたとも！ 命令書を持たせて送り出した兵たちが、murlocsに待ち伏せされ、ひどく痛めつけられたのだ。生き残ったのは一人だけ、あれを生き残ったと言えるのならな。ろくに話せず、歩けず、管で食事を流し込まねばならん。命令書がどうなったか知りたいなら、Bengorと話せ。どこかこの辺りにいるはずだ……それから、{name}、何に首を突っ込むかには気をつけることだ。その鼻を噛みちぎられるかもしれんぞ。", nil, "Swamp tal……talk……talker……だ……", 0x2d77d470, 0x9bcc00ad, 0x8684ebe3, nil, 0xb47cdba1, "...m." },
  [2623] = { "沼地の語り手", "Warchief's Ordersを回収し、Fallen Hero of the Hordeのところへ持ち帰って下さい。", "命令書、伝令の司令官から渡された。俺たち……命令書、受け取った。Blasted Landsへ向かう途中、待ち伏せされた。\n\nmurlocs……たくさんのmurlocs……一匹、Swamp Talkerという名。槍が頭蓋骨に突き刺さったとき、俺の手から命令書を奪った。東……洞窟……\n\n<Bengorは気を失った。>", "命令を待っている。", "想像以上にひどい。私の部下のうち19人は、あのような苦しみを味わわずに済んだはずだ。私があれほど無分別に行動しなければ。\n\n彼らを助けてくれ、{name}！私には何もできないのだ。", 0xe86f7781, 0xf431fca9, 0x309b0066, 0x45e39911, 0xf2effa95, "....." },
  [2641] = { "Sprinkleの秘密素材", "GadgetzanのSprinkleは、Violet Traganを集めて渡すよう求めています。", "子どもの頃は、姉が料理を全部やっていたの。ひどいものだったわ！ 姉の作るごちゃ混ぜ料理には、とても喉を通らないものもあった――私が『秘密の』材料と呼んでいるものを見つけるまではね！ 何にでも加えれば……ワオ！ すごくおいしくなるのよ！\n\nそれは何かって？ Violet Traganっていうキノコよ。このひどい味の醸造酒を食べられるものに変える手伝いをしてほしいなら、Hinterlandsへ行って、そこにある小さな湖を探して。\n\nああ、それと覚えておいて。Violet Traganは水中でしか見つからないの。", "あの湖の水の底――Violet Traganが見つかるのはそこだけだ。息止めが得意だといいがな!", "それだよ、{name}！\n\nあまりに美味そうだから、つい……ハハ、引っかかったな！", 0x48dcbf56, 0x725eaf56, 0x8fd96556, 0x624f9464, 0x7cf9518d, "....." },
  [2661] = { "Marinへの配達", "SprinkleはViolet PowderをGadgetzanのMarin Noggenfoggerへ届けるよう求めています。", "これがViolet Powderね、{name}。これをMarinのとこへ持っていって、私に借りがあるって言っといてちょうだい!", "ああ、{name}、やっと戻ってきたか。何を持ってきたんだい?", "Violet Powderだって? 試しに使ってみるか……悪いようにはならないだろうしね。それは確かさ!", 0x458593b0, 0xbf6e3776, 0x1e01e31c, 0x1caa7a18, 0xe0372ebf, "....." },
  [2662] = { "Noggenfogger Elixir", "Marin Noggenfoggerは、彼が薬を作ったあとでまた話しかけるよう求めています。", "さて、この粉を露に混ぜるとしよう。\n\n少ししたら戻ってきて話しかけてくれ……素晴らしいNoggenfogger Elixirを完成させた後でな！", nil, "これを飲め！最高に素晴らしいぞ！！！\n\n自分にはできると分かっていたんだ……ああ、助けてくれて改めてありがとう、{name}。だが頼む、少し横に寄ってくれないか？商売の邪魔なんだよ！この見事なNoggenfogger Elixirで何百万と稼いでみせる、何百万だ！\n\n何だって？Sprinkleに借りがあると言っている？ああ、あのSprinkleときたら、冗談ばかりだ！", 0x1f1d9022, 0x1eeb2789, 0x356c5cd7, nil, 0x1bf10544, "...m." },
  [2681] = { "我らを結ぶ石", "Servants of Razelikhを九体、Servants of Sevineを三体、Servants of Allistarjを三体、Servants of Grolを三体解放する。任務を終えたらFallen Heroのところへ戻って下さい。石のすぐ近くにいなければ、儀式は失敗してしまう。", "Razelikhとその配下どもの軍勢を打ち破るには、お前一人の力では足りん。\n\nふさわしい冒険者の一団を集め、我が部下たちを永遠の責め苦から解き放ってくれ！ 打ち砕かねばならぬ石は十八個だ。\n\n激しく戦い、名誉とともに死ぬがいい、{name}。", "簡単な仕事ではないぞ、{name}。諦めるな!", "やり遂げたな、{name}！哀れな、苦しめられた魂たちもようやく安らげる。\n\n我々の仕事はまだ終わっていないぞ、{name}。話し合うべきことも、成し遂げるべきこともまだ多い。", 0xb9c0ca74, 0x954b0e18, 0xe5fcf65b, 0x2db7e4f8, 0xd8cd7b43, "....." },
  [2701] = { "古の英雄たち", "箱を開けて報酬を受け取って下さい。", "どうか、ここから古の遺物を一つ持っていってくれ。我々にはもう使い道のない品だ。\n\nLegionとの戦いで、お前の役に立つことを願う。", nil, "きらめきと輝きに、一時的に目がくらんだ。", 0x66b9e903, 0x9708f52e, 0x84e15692, nil, 0x4202d363, "...m." },
  [2702] = { "古の英雄たち", "Corporal Thund Splithoofと話して下さい。", "お前はその高潔さと英雄的な行いで、私に名誉を与えてくれた、{name}。\n\nそして、彼らにも名誉を与えてくれた……", nil, "まことに、そなたは我ら皆に栄誉をもたらした。我らの感謝の言葉だけでは足りぬ。", 0x66b9e903, 0x30807b26, 0xa2f524f9, nil, 0xe07e9f96, "...m." },
  [2721] = { "Kirith", "Lieutenant Kirithがどうなったのかを突き止めて下さい。", "お前の冒険の一つの章が閉じ、また別の章が始まる、{name}。\n\n私の部下の一人がまだ行方知れずだ。Blasted Landsのどこかで消息を絶った。もちろん、Lieutenant Kirithのことだ。\n\n前にも話したとおり、我々は二人ともAllistarjに捕らえられ、拷問を受けた。だが気の毒なKirithは、その意志の強さが揺らいでしまった。私は檻の中から実験の音を聞いていた。拷問を受ける者の悲鳴が、洞窟の通路じゅうに響き渡っていた。それが、私がKirithを見聞きした最後だった。", nil, "Treborだと？Treborがお前をよこしたのか？", 0xf24438ad, 0xa3197881, 0x5ce3d883, nil, 0x38fc0acd, "...m." },
  [2741] = { "スーパーEgg-O-Matic", nil, nil, "Super Egg-O-MaticはCurgle Cranklehopの最新の発明品だ。なかなか見事な機械である。\n\nあなたが操作盤に近づくと、Super Egg-O-Maticは激しくプスプスと音を立てる。", "hippogryphの卵を機械に入れた。一連のビープ音とともに、奇妙な機械音が続く。\n\nどうやらEggometerが卵の重さを量り、寸法を測り、梱包してくれたようだ。なんと素早いサービスだろう！", 0x4734c8ad, nil, nil, 0x057367ef, 0x55a62f46, ".mm.." },
  [2742] = { "Rin'jiが閉じ込められた！", "Rin'jiをQuel'Danil Lodgeの外まで護衛し、東のOverlook Cliffsで彼の隠された秘密を見つけて下さい。", "おい、{race}！\n\nRin'ji、斧なくして捕まった！ お願い、Rin'jiが逃げるの手伝って。{race}みたいな奴、Rin'jiの仲間嫌いなの、Rin'jiも知ってる。でもRin'ji、頼む！ ここから出なきゃいけない！\n\nRin'jiをここから助け出してくれたら、優しい{race}にいいものあげる……\n\nRin'ji、Overlook Cliffsに秘密のもの隠してる。", "Rin'ji、怖い!", "このトロールの石板が、Rin'jiの言っていた「秘密」に違いない。\n\n奇妙な印に覆われていて、石板に何が書かれているのか解読できない。", 0xedcbafa0, 0x2e3685ec, 0x9115ee07, 0x84c2d66f, 0x60b31af3, ".....", nil, nil, 0x9beee76c, nil, nil },
  [2743] = { "闇に紛れて", "調べて分かったことを持って、Fallen Hero of the Hordeのところへ戻って下さい。", "言葉を濁すのはやめよう、{race}。ここにいられる時間は限られている。\n\n悪魔の王Razelikhを守る力の三者を滅ぼさねばならん。それは、呪われた魂を一つ解き放つほど簡単な仕事ではないぞ。\n\n<Kirithはにやりと笑った。>\n\nいいか、Razelikhの配下どもは、それぞれがRazelikhの作ったアミュレットの三分の一を首に下げている。大悪魔を召喚するのに必要なのは、まさにそのアミュレットだ。\n\nTreborのもとへ戻り、Razelikhを召喚するのに何が必要か伝えろ。彼がさらに指示を与えてくれるだろう。", nil, "あの悪魔の王は、その残忍さに劣らぬほど計算された狡猾さを見せている、{name}。", 0x6aba07e4, 0x3827a7a4, 0xf90b2858, nil, 0x5627f8b3, "...m." },
  [2744] = { "悪魔ハンター", "AzsharaのLoramus Thalipedesと話して下さい。", "その三者は、Razelikhに守られている。\n\n隷属と引き換えに、RazelikhはBlasted Lands内で、彼らそれぞれにほぼ無限の力を与えた。アミュレットのかけらは、それぞれが持ち主の生命力と共鳴し、不死を与えている。Blasted Landsの中にとどまる限り、彼らは殺されることがなく、その寿命は世の終わりまで延ばされるのだ。\n\nお前の力になってくれるかもしれない者が一人いる、{name}。Azsharaへ行き、デーモンハンターのLoramus Thalipedesを探せ。島々を探すのだ。", "ここで何をしている?", "力を貸そう。だが、自分が何を相手にしているのか、お前は完全には分かっていないと思う。", 0x94f424b7, 0x52d8585c, 0xada03b34, 0xb27a2670, 0xb056674e, "....." },
  [2745] = { "城への潜入", "Stormwind CastleのTyrionに話しかけて下さい。", "ふむ、興味深い話だな。軽く扱っていい話じゃない。ああ、力にはなれる。だが、この件を最後までやり遂げるつもりなら、お前がやるべきなのは……合法とは言えない形の裁きを下すことだ。\n\nLescovarとMarzonは始末しなきゃならない、それも迅速にな。お前にそんなことができると思うか？\n\n決めるのはお前だ。やるなら、急いで城へ行き、俺の古い友人のTyrionというノームを探せ。あいつはここ数週間Lescovarを見張っている。この件を終わらせる手助けをしてくれるはずだ。", nil, "何だ……！？そんなふうに忍び寄るんじゃない！それに声を落とせ！Shadowの名にかけて、何だって俺に忍び寄ってくるんだ？忙しいのが分からんのか、この間抜けが。\n\n何をしているのかだと？次のDark Portalが開くのを待っているんだ、他に何をしていると思うんだ？言いたいことを言ってさっさと行け……俺たち二人が茂みに隠れているのを衛兵に気づかれる前にな。俺には守るべき評判があるんだ。", 0x8aa81dca, 0xffe1ba3d, 0x31a5101a, nil, 0xd55e7590, "...m." },
  [2746] = { "重要な品物", "Silk Cloth 3枚とClara's Fresh Apple 2つをStormwindのTyrionに渡して下さい。", "Triasが予定を少し早めたいって？ いいさ、やれるよ。でも俺はまだ準備ができてない。それと覚えておけ、難しいところは俺がやるが、自分の手を汚すのはお前だ。わかったか？ よし。\n\nよし、計画を実行に移す前に、いくつか持ってきてほしいものがある。Spybotにあの衛兵たちを通り抜けさせる完璧な変装があるんだ。\n\nsilkとapplesをいくつか持ってきてくれ。silkはお前に任せるが、街のすぐ外にあるClaraの小さな農場には、ちょうどいい大きさのapplesがあるんだ。", "ここ二、三週間、Lescovarを見張っている。Triasは一度もあいつを信用したことがないが、Defias Brotherhoodに関わっているとまでは疑っていなかった。俺たちが追っていたのは、あいつをTwilight's Hammerに結びつける手がかりだったんだ。いずれにせよ、あいつはこの街の手に負えないほど危険な存在になった。そこで俺たちの出番ってわけだ。\n\nその品を持ってきてくれれば、計画を実行に移せる。", "これで十分だ、{name}。よくやった。\n\n必要な残りの装備は背嚢に入っている……光に感謝だ、仕立て屋の友人に絹の鞄を作ってもらったばかりでな。装備を全部持ち歩くには、そろそろ場所が足りなくなっていたんだ。\n\nSpybotが入り込む前に、お前が何をすべきか分かるよう、細かいところを決めておこう。", 0x1f4eb590, 0x1d0c75b3, 0x1b56c1ff, 0xb3384936, 0x8b76d0c1, ".....", nil, nil, 0xde7d35a2, nil, nil },
  [2751] = { "蛮族の胸壁", "Patterned Bronze Bracers・Bronze Greatsword・Sharp Clawをそれぞれ2つずつ、OrgrimmarのOrokk Omoshに渡して下さい。", "{name}、20代にわたってOmosh家はこのハンマーを握ってきたんだ。十万トンもの金属を我々は鋳造してきた。悲しいけれど、それもOmosh家の不作、Orokkで終わる。血縁も無く、子孫を作る能力も無いせいでな。\n\nOmosh家に伝わってきた秘密の製造法を自分と一緒に死なせることはできん! この遺産を誰かが受け継いでいかねばならんのだ。Omoshであろうがなかろうが関係なく!\n\n有能であることを証明してくれ、{name}。これから言う物をOrokkに持ってきてほしい。patterned bronze bracers・bronze greatsword・sharp clawをそれぞれ2つずつ。それをOrokkのところへ持ってきてくれたら、続けよう。", "青銅だ、{name}! もっと青銅を!!", "血筋は絶えても、Omoshの伝説は続いていくだろう!\n\n{name}、君は己を鍛冶師であると示してくれた。鍛冶師にとって報酬というのは、自分の作った武器と鎧が敵の血で覆われるのを見られる満足感だ!\n\n君の作る胴鎧がこの先何世代にわたり、敵の血でずぶ濡れになりますように!", 0x17a1e905, 0x5f866922, 0x7a95f0a5, 0x718616f8, 0x90223961, "....." },
  [2752] = { "鉄の肩当に", "Bronze Battleaxe・Bronze Warhammerをそれぞれ4つずつ、OrgrimmarのOrokk Omoshに渡して下さい。", "{name}、君の目に熱意が見える。スポンジみたいにOmosh家の知識に浸かっている。\n\n教えられることは三つある!\n\nその金床へ戻ってきて、炉の熱に浸かって、Orokkにbronze battleaxesとbronze warhammersを4本ずつ作ってくれ。その時こそ、鉄の肩当てを学べるんだ。", "お前の献身を見せてみろ、{race}。", "{name}、君はOrokkの誇りだ。読んで、鉄の肩当を学んでくれ!", 0xf7581b4d, 0x57479f8c, 0xb4647cff, 0x31673690, 0x16d86607, "....." },
  [2753] = { "踏みつけられて", "OrgrimmarのOrokk OmoshにGreen Iron Helm 4つ・Green Iron Bracers 4つ・Green Iron Leggings 2つを渡して下さい。", "Orokkが教えられることはもう二つある、{name}。筋肉が痛いのは知ってる。だがOmosh家のために続けてくれ!\n\ngreen iron helms 4つ・green iron bracers 4つ・green iron leggings 2つを持ってきてくれ……君が学び、敵に苦痛を与えるために!", "お前のブーツに踏まれて、奴らの頭蓋骨は砕けるだろう!", "君は祖父を思い出させるよ、Omosh家のChief Gorokkを! 読んで、鉄のブーツについて学んでくれ。", 0x910ff756, 0xaf1751cb, 0x89658ce5, 0x8fb855cc, 0x65ef0b88, "....." },
  [2754] = { "怒りの角", "Solid Iron Maul・Silvered Bronze Boots・Silvered Bronze Gauntletsをそれぞれ2つずつ、OrgrimmarのOrokk Omoshに渡して下さい。", "{name}、Orokkの最後の授業だ。神聖な金床と炉へ戻れ!\n\nsolid iron mauls 2本とsilvered bronze bootsが2つ、それとsilvered bronze gauntletsを2つ持ってきてくれ。\n\n近づいた時、奴らの目に映る恐怖を見ろ!", "鉄に誰が主人か教えてやれ、{name}!", "驚きだ! {name}、君はOmosh家のやり方を身につけている!", 0xda80e91d, 0xcba97f38, 0xe496585c, 0x255ff424, 0xf310ad15, "....." },
  [2755] = { "Omoshの喜び", "Omosh Dance of Joyを見て学んでください。", "Orokkは泣いてるんじゃないぞ、{name}。煤が目の中に。\n\n<Orokkは涙を拭った。>\n\nOmosh家最後の秘密がひとつある。それを教えてあげよう。Orokkは幸せに死ねるよ、{name}に感謝する。\n\nOmosh家の喜びの踊りを身につければ、鉄の拳が身につく!", nil, "<Orokkは息を切らしている。>\n\nOrokkがOmosh家の喜びの踊りを踊ってから、もうだいぶ長いこと経ってしまったよ。今覚えてくれ、{name}!", 0x69671f62, 0x90c19859, 0x16aecffb, nil, 0xc6b8ccc7, "...m." },
  [2756] = { "昔ながらのしきたり", "Steel Breastplate・Steel Plate Helmをそれぞれ4つずつ、OrgrimmarのAturk the Anvilに渡して下さい。", "伝説の時代、Aturkは敵の頭蓋骨を叩き割り、その骨を細かい粉に挽いて金属線に使ったものだ。そんな時代はとうに過ぎ去った、{race}。大族長は氏族の間の平和を求めておられる。かつての敵も、今では疲れた目で見張られるだけだ！\n\n信じられんだろうが、それがThrallの意志なのだ。\n\n嘆くのはここまでだ！ お前は学ぶためにここにいる、そして学ぶのだ！ steel breastplatesを4つとsteel helmsを4つ持ってこい。そうすれば戦の味を少しは知ることになるだろう！", "Aturkは時と同じく、誰も待たん! 急げ、愚か者!", "お前も大族長に付き従うだけの、もう一匹の愚かな追随者にすぎんようだな、{name}。がっかりだ。\n\n戦場での栄光ある死をどれほど望んでいることか。それなのに俺はここに縛りつけられ、Thrallの命令で赤子どもに物作りを教えている！見て学べ、小僧！", 0x4e5f99d2, 0x111e7523, 0xd7eb3c98, 0xfa65622b, 0xd7251ac5, "....." },
  [2757] = { "のるかそるか!", "Booty BayのMcGavanと話して下さい。", "いいか、小僧、ここでうろうろしていても何も学べやしないぞ。\n\n知り合いの知り合いがいてな。そいつはBooty Bayの鍛冶場のあたりにいる。この記章を見せれば、mithrilについて何もかも教えてくれるだろう。\n\nで、どうする？ こんな子どもの遊びはおむつの赤ん坊に任せておけ、{name}――次へ進む時だ。\n\n興味があるなら、そいつの名はMcGavanだ。この装身具を見せれば、お前の本気をわかってくれるだろう。", "お前さんのような者は珍しいぜ、相棒。その記章を見せてみな。", "Blackhoofの後ろ髪によって……ついに、Mithril Orderにふさわしい者が!", 0x201687f5, 0x76671185, 0x8d214fc9, 0xbd77d15c, 0x83bb6990, "....." },
  [2758] = { "鋳造の起源", "Golden Scale Bracers 6つをStormwindのHank the Hammerに渡して下さい。", "わしがお前さんくらいの年の頃、Galvanという名のドワーフがわしを弟子にして、鎧鍛冶の道を教えてくれた。Booty Bayへ発つ前に、鍛冶の技を高める意欲と決意のある者は皆鍛えてやると約束させられたんだ――だからわしはここにいる――あれから何年も経った今もな。\n\nさて、お前さんも少し学ぶ時だ。golden scale bracersを6つ作ってくれ。そうすれば鍛冶がどこから来たのかがわかるだろう、{name}。", "お前がGalvanの次の弟子になるのか?", "よくやった、{name}！よく聞いて学べ。\n\nBlacksmithingは決してここから生まれるのではない！<Hankは自分のハンマーを指さす。>\n\nBlacksmithingは決してここから生まれるのではない！<Hankは金床を指さす。>\n\nBlacksmithingが生まれるのはここだけだ！<Hankは自分の心臓を指さす。>\n\nこれでBlacksmithingがどこから来るのかが分かっただろう。", 0x5dd39489, 0x350387d3, 0x870eb53b, 0x1e10ca8a, 0xeb39dca0, "....." },
  [2759] = { "Galvanを探して", "Booty BayのMcGavanと話して下さい。", "GalvanがBooty Bayを去ってから何年も経つが、教団の者たちはまだ町に残っていて、Galvanの教えにふさわしい者がいつか現れるのを待っている。\n\nこの記章を持っていって、Booty BayのMcGavanに見せなさい。\n\n本当にそこまでたどり着けたなら、彼はお前がふさわしい者だとわかるだろう。私は信じているよ、{name}！", "お前さんのような者は珍しいぜ、相棒。その記章を見せてみな。", "Blackhoofの後ろ髪によって……ついに、Mithril Orderに相応しい者が!", 0x4dfe8db2, 0x76671185, 0x9fa6b639, 0xbd77d15c, 0x83bb6990, "....." },
  [2760] = { "Mithril Order", "Stranglethorn ValeのGalvan the Ancientと話して下さい。", "新入りのほとんどはBooty Bayまでたどり着けないんだ、{name}。記章の輝きだけで、どんなに堅物の鍛冶屋でも欲に目がくらんじまう。愚か者どもさ。その先で目にする財宝に比べりゃ、記章なんて大海の一滴だってのに！\n\nGalvan the Ancientを探して、このピンを見せな。あの人の住まいはずっと北、Zul GurubとMosh'Ogg ogreの塚の間にある。", "よう! 近くに来な。Galvanに持ってきた物を見せてみろ。", "ああ、Mithril Order入団に相応しい者がやってきてからもう何年も経った。すぐ始めよう!", 0x569a9c64, 0xa93e34db, 0x8f04f385, 0x5db33734, 0x2f763df1, "....." },
  [2761] = { "精錬始め、精錬終わり", "Mithril Bar・Iron Barを40本ずつ、StranglethornのGalvan the Ancientに渡して下さい。", "多くの鍛冶屋は、採掘と鍛冶は別々の独立した仕事だと思っている。だが、採掘なくして鍛冶がありえようか？ ははっ――ありえぬことだ！ 腕の立つ鍛冶屋は、腕の立つ鉱夫でもなければならんのだ。\n\nGalvanに力を示してみよ、{name}。bars of ironを40本とbars of mithrilを40本持ってこい。その暁には、Galvanがornate mithril pantsの技を教えてやろう！", "これだけ採掘すれば、筋肉は盛り上がり、体は痛むものだ!", "君の仕事の価値観は申し分ない、{name}! Galvanの鉱物学の道を理解し始めている! これを持っていって、学べるものをすべて学べ。", 0x4717cd13, 0x15538102, 0x6f06ffe2, 0x5c6d8c09, 0x8470c433, "....." },
  [2762] = { "インチキ銀", "StranglethornのGalvan the AncientにMithril Bar 40本とTruesilver Bar 5本を渡して下さい。", "truesilverはmithrilより強く丈夫だと言われておる。Galvanもこの鉱物の評価に異を唱えはせんが、その名に反して、truesilverは真実ではない！ mithrilのほうがはるかに高貴な鉱物なのだ！ はっ！ いずれにせよ、この教えのためには、その偉大なる銀の偽り者を探してこねばならんぞ、{name}。\n\nbars of mithrilを40本とbars of truesilverを5本持ってこい。引き換えに、ornate mithril glovesの秘密を教えてやろう。そして何より、truesilverが嘘つきであることを学ぶのだ！", "これだけ採掘すれば、筋肉は盛り上がり、体は痛むものだ!", "あれは残酷な女主人だろう、{name}？もちろんtruesilverのことを言っているのだ。そうとも、Galvanはこの教訓を学ぶのにAlteracの山々で十年以上を費やした。これを受け取り、そこから学べるだけのものを学ぶがいい！", 0xc46fcd5c, 0xc623695f, 0xd9fa85a8, 0x5c6d8c09, 0xa96f4203, "....." },
  [2763] = { "注入の技", "StranglethornのGalvan the AncientにMithril Bar 40本とCitrine 4つを渡して下さい。", "貴重な宝石の採取は、我らの技にとって最も重要なことだ、{name}。citrineほど貴重な宝石はそうない。我らが品に込める魔力は、citrineがあることで大いに増幅されるのだ。\n\nこの教えでは、bars of mithril 40本をcitrines 4つで強化する。その結果、魔法宝石学をより深く理解し、ornate mithril shouldersを作る知識を得ることになろう。", "これだけ採掘すれば、筋肉は盛り上がり、体は痛むものだ!", "その輝きから目を離すのは難しいものだ、{name}。そうとも、citrineは見事な宝石だ。\n\nよく見て、この発見が我々に何を教えてくれるのかを学ぶがいい！", 0xf2f52fac, 0xdf13f115, 0xf5af3a64, 0x5c6d8c09, 0x7cc58672, "....." },
  [2764] = { "Galvanの最も優秀な弟子", "TanarisのGadgetzanにいるTrenton Lighthammerと話して下さい。", "Galvanのもとでの修行を締めくくる準備ができたなら、Gadgetzanへ向かうがよい。\n\nそこには我が最高の弟子、Trenton Lighthammerがおる。ornate mithrilの技について、多くを教えてくれるだろう。さもなくば、ここに残って学ぶがよい！\n\nああ、GadgetzanはもちろんTanarisにあるぞ！", nil, "Galvan the Ancientがお前を寄越したのか？？\n\n<Trentonは頭を下げる。>\n\n師匠のもう一人の弟子に会えるとは、大変な光栄だ！", 0xa8a42fec, 0xcd48da8f, 0x7bd100a2, nil, 0x4513ea46, "...m." },
  [2765] = { "鍛冶の専門家!", "Galvan the Ancientに報酬を要求して下さい!", "初めてわしのところへ来た時から、お前はわしの最高の弟子の一人になるとわかっておった！ お前はためらうことなく、なかなかの力を持つ装身具をMcGavanに手放した。わしに会うためだけにそうしたのだ。そのような鍛冶の技への盲目的な信頼と献身は報われるべきだ。\n\nお前は鍛冶の熟練を極めたぞ、{name}。報いを受け取るがよい！", nil, "ここで得るために払った犠牲よりもっと大きな力を秘めた飾りを受け取るのは、君に相応しい。達者で使えよ、{name}。", 0x54c35794, 0x66460dd6, 0x62ca6d71, nil, 0xffcf7017, "...m." },
  [2766] = { "OOX-22/FEを探せ!", "Feral Scar Vale付近の洞窟内にいるOglethorpeの自動誘導ロボットのところへ、救難装置を持って行って下さい。", "金属でできた、卵のような形の奇妙な装置を見つけた。つまみの一つをいじると卵が動き出し、開いてノームのロボットのような仕掛けになった！ ロボットの卵の中から、雑音混じりの声が聞こえてくる。\n\n「私の名はOglethorpe Obnoticus、私の帰還用ロボットが墜落してしまったのだ！ 回収してくれたらお礼をしよう。このビーコンをロボットのところへ持っていってくれ！」\n\n「ロボットの座標を計算しておいたぞ。Feral Scar Vale近くの洞窟の中だ！」", "どうやら……ロボットのニワトリの残骸を掘り当てたようだ。卵の中から、再び声がパチパチと響き出す。\n\n「ああ、素晴らしい働きだ！ これこそ私の帰還ロボットだよ。ただ、センサーによると、修理のためにBooty Bayへ飛んで帰るには、まず始動の手助けが必要なようだ。さあ、ビーコンをローバーの中に置いてくれ。あとはビーコンが全部やってくれる！」", "あなたは卵……遭難信号機を、鶏……帰巣ロボットの中に納めた。\n\nロボットの中からうなりと駆動音が聞こえ、それは立ち上がろうともがいている。ロボットが動き出すと、再びOglethorpeの声が、今度はロボットの内側から聞こえてくる。\n\n「OOX-22/FEはどうにか動いている。だが大がかりな修理が必要だ！お前が運ぶには重すぎる……しかし考えがある。もう少しこいつを見守ってくれるか？」", 0x66c4048e, 0x7e3d9c73, 0xa871c89f, 0xae44575b, 0x5f146e7e, "....." },
  [2767] = { "OOX-22/FEを救出せよ!", "OOX-22/FEをForgotten Coast沿いの桟橋まで護衛し、Booty BayのOglethorpe Obnoticusに報告して下さい。", "ロボットから再びノームの声が雑音混じりに聞こえてくる。\n\n「OOX-$N1/FEを開けた安全な場所へ移動させて、長い離陸手順を始めさせなければならない。ステルス機能は内蔵されているが、再び使えるようにするにはこちらで時間が必要だ。ロボットを今の場所から、そうだな、Forgotten Coast沿いの波止場まで護衛してくれ！ あそこならうってつけの場所だし、準備を整えるのに十分な時間も稼げる！」\n\n「無事に波止場まで護衛したら、Booty Bayの私のところへ話しに来てくれ！ Oglethorpe Obnoticus、以上！」", "そう、私がOglethorpe Obnoticus、名発明家にしてあなたのお役に立つ者だ! さて、何かお手伝いできることはあるかな?", "おお、あなたがOOX-22/FEの偉大なる救い主か！この助力には感謝の言葉もない！私の帰巣ロボットの系統にはまだ開発が要るが、あなたが回収してくれたおかげで、作り直しに費やすはずだった数えきれない時間も、製造にかかる多額の金貨も助かった！\n\nさあ、ここにある品から好きなものを選んでくれ。惜しみない助力に改めて感謝する、{name}。私も私のロボットたちも、あなたに借りがある！", 0xa3042cf3, 0x89a547eb, 0x0624d95d, 0xa11d5fae, 0xd20da83c, "....." },
  [2768] = { "Divino-matic Rod", "GadgetzanのChief Engineer BilgewhizzleにDivino-matic Rodを渡して下さい。", "Sergeant Blyに盗まれたんだ！ 借りるだけだって言ったくせに、俺の大事なdivino-matic rodを盗みやがった！！ あのrodがなかったら、どこに新しい水場を掘ればいいのかどうやってわかるっていうんだ？？\n\nBlyを見つけて、俺のrodを持ってきてくれ！ あいつは評判の悪い冒険者の一団を率いて、西のZul'Farrakへ宝探しに行ったそうだ。きっとそこにいるはずだ。\n\nトロールどもがあいつを片付けてくれてるといいがな。rodを取り返すのにあいつと戦わなきゃならないとしたら、相当な戦いになるぞ。", "Sergeant Blyは見つかったかい? divino-matic rodは手に入れてくれた?", "見つけたのか! よくやったよ{name}! Blyと戦わなきゃならなかったのか? あいつと仲間連中を思いっきりぶちのめしてくれたんだろうね!", 0x5062dadf, 0x5ecdd6a7, 0xa6f3d8cc, 0x7535d73e, 0x9ab2a77b, "....." },
  [2769] = { "Brassbolts兄弟", "Shimmering FlatsのWizzle Brassboltsと話して下さい。", "Brassbolts兄弟に会ったことはあるか? 彼らは遙か彼方Kalimdor大陸のShimmering Flatsにいて、ゴブリンとロケットカーで競争しているんだ。いつも勝ってるが驚くことじゃあない……ゴブリンの車はよく爆発するんで、フィニッシュラインを越えることはほとんどないからな!\n\nそれでも、Brassbolts兄弟は車をより速く走らせる新しい方法をいつも探していて、次の実験に使うとても貴重な物が必要だとWizzleが言っていたよ。\n\nその重要な物って奴を手に入れる助けが必要だろう。彼と話して、見つけてやってくれ。", nil, "ああ、俺を手伝いたいって? そりゃあいい!\n\n今取り組んでる実験に使いたい物があるんだ。それを手に入れる手伝いをしてくれる、君みたいに勇敢な{class}が必要なんだ!", 0x089469a7, 0xb1fcc703, 0x1fabb59b, nil, 0x80c2ec73, "...m." },
  [2770] = { "Gahz'rilla", "Shimmering FlatsのWizzle BrassboltsにGahz'rilla's Electrified Scaleを渡して下さい。", "Tanarisにあるトロルの砂の都、Zul'Farrakの奥深くに、神聖な池がある。その池からトロルは巨大な獣を召喚する! Gahz'rillaだ! その鱗はエネルギーでパチパチと音を立てていて、そりゃあ恐ろしいんだ。そのエネルギーこそ、車に使いたいんだよ!\n\nGahz'rilla's Electrified Scaleを持ってきてくれ!\n\nだけど、Gahz'rillaの召喚方法はトロルたちがしっかり守っている秘密なんだ。Gahz'rillaに会うには、まず最初にトロルからその秘密を力尽くで奪わなきゃならない。", "scaleは持ってる? そのエネルギーを利用するいろんな方法を試すのが待ちきれないよ!", "うわあ、鱗を持ってきてくれたんだ! ありがとうよ、{name}。この鱗を使うのが待ちきれない!\n\nそれじゃ君、Gahz'rillaに会ったんだ? みんなが言うくらい大きいのかい??", 0x020c88eb, 0x1d10cf57, 0xd30442ce, 0xcc8dce4a, 0x7f35b7a9, "....." },
  [2771] = { "肩に乗ってる良い頭", "Mithril Coif 2つとOrnate Mithril ShouldersをTrenton Lighthammerに渡して下さい。", "どうやら師匠は最初からこうするつもりだったらしい。私はあなたが学んだ品の作り方を教わらなかったし、あなたは私が学んだ品の作り方を教わらなかった。\n\n師匠は賢いお方だ、{name}。互いに教え合おうじゃないか！\n\nmithril coifとornate mithril shouldersの作り方を教えてくれたら、ornate mithril helmの作り方を教えよう。", "品物の製作は終わったか、{name}?", "素晴らしい! 平等な取引だな、あえて自分で言うとしたら。よく見て学んでくれ、{name}!", 0xd4e4683b, 0x7a9ee4a2, 0x1014689c, 0x71e37944, 0xf6fdfe75, "....." },
  [2772] = { "世界がひれ伏して", "Trenton LighthammerにHeavy Mithril Boots 2足とOrnate Mithril Pants 1つを渡して下さい。", "去年のAll-Valley Blacksmithing Championshipで、観客は皆、Venture Co. Foundryの卑怯な犬に私の脚が払われるのを見た。だが彼らが知らなかったのは、私が試合を続け、最終的に優勝できた理由だ。そう、ornate mithril bootsさ！\n\nだが、今年の大会に向けてornate mithril pantsの作り方を覚えなければならない。Venture Co.のshredderが出場するんだ！ pantsの作り方を教えてくれ、そうすればbootsの作り方を教えよう！", "品物の製作は終わったか、{name}?", "世界が君の足下にひれ伏すよ、{name}! みんなを足下に集まらせてみなよ、誰にも動かせないから!", 0x090933fe, 0x4f45deb8, 0xb61b748b, 0x71e37944, 0x04ba94a1, "....." },
  [2773] = { "Mithrilの子", "Trenton LighthammerにHeavy Mithril Breastplate 2つとOrnate Mithril Gloves 1つを渡して下さい。", "このあたりじゃ、私はMithril Kidとして知られている。世界中の冒険者にornate mithrilを供給しているんだ。\n\n<Trentonがささやく。>\n\n彼らは知らないのさ、私がornate mithril glovesの作り方を知らないってことをね。シーッ！ これは私たちだけの秘密だ。\n\nornate mithril glovesを作る技を教えてくれ、{name}。引き換えに、Galvanのもとでの修行の集大成、ornate mithril breastplateを見せてやろう。", "品物の製作は終わったか、{name}?", "教えてくれたことすべてに感謝する、{name}。ornate mithril一式の主にして司令官たる品が、間もなくあなたのものとなる。\n\n見よ！", 0xc82def0d, 0xcf23ef19, 0x8eabfebf, 0x71e37944, 0xa14908be, "....." },
  [2781] = { "お尋ね者: Caliph Scorpidsting", "GadgetzanのChief Engineer BilgewhizzleにCaliph Scorpidstingの首を渡してください。", "指名手配：Caliph Scorpidsting！\n\nTanarisのGadgetzanにあるGadgetzan Water Companyは、Wastewanderの無法者どもの首領、Caliph Scorpidstingの首に高額の懸賞金を支払う。その罪状は以下のとおり。\n\n$N1. Gadgetzan Water Co.の従業員の殺害！\n\n2.Gadgetzan Water Co.の資源の窃盗！\n\n3.Gadgetzan Water Co.の財産の強奪！\n\nCaliph Scorpidstingを仕留めた証拠をChief Engineer Bilgewhizzleのもとへ持参すれば、即座に報酬が支払われる！", "ええ、{class}、私はGadgetzan Water Companyの職員です。何かご用でしょうか?", "ついに――正義は成された！あの卑劣な放浪者どもに大きな一撃を与えたな！Scorpidstingが倒れた今、これこそがGadgetzanの水源から不法居住者どもを追い払う決め手になるかもしれん！\n\nGadgetzan Water Companyの権限において、この懸賞金を喜んで授けよう。お前は我々全員のために大きな働きをしてくれた。", 0xb61cb520, 0xf8907cbb, 0x2f04d7af, 0xbf6f0318, 0x71967060, "....." },
  [2782] = { "Rin'ji's Secret", "Witherbarkのトロールに関する事柄でよく知られた学者、Oran Snakewritheなら、この石板を解読できるかもしれない。彼女はUndercityのMagic Quarterに住んでいることで知られている。", "その石板はWitherbarkトロールの紋様で覆われている。Rin'jiの秘密は、まったくの謎だ……\n\nかなり価値のあるものを手にしているのかもしれない。一方で、その正反対ということもありうる。窮地に陥ったWitherbarkのトロールなら、危機から抜け出すためにどんなことでもするだろう……", "さて、これは何かな?", "この石板は……実に珍しい……どこでこれを見つけたのだ、{name}？", 0x9db2ed6a, 0xacdc06a9, 0xc21069d7, 0xd520768c, 0x51b1062d, "....." },
  [2783] = { "つまらない口論", "Blasted Landsと沼地の境にいるFallen Hero of the Hordeと話して下さい。", "我々は戦う相手を間違えている、{name}。\n\nこの地の真の力は、我々がオークどもと焦土を奪い合っている間にも、力と数を増し続けている。\n\nこの地でHordeを相手に戦を続け、いつの日かBurning Legionの軍勢に蹴散らされるだけなのか？ 無益なことだ。\n\n互いの違いはひとまず脇に置け、{name}。Hordeの倒れた英雄と話すのだ。彼はBlasted Landsの背後にある真実を知っている。", nil, "Allianceが力を貸したいと？\n\n二度とこのような日を目にすることはないと思っていた。AllianceがHordeと肩を並べて共通の敵と戦う日を。\n\nそうなるであろう……我らは手を結ぶ。", 0xfd0feee3, 0xdc8a1010, 0xa7547fc4, nil, 0x1a69cea0, "...m." },
  [2784] = { "恩寵を失って", "Fallen Hero of the Hordeが語る話を聞いて下さい。", "我が話を聞け、{race}。", "私の話を聞いてくれ。", "霊となった我には何の力もない、{name}。力を貸してくれ。我が名誉を取り戻させてくれ。", 0x8531d6e8, 0xcc5274d5, 0x896212bd, 0x35dae5cd, 0x9269440e, "....." },
  [2801] = { "悲しみの物語", "Fallen Hero of the Hordeが語る話を聞いて下さい。", "先へ進む前に、我が話を聞かねばならん。", "私の話を聞いてくれ、{name}。", "今こそ行動の時だ、{name}。", 0x76eea50b, 0xcc5274d5, 0x7cce8f86, 0x8967c526, 0x75013208, "....." },
  [2821] = { "品質の証", "Thick Yeti Hidesを$N1枚、Feathermoon StrongholdのPratt McGrubbenのところへ持って行って下さい。", "革細工についての俺の哲学はな、仕事はできる限り最高の品質でなきゃならないってことだ。妥協はなしだ。品質なんてどうでもいいなんて言う奴は、Dun Moroghの海辺の土地を売りつけようとしてるのさ！\n\n最高品質の素材を追い求めているうちに、thick yeti hidesに行き当たった。YetiはFeralasに棲んでいて、Feral Scar Valeにたくさんいる。そいつが欲しいんだ。十枚ひと束持ってきてくれたら、俺の革製品から一つ選ばせてやる。それで公平だと思うなら、取引成立だ。", "thick yeti hideを10枚ひと束持ってきてくれれば、私が作った品から好きなものを1つ選ばせてあげよう。品質にはこだわっているから、良い品が手に入ることは保証するよ!\n\nyetiが見つからないなら、いそうな場所を知っている。Forgotten Coastの少し内陸、Feral Scar Valeのあたりを探してみるといい。", "このhideの手触りを確かめてみたかい？きちんと処理すれば、このhideは鉄より強くなるかもしれないんだ。このhideを知る者は多くない。それに私が知っている数々の処理液を組み合わせれば、本物の品質の証を持つ品が作れるかもしれない……もちろん、君のおかげでね！\n\nさあ、君の働きに対して私が差し出せる品から選んでくれ！", 0x2849b87a, 0x1edbe908, 0x1df20f34, 0x3b3e3760, 0x7bf8bd37, "....." },
  [2822] = { "品質保証", "Thick Yeti Hide 10枚をCamp MojacheのJangdor Swiftstriderに渡して下さい。", "私は自分の革細工に誇りを持っているし、それは作品に表れていると思う。品質は決して妥協してはならない。品質なんてどうでもいいと言う者は、大地が秘密を隠していないとも信じ込ませようとするだろうさ！\n\n高品質な素材を追い求めるうちに、最近thick yeti hidesを見つけたんだ。yetiはFeralasに生息していて、ここから西のFeral Scar Valeでよく見かける。10枚ひと束につき、私の革製品を一つ選ばせてやろう。それで納得してくれるなら、取引成立だ！", "thick yeti hideを10枚ひと束手に入れられたかい? 私の革製品は他の追随を許さない。hideを持ってきてくれたら、いくつか分けてあげよう。\n\nyetiが見つからないなら、いそうな場所を知っている。ここから西、Forgotten Coastの少し内陸、Feral Scar Valeのあたりを探してみるといい。", "ああ、素晴らしい！このhideは、特別な処理を施せば鉄のように丈夫になるのだ、本当だとも！なめしに合う配合を見つけるには何度も試す必要があるだろうが、これで私の品質の証をさらに高められると確信している。\n\nそしてお前だが、{name}……お前の助けは私にとって計り知れないものだった。私が作ったこれらの品から、好きなものを選んでくれ。", 0x2849b87a, 0xc0f5fd2f, 0xf3e7743d, 0xa1aa3678, 0x64f1fdb0, "....." },
  [2841] = { "Rig Wars　乗り物戦争", "Gnomereganから Rig BlueprintsとThermaplugg's Safe Combinationを手に入れて、OrgrimmarのNoggに渡してください。", "ノームの技術・・・それは２年前なら一番の笑い種でした。時代は確かにかわりました。今、彼らは我々のシュレッダーより素晴らしい新しい乗り物（Rig）に乗っています。私には青写真（blueprints）が必要なんです、{name}！\n\n残念なことに、設計図は Mekgineer Thermaplugg近くの金庫の中です。もっと悪い事に、金庫を開ける組み合わせは、 Mekgineer Thermapluggが知っているだけです。\n\n何としてでもその組み合わせを手に入れてください、{name}。そして、金庫をこじ開け、青写真を持ってきてください！", "blueprintsなんて見当たらないぞ。体のどこかに隠してるのか、それとも俺をイラつかせるためにここで突っ立ってるだけか?", "やれると思っていたぞ、{name}！もっとも、Sovikのほうは疑っていたがな。\n\n<Noggは咳払いをする。>\n\n設計図が手に入った以上、あの掘削機の製作に使われたノームの技術をすべて解き明かし、それを新型シュレッダーのためのゴブリンの技術に変えるのは時間の問題だ。", 0xcf5a7376, 0x0da92dea, 0xe80d6917, 0xc41d80f1, 0xbb1889bb, "....." },
  [2842] = { "Chief Engineer Scooty", "Booty BayにいるScootyと話してください。", "新しいノームの乗り物（Rig）についてKernobeeから聞いてすぐに、Scootyと私はTranspolyporter 6000：Gnomeregan への最も速く信頼性が高い道、の作業にとりかかりました。\n\nそれは、すでに乗ることができます、{name}。もし試してみたいなら、Booty Bayに行って、wind rider小屋近くのScootyと話をしてください。Booty Bayへ行くにはRatchetから船にのってください。\n\nもちろん、ドワーフのはびこるDun Moroghの山々を通り抜けてGnomereganまで走ろうっていうなら、ご自由に！", nil, "いい代物だろう？ゴブリンの輸送技術の頂点だ。爆発したのは十数回ばかりさ。\n\n心配するな、{name}、すっかり直しておいた。お前の上で爆発したりはしない。まあ、もし爆発しても、あっという間で痛みもないさ。", 0x8bca8052, 0xfcd92c6b, 0x7f138176, nil, 0xc0853908, "...m." },
  [2843] = { "Gnomer-gooooone!", "ScootyがGoblin Transponderの設定を済ませるのを待ってください。", "トランスポンダーを持ってさえいれば、あとはパッドに乗るだけでGnomereganへテレポートできるよ。\n\nちょっと変わった副作用が出るかもしれないけど、どれも後に残るものじゃない……もうね。\n\n一番大事なことを忘れるところだった――戻り方だ。戻る準備ができたら、Gnomereganにあるトランスポリポーターのパッドに乗ればいい！\n\nさて、トランスポンダーをあんたの体格と体重に合わせて調整しないとね。", "準備できたぞ!", "準備完了！　用意ができたら、とにかく台に乗りな。", 0xbb614da5, 0xec9deafb, 0xed51c3c5, 0x8ea737cf, 0x32ca58dc, "....." },
  [2844] = { "巨大な守護者", "迷子になったナイトエルフの少女を見つけて下さい。", "おいらは役立たずだよ、{name}。ちっちゃな友達のShayを見張ってるはずだったのに、どういうわけか、あの子はおいらのところからいなくなっちまった。何があったのか、ほんとによく分かんないんだ。最後に見たときは、ここのすぐ北の遺跡を一緒に歩いてたんだけど。\n\n何もかも順調だったのに、振り向いたら……あの子がいなくなってた。\n\nで、今はどうしたらいいのか、さっぱり分かんないんだ。何かいい考えはあるかい、{name}？ おいら、ひどく心配なんだよ。\n\nなあ、あんたがShayを探しに行ってくれないかい？ あんたの脚なら、おいらの脚よりずっと速く行けるからさ。", nil, "ああ、見つけてくれて本当に嬉しい！正直に言うと、ちょっと迷子になってて……でも、ここって美しい場所じゃない？", 0x4901404e, 0x55e72e8a, 0x7c246465, nil, 0x8e2ac637, "...m." },
  [2845] = { "さまようShay", "箱からShay's Bellを取り出す。\n\nShay LeafrunnerをRockbiterの野営地まで護衛して下さい。", "友達のRockbiterのところへ戻る道を探すのを、手伝ってもらえないかしら？ 彼は私を見張っているはずだったの……でも私、ときどきふらっとどこかへ行っちゃう癖があるのよね。見るものがたくさんありすぎて、すぐ気が散っちゃうの。\n\nでも、いつでも私の気を引けるものが一つだけあるの。\n\nこの箱の中に、私のとても大切なbellが入っているわ。その音が大好きなの。約束するわ、私がふらっといなくなったら、それを鳴らすだけでいいの。すぐに走って戻ってくるから。", "あんたのこと心配してたんだよ! Shayを家に連れ帰ってくれて本当にありがとう、{name}。", "何だって？Shayが逃げ出したら、このbellが役に立つってのか？いやあ、こいつは驚いた！\n\n俺のためにこんなにしてくれたんだ、ほらよ、{name}。", 0x7a831151, 0x0dfd54bb, 0x78a146db, 0x787391f0, 0x7d16be98, "....." },
  [2846] = { "Tiara of the Deep", "Dustwallow MarshのTabethaにTiara of the Deepを渡して下さい。", "ずっと昔、私はTiara of the Deepという美しい装飾品を持っていた。それはきれいなだけじゃなく、使い方を知る者には大きな力をもたらすものだった。\n\nだからそのtiaraの噂がHydromancer Velrathaの耳に入ると、彼女はどうしても欲しくなったのさ。私の留守中に手下を家に送り込んで、盗ませたんだ。盗人どもめ！\n\ntiaraを取り戻したい！ Tanarisにあるトロールの都市、Zul'Farrakへ行き、Velrathaを見つけて、tiaraを奪い返してくれ。持ち帰ってくれれば、恩に着るよ。", "tiaraは持っているか、{name}? Velrathaは私に逆らう代償を思い知ったか?", "素晴らしい！見つけてくれたのか！そして同じくらい大事なのは――Velrathaがもうそれを持っていないということだ！ありがとう、{name}。この恩は一生忘れない！\n\nそれと、さっきは少し……きつい物言いだったかもしれないが、気にしないでくれ。私から盗んだりしない者には、ずっと優しい人間だと分かるはずだ。", 0x9db75a34, 0x182805f8, 0xea00f20d, 0xe3059e4c, 0x116c565f, "....." },
  [2847] = { "荒々しい皮防具", "Feathermoon StrongholdのPratt McGrubbenにThick Leather 10枚を渡して下さい。", "{name}、君は革細工師としてかなりの腕になってきたね！ 君が興味を持ちそうな型紙を知っているよ……Wild Leatherの防具さ！ Wild Leatherは、緑豊かな地域やそこに住む一部の生き物から採れるwildvinesの、強力で混沌とした性質を利用するんだ。それを使って作った防具は、君ほどの腕の者にとっては間違いなく最高の品だよ。\n\n教えてあげるけど、しばらくは私のために働いてもらうよ。最初の代価は、thick leatherを10枚だけだ。その後で詳しい話をしよう。", "言ったとおり、Wild Leatherの防具について学ぶ間は私のために働いてもらう。wildvineは強力でありながら気まぐれでもあるから、君が作る元々頑丈な防具に、ランダムだが強力な恩恵を与えてくれるんだ。だが、この知識を手に入れるのは私にとっても簡単ではなかった。\n\nこの工程を始めるための最初の代価は、thick leatherを10枚だ。\n\nそれが済んだら、型紙を手に入れるために君がやるべき仕事に取りかかろう。", "さて{name}、仲間に加わってくれて嬉しいよ。革職人として賢い決断をしたな。Wild Leatherの防具を一つでも作れるようになれば、革の鎧を身につける者たちが我先にと押しかけてくるだろう。\n\nさあ仕事にかかろう。どこから始めたい？", 0x053a8360, 0xf6a18def, 0x5c5bf7ef, 0x62f7bc20, 0xfcbb1f9d, "....." },
  [2848] = { "Wild Leather Shoulders", "Thick Armor Kit 6つとWildvine 1つをFeathermoon StrongholdのPratt McGrubbenに渡して下さい。", "Wild Leatherのショルダーは着る者の体格を非常によく支え、上腕と肩そのものを一流の防御で守ってくれる。すべてのWild Leather防具と同じく、wildvineを縫い込む際に、強力だがランダムな恩恵が品に宿るんだ。\n\nこの型紙には、thick armor kitsを6つとwildvineを一つ用意してもらう。君にとってはそれほど難しい注文じゃないはずだよ。", "頼んでおいたthick armor kit 6個とwildvineは持ってきたか?\n\n防具キット作りを単調な作業だと思わないことだ。このキットで腕を振るううちに身につく着実な作り方が、Wild Leatherの防具作りに必要な精緻な仕事の腕を磨いてくれるんだ。\n\nほらな、君が私のために作っている物には、ちゃんとした理由があるんだよ……", "このarmor kitはしっかりした出来だ、{name}。自分の仕事にも、雇っている者の仕事にも、私が一つだけ求めるものがあるとすれば、それは品質だ。\n\nこの型紙を得るにふさわしい働きだった。私にもたらしてくれたのと同じ実りを、あなたにももたらすことを願うよ。", 0x765de05b, 0x5fd85b49, 0xebba0586, 0xc673456c, 0xddffc6c0, "....." },
  [2849] = { "Wild Leather Vest", "Turtle Scale Breastplate 2着・Turtle Scale Gloves 2つ・Wildvine 1つをFeathermoon StrongholdのPratt McGrubbenに渡して下さい。", "Wild Leatherのベストは、Wild Leather防具一式の要だ。ベストの骨組みがwildvineと溶け合い、胴体を最大限に守りつつ、強力な魔力が衣服全体に行き渡る品が出来上がるんだ。\n\nこの型紙には、Turtle Scale breastplatesを2つ、Turtle Scale glovesを2組、それにwildvineを一つ用意してもらう。大変な注文だけど、君ならほとんど苦労せずに揃えられるはずだ。", "注文しておいたTurtle Scale breastplateとglovesを2つずつ持ってきたか? それと、wildvineも忘れるなよ!\n\nごく初期の型紙からでも、形の基本はより難しい衣服にうまく応用できると学べる。品物は違っても、Turtle Scale breastplateの形は、Wild Leather vestを作るのに必要な細部の仕上げへの準備になるんだ。\n\nそれでglovesは……まあ、あれは私自身のためだ。忘れるな、君は私のために働いているんだぞ!", "どれも実にいい出来だ、{name}。これらに込められた技と丁寧さだけでも、並の品より銀貨数枚は高く売れるだろう。\n\nあなたは私の注文を満たしてくれた。それに伴う報酬だ。Wild Leatherのベストを作る知識は、これであなたのものだ！", 0x762367c6, 0xe2688b0f, 0xcfbb37a9, 0x84b4761f, 0x4389a2a4, "....." },
  [2850] = { "Wild Leather Helmet", "Nightscape Tunic 2着・Nightscape Headband 2つ・Wildvine 一つをFeathermoon StrongholdのPratt McGrubbenに渡して下さい。", "Wild Leatherの兜は、着け心地を犠牲にすることなく、頭の急所を優れた防御で守ってくれる。すべてのWild Leather防具と同じく、組み込まれたwildvineが兜の骨組みに強力だがランダムな強化をもたらすんだ。革を着る者なら、きっとこの一品を欲しがるよ！\n\nこの型紙には、Nightscape tunicsを2つ、Nightscape headbandsを2つ、それにwildvineを一つ用意してもらう。この注文を果たせば、型紙は君のものだ！", "そのtunicとheadbandを作ってもらわないとな。それにそのwildvineも必要だ。それが揃ってから、Wild Leather helmetの知識を教えてやろう。\n\n拍子抜けするほど簡素なヘッドバンドであれ、頭全体を覆う兜であれ、頭防具は冒険者の間で非常に人気がある。価値ある頭防具を作る基本は、見た目がどうであれ変わらないものだ。", "提供してくれたこのNightscapeの装備は、注文を完璧に満たしている、{name}。あなたほどの腕の革職人なら当然のことだ。\n\nこの型紙は間違いなくあなたが勝ち得たものだ。惜しみなく差し上げよう。それで相応の利を得ることを願う。", 0xa93a2f88, 0xb3a4a52f, 0x276d4784, 0xe1bd53bd, 0x944bc44f, "....." },
  [2851] = { "Wild Leather Boots", "Nightscape Pants 2着・Nightscape Boots 2足・Wildvine 2つをFeathermoon StrongholdのPratt McGrubbenに渡して下さい。", "もうずいぶん学んだね、{name}。でも、まだ学ぶことはある。次はWild Leatherのブーツ、どんな一式にも欠かせない要の品だ。\n\nこのブーツは、冒険の危険から足を守りながら、心地よく包み込むように作られている。柔らかな靴底は、静かに動きたい者にとってありがたいものだよ。\n\nこの型紙には、Nightscape pantsを2つとNightscape bootsを2つ揃えてもらう。それにwildvinesも2つ必要だ……1つじゃなくてね。全部揃ったら知らせてくれ。", "型紙を渡す前に、pants、boots、wildvineの注文を満たしてもらう必要がある、{name}。終わったか?\n\n最初に作り方を覚えるブーツから、良質なブーツは快適さと機能のぎりぎりの境界を歩まねばならないと分かり始める。その両方を備えてこそ、質の劣る品を身につけた者なら動けなくなるほどの疲労も、着用者が気にせずにいられる品を作れるのだ。", "またしても、熟練した職人技でもって複雑な注文をこなしてくれたね。この型紙と私からの感謝の気持ちは君の物だ。", 0x1661d982, 0x0127e602, 0xbe8c2905, 0xa24c5cd2, 0x9e668019, "....." },
  [2852] = { "Wild Leather Leggings", "Turtle Scale Helm 2つ・Turtle Scale Bracers 2つ・Wildvine 2つをFeathermoon StrongholdのPratt McGrubbenに渡して下さい。", "基本はもう身についたから、もっと複雑な品に挑む準備ができているね、{name}。Wild Leatherのレギンスは、革装備の中でも指折りの頑丈さと力強さを誇る。腰、太もも、ふくらはぎ、そして急所――すべてが途方もない防御で守られる。それにwildvineがもたらす強化が加われば、これを持つ冒険者たちは君に会うたびに感謝するだろう。\n\nこの型紙には、Turtle Scale helmsを2つ、Turtle Scale bracersを2つ、そしてwildvinesを2つ揃えてもらう。", "Turtle Scale bracersとhelmの用意はできたか? 必要なwildvine 2本も忘れるなよ!\n\nそろそろ、Wild Leatherの防具に秘められた力に気づき始めた頃だろう。用途に限りのない防具は、革細工師にとってほとんど計り知れない価値がある。限界は品を作る資源の量だけで、完成品の質ではないんだ!", "またしても、あなたは注文を寸分の狂いもなく満たしてくれた。いつか私のほうがあなたに知識を求めに来ることになるかもしれんな、{name}？\n\nこれがレギンスの型紙だ、感謝とともに受け取ってくれ。この知恵を身につけ、あなたの見事な腕を仕上がりに存分に生かしてくれ。", 0xb8e345b1, 0xd7de4f84, 0xe55cc30f, 0xb19aa2de, 0x098b510c, "....." },
  [2853] = { "Wild Leatherの完全な習得", "Pratt's LetterをDarnassusのmaster leatherworker Telonisに渡して下さい。", "さて{name}、君はまさに勤勉そのものだ。Wild Leather防具の型紙は、あと一つ残っている。他のものはすべて身につけたね。この型紙のために無駄に骨を折らせるつもりはない。君はもう十分以上にそれを手にする資格がある……だが、私自身が君に渡すことはできないんだ。私の師、私をこの道に導いてくれた人こそが、君に報いるべきなんだ。\n\nこの手紙をTelonisのところへ持っていってくれ。彼はDarnassusで革細工を教えている。手紙を見せて、私と同じように、君を対等な者として認めてもらうといい。", "ごきげんよう、{race}……その顔つきから、あなたも私と同じ革細工師だと分かります。私の技を学びに来たのですか、それとも他に何かご用がおありですか?", "ああ、Prattがあなたを寄越したのですね。彼は人間ですが、時折われわれナイトエルフを思わせるところがあります。革に対する彼の献身と才は見事なものです。その彼がこの手紙でこれほどあなたを称えるのなら、それは私も認める敬意の証です。\n\n彼があなたにWild Leatherの技を教えたことは承知しています。あなたの修業はこの型紙で仕上げさせてください。有効に使ってください。Wild Leatherのマントの秘密を知る者は、この世界にもほとんどいないのですから。", 0x0b03020c, 0xc396a4c4, 0xf694056c, 0xb2e5d777, 0x1241932d, "....." },
  [2854] = { "荒々しい皮防具", "Camp MojacheのJangdor SwiftstriderにThick Leather 10枚を渡して下さい。", "{name}、革細工師としてのお前の腕前は聞いている。俺は、お前が身につけておくべき革細工の知識を持っている……Wild Leatherの防具だ！ Wild Leatherは、緑豊かな地域やそこに住む一部の生き物から採れるwildvinesの、強力で混沌とした性質を利用する。それを使って作った防具は、お前ほどの腕の職人にとって間違いなく最高の品だ。\n\n教えてやるが、しばらくは俺のために働いてもらうぞ。最初の代価は、thick leatherを10枚だけだ。その後で詳しい話をしよう。", "はっきりさせておこう。Wild Leatherの防具の技を学ぶ間、君は私の弟子となる。wildvineは強力でありながら気まぐれでもあるため、君が作る元々頑丈な防具に、ランダムだが強力な恩恵をもたらす。だが、この知識を得るのは私にとっても容易ではなかった。\n\nこの工程を始めるための最初の代価は、thick leatherを10枚だ。\n\nそれが済んだら、型紙を手に入れるために君がすべき仕事に取りかかろう。", "さて{name}、弟子として迎えられて嬉しいぞ。革職人として賢い決断をしたな。Wild Leatherの技を修める術を身につければ、革の鎧を使う者たちが我先にと押しかけてくるだろう。\n\nさあ仕事にかかろう。どこから始めたい？", 0x053a8360, 0x4b71ee49, 0xea03e2b5, 0x692a5bf2, 0x7033c860, "....." },
  [2855] = { "Wild Leather Shoulders", "Thick Armor Kit 6つとWildvine 1つをCamp MojacheのJangdor Swiftstriderに渡して下さい。", "Wild Leatherのショルダーは着る者の体格を非常によく支え、上腕と肩を優れた防御で守る。すべてのWild Leather防具と同じく、wildvineを縫い込む際に、ランダムだが非常に強力な強化が品に宿るのだ。\n\nこの型紙には、thick armor kitsを6つとwildvineを一つ用意してもらう。お前にとってはそれほど難しい注文ではないはずだ。", "必要なthick armor kit 6個とwildvineは持ってきたか?\n\n防具キット作りは、着実で確かな製作の授業だと考えるといい。このキットで腕を振るううちに身につく一貫した作り方が、Wild Leatherの防具作りに必要な精緻な仕事の腕を磨いてくれる。\n\nどの授業にも目的があるのだ、{name}。一つひとつをしっかりと受け止めることが大切だ。", "このarmor kitはしっかりした出来だ、{name}。自分の仕事にも、教えを授ける者の仕事にも、私が一つだけ求めるものがあるとすれば、それは品質だ。\n\nこの型紙を得るにふさわしい働きだった。私にもたらしてくれたのと同じ実りを、あなたにももたらすことを願うよ。", 0x765de05b, 0x56e3ec88, 0x26cd7091, 0x81b4f39f, 0xf1b34312, "....." },
  [2856] = { "Wild Leather Vest", "Turtle Scale Breastplate 2着・Turtle Scale Gloves 2つ・Wildvine 1つをCamp MojacheのJangdor Swiftstriderに渡して下さい。", "Wild Leatherのベストは、Wild Leather防具一式の要だ。ベストの骨組みとその中に織り込まれたwildvineが、胴体を最大限に守りつつ、強力な魔力が衣服全体に行き渡る品を生み出すのだ。\n\nこの型紙には、Turtle Scale breastplatesを2つ、Turtle Scale glovesを2組、それにwildvineを一つ用意してもらう。簡単な修行ではないが、お前なら確かにやり遂げられる腕がある。", "Turtle Scale breastplateとglovesを2つずつ持ってきたか? それと、wildvineも忘れるな!\n\nごく初期の型紙からでも、形の基本はより難しい衣服にうまく応用できると学べる。品物は違っても、Turtle Scale breastplateの形は、Wild Leather vestを作るのに必要な細部の仕上げへの準備になるのだ。\n\n授業を進めるにつれ、私が教える技は芸術のようになっていくだろう。", "どれも実にいい出来だ、{name}。これらに込められた技と丁寧さは、あなたがこの務めに全力を捧げる道を選んだことを示している。\n\nあなたは私の求めに応えてくれた。それに伴う報酬だ。Wild Leatherのベストを作る知識は、これであなたのものだ！", 0x762367c6, 0x8af7a605, 0x0f2311f8, 0x068164b1, 0x32236632, "....." },
  [2857] = { "Wild Leather Helmet", "Nightscape Tunic 2着・Nightscape Headband 2つ・Wildvine 一つをCamp MojacheのJangdor Swiftstriderに渡して下さい。", "Wild Leatherの兜は、着け心地を犠牲にすることなく、頭の急所を優れた防御で守る。すべてのWild Leather防具と同じく、組み込まれたwildvineが兜の骨組みに強力だがランダムな魔力を宿らせる。革を着る者なら、きっとこの一品を欲しがるだろう！\n\nこの型紙には、Nightscape tunicsを2つ、Nightscape headbandsを$N1つ、それにwildvineを一つ用意してもらう。この修行を終えれば、型紙はお前のものだ！", "そのtunicとheadbandを作ってもらわないとな。それにそのwildvineも必要だ。それが揃ってから、Wild Leather helmetの知識を教えてやろう。\n\n拍子抜けするほど簡素なヘッドバンドであれ、頭全体を覆う兜であれ、頭防具は冒険者の間で非常に人気がある。価値ある頭防具を作る基本は、見た目がどうであれ変わらないものだ。", "提供してくれたこのNightscapeの装備は、私が出した条件を完璧に満たしている、{name}。あなたほどの腕の革職人なら当然のことだ。\n\nあなたはWild Leatherの兜を作る栄誉を勝ち得た。この型紙は惜しみなく差し上げよう。それで相応の利を得ることを願う。", 0xa93a2f88, 0xecd7e157, 0x7bcdc51b, 0xe1bd53bd, 0xf8efbed3, "....." },
  [2858] = { "Wild Leather Boots", "Nightscape Pants 2着・Nightscape Boots 2足・Wildvine 2つをCamp MojacheのJangdor Swiftstriderに渡して下さい。", "Wild Leather防具についてのお前の知識は増している、{name}。だが、まだ学ぶことはある。\n\nWild Leatherのブーツは、どんな一式にも欠かせない要の品だ。このブーツは、冒険の危険から足を守りながら、心地よく包み込むように作られている。柔らかな靴底は、静かに動きたい者にとってありがたいものだ。\n\nこの型紙には、Nightscape pantsを2つとNightscape bootsを2つ作ってもらう。それにwildvinesも2つ必要だ……1つではないぞ。これらの品が揃ったら、先へ進もう。", "型紙を学ぶ前に、pants、boots、wildvineを私に届けてもらわねばならない、{name}。言ったとおりにしてきたか?\n\n最初に作り方を覚えるブーツから、良質なブーツは快適さと機能のぎりぎりの境界を歩まねばならないと分かり始める。その両方を備えてこそ、質の劣る品を身につけた者なら動けなくなるほどの疲労も、着用者が気にせずにいられる品を作れるのだ。", "再び、熟練した職人技でもって品物を作ったのだな。この型紙と私からの祝いの言葉は君の物だ。", 0x1661d982, 0xb3b1079c, 0xa6d99d3d, 0xd32a3cf5, 0x6f0c5592, "....." },
  [2859] = { "Wild Leather Leggings", "Turtle Scale Helm 2つ・Turtle Scale Bracers 2つ・Wildvine 2つをCamp MojacheのJangdor Swiftstriderに渡して下さい。", "もっと複雑な修行に挑む準備ができたようだな、{name}。Wild Leatherのレギンスは、革装備の中でも指折りの頑丈さと力強さを誇る。腰、太もも、ふくらはぎ、そして急所――すべてが途方もない防御で守られる。それにwildvineがもたらす強化が加われば、これを持つ冒険者たちはお前に会うたびに感謝するだろう。\n\nこの型紙を得るには、Turtle Scale helmsを2つ、Turtle Scale bracersを2つ、そしてwildvinesを2つ用意してもらう。", "Turtle Scale bracersとhelmの用意はできたか? 必要なwildvine 2本も忘れるな。\n\nそろそろ、Wild Leatherの防具に秘められた力に気づき始めた頃だろう。用途に限りのない防具は、革細工師にとってほとんど計り知れない価値がある。限界は品を作る資源の量だけで、完成品の質ではないんだ!", "またしても、あなたは私の課題を寸分の狂いもなくやり遂げた。いつか私のほうがあなたに知識を求めに来ることになるかもしれんな、{name}？\n\nこれがレギンスの型紙だ、感謝とともに受け取ってくれ。この知恵を身につけ、あなたの見事な腕を仕上がりに存分に生かしてくれ。", 0xb8e345b1, 0x612c1276, 0x3a102e0d, 0x792dd5a5, 0xf055bcf5, "....." },
  [2860] = { "Wild Leatherの完全な習得", "Jangdor's LetterをThunder Bluffのmaster leatherworker Unaに渡して下さい。", "{name}、俺が教えられることはすべて教えた。だが、Wild Leather防具の型紙がまだ一つ残っている。これのために無駄に骨を折らせるつもりはない。お前はもう十分以上にそれを手にする資格がある。だが、この型紙は俺が自由に渡せるものではないのだ。\n\n俺の師、俺をこの道に導いた人こそが、お前に報いるべきだ。この手紙をUnaのところへ持っていけ。彼女はThunder Bluffで革細工を教えている。手紙を見せて、俺と同じように、お前を対等な者として認めてもらえ。", "ごきげんよう、{race}……その顔つきから、あなたも私と同じ革細工師だと分かります。私の技を学びに来たのですか、それとも他に何かご用がおありですか?", "ああ、Jangdorがあなたを寄越したのですね。私の最も優れた弟子の一人が、今では自分の弟子を持つようになったとは、喜ばしいことです。\n\n革に対する彼の献身と才は見事なものです。その彼がこの手紙でこれほどあなたを称えるのなら、それは私も認める敬意の証です。\n\n彼があなたにWild Leatherの技を教えたことは承知しています。あなたの修業はこの型紙で仕上げさせてください。有効に使ってください。Wild Leatherのマントの秘密を知る者は、この世界にもほとんどいないのですから。", 0x0b03020c, 0x72f983eb, 0x9cfc7e82, 0xb2e5d777, 0x761c97b8, "....." },
  [2861] = { "Tabethaの仕事", "Dustwallow MarshのTabethaと話して下さい。", "噂では、Dustwallow Marshの奥深くに住むメイジの同僚、Tabethaが、Zul'Farrakのある砂トロールに恨みを抱いているらしい。Tabethaと話せば、もっと詳しく教えてくれるだろう。\n\nそれと仲間を連れていけ、{name}。TabethaにZul'Farrakへ行かされるなら、一人では行きたくないはずだ。\n\nTabethaの小屋はTheramoreの西、Stonemaul Ruinのすぐ北にある。", nil, "その通りだ。あるトロールに片をつけたいことがある。いくつも片をつけたいことがな。あいつの骨という骨すべてにだ！\n\n手伝ってくれるか？", 0x96c81b26, 0x67e27f0b, 0xaa525e99, nil, 0x80cd032f, "...m." },
  [2862] = { "Woodpaw族との戦い", "Camp MojacheのHadoken SwiftstriderにWoodpaw Gnoll Mane 10個を渡して下さい。", "gnollsは……ただの厄介者ではない。この野営地の存続そのものを常に脅かす存在だ！ 奴らがFeralasの土着の者かどうかなど関係ない。奴らに立ち向かう決意を固めなければ、我々はこの地域全体から追い出されることになるだろう。\n\n最近、野営地へのgnollの襲撃はますます激しくなっている。奴らの数を減らすのに力を貸してほしい。奴らのmanesを10個持ってきてくれれば、その働きに十分に報いよう。\n\n行け！", "追い払っても追い払っても、奴らはまだ襲ってくる! 誰か、あるいは何かが奴らを狂乱に駆り立てているに違いない……おお、戻ったか、{name}? 賞金に見合うだけのmanesは持ってきたか?", "これは幸先の良い証だ、{name}。兵士としてのお前の腕前は称賛に値する。\n\nその任務を頼んでいるのはお前だけではない。お前の前にも多くの者が奴らと戦い、これまでは我々の努力で奴らを食い止めてきた。だが最近、奴らが北へ、我々の勢力圏へ押し入ろうとする動きが急激に増している。攻撃もより凶暴になってきた……まるで追い詰められているかのようにな。\n\nだが考えがあるのだ、{name}。奴らとの決着を一気につけられるかもしれん考えがな……", 0xc1b743b5, 0x1ddcdda5, 0x9d52d80c, 0x6b0c27cf, 0xf34890ac, "....." },
  [2863] = { "アルファ攻撃", "Woodpaw Alphaを5頭殺し、一時間以内にHadoken Swiftstriderのところへ戻って下さい。", "計画はこうだ。gnollsの様々な指導者――奴らはAlphasと名乗っている――を立て続けに倒す。このような素早く正確な壊滅的打撃を与えられれば、奴らの隊列に混乱を引き起こせるだろう。そしておそらく、我々は奴らを滅ぼせるし、実際に滅ぼすのだということを、蚤だらけの鈍い頭にも叩き込めるはずだ！\n\n君には我が意志を伝える使者になってもらいたい。これを成功させるには、1時間以内に奴らのAlphasを5体倒すのだ、{name}。さもなければ、我々はこの膠着状態のままだ！", "時間がないぞ、{name}! Alphasを始末したと報告しに来たのでないなら、時間の無駄だ!", "お前は私が頼んだ通りにやってくれた。それには敬意を表する。労に対する報いとして、このささやかな報酬を受け取ってくれ、{name}。\n\n数を減らされ、頭目を討たれた今、gnollどもも野営地へ攻め込むのを考え直すだろう。だが、これで目の前の問題が片づいたわけではない……\n\ngnollどもがこれほど狂乱した状態に駆り立てられているのには、何か理由があるはずだ。奴らが態勢を立て直す前に、その原因を突き止めたい。", 0x8dbc86ab, 0x3dfff3ba, 0xb852b226, 0x1fcc4718, 0xefd117c5, "....." },
  [2864] = { "Tran'rek", "GadgetzanのTran'rekと話して下さい。", "いとこのTran'rekが困ったことになっててさ。何週間も前にscarabの殻をひと山届けるって約束したのに、まだ届いてないんだ。いとこだから、Gadgetzanに誰かを送り込んであいつの何かをぶっ壊させるなんてことはしたくないんだよ。\n\n俺の代わりにTran'rekと話してくれないか？ 俺が早まったことをする前に、その荷をちゃんと揃えなきゃならないって伝えてくれるかい？\n\nGadgetzanはKalimdorのTanaris北部にあるよ。", nil, "やあ！\n\nおや、いとこのKrazekと話したのかい？あいつは元気かな？Booty Bayでうまくやっているといいんだが……\n\nscarab shellだって？ふむ……ひとつ話を聞かせてやろう……", 0x862f6956, 0x08fec570, 0x0c814a4b, nil, 0x87221180, "...m." },
  [2865] = { "甲虫の甲殻", "GadgetzanのTran'rekにUncracked Scarab Shell 5つを渡して下さい。", "Tanarisのscarabsはすごく硬い殻を持ってるんだ！ いろんな物の建材に使えるくらい硬いんだよ。本当にいろんな物にね！\n\n実際、その殻があんまり役に立つもんだから……scarabsは狩られまくって絶滅寸前になっちゃったんだ！\n\nもっとscarabsがいる場所を知ってるんだけど、殻を持ってきてくれるって約束してくれるなら、どこにいるか教えてあげるよ。約束する？\n\nよし、scarabsはZul'Farrakにコロニーを作ってるんだ。トロールは殻目当てにあいつらを狩ったりしないみたいだね。\n\nでも君ならできる！ Zul'Farrakへ行って、uncracked shellsを取ってきてよ！", "shellsは持ってきたかい? Booty Bayにいる俺のいとこがそいつをどっさり待っていて、しびれを切らしてるんだよ!", "おお、よかった！手に入れてくれたんだね！\n\nありがとう、{name}。本当に命の恩人だよ！", 0xaeea837d, 0xb0792b2e, 0x1769c4e1, 0x29ff8a96, 0x096fb397, "....." },
  [2866] = { "Solarsalの遺跡", "Ruins of Solarsalを探索し、そこにいるnagaについて調べて下さい。", "我々の南にはRuins of Solarsalがある。ここは近代よりはるか昔にさかのぼる地域だ。我々は最初にその遺跡を探索したが、目ぼしいものは何も見つからなかった。それで、そっとしておいたのだ。\n\nごく最近になって、Hatecrestのnagaが驚くほどの数でその遺跡を占拠した。最初は攻撃の前触れだと考えた。その脅威はまだありうるが、何か別のことが起きているのではないかと我々は考えている。\n\nそこへ行って遺跡を探索し、目につくものがないか探してくれ。幸運を祈る、{name}。", nil, "あずまやを調べると、周囲の遺跡とは対照的に、興味深く珍しいものがいくつか見つかった。\n\nまず、あずまやは明らかに遺跡の他のものより新しい建造物だ。次に、あずまやの側面には小さなグリフが連なって刻まれている。グリフは模様を繰り返しているが、それ以外に由来も意味も分からない。そして、あずまやの石そのものが触ると温かい。\n\n遺跡の調査で「目立つもの」と言えば、間違いなくこれだろう！", 0x1a50d962, 0xc3dae690, 0x5322883e, nil, 0x5f67c7ca, "...m." },
  [2867] = { "Feathermoon Strongholdへ戻る", "Feathermoon StrongholdのShandris Feathermoonのところへ戻り、調べて分かったことを報告して下さい。", "Ruins of Solarsalの中心で奇妙なあずまやが見つかった今、Feathermoon Strongholdへ戻り、ここで見つかったことをGeneral Shandris Feathermoonに報告する時が来た。", nil, "おかえり、{name}。このあずまやについての報告は実に……不穏だ。たとえそこのnagaが攻撃を計画していなかったとしても、奴らが居座り続けることは、我々のFeralas進出にとって不吉な兆しのようだ。いずれにせよ、これが調査の報酬だ。\n\nFeathermoon Strongholdは、Hatecrestのnagaについてさらなる援助を切実に必要としているようだ。その気があるなら、君にその任務を任せたい。やるべきことは山ほどある。", 0xeef1a527, 0x9e8c4317, 0xa7312d25, nil, 0x90a88c18, "...m." },
  [2869] = { "Hatecrestとの戦い", "Hatecrest Naga Scalesを$N1枚、Feathermoon StrongholdのLatronicus Moonspearのところへ持って行って下さい。", "現時点で最善の策は、nagaが何を企んでいようと、いずれはこの島を自分たちのものにしようと動くと想定しておくことだ。手遅れになる前に、その脅威に対抗する積極的な手を打たねばならん。\n\n状態の良いHatecrest Scalesを十枚持ってこい。どうやって手に入れるかは、言わなくても分かるはずだ。お前はnagaを相手に初めての経験を積み、我々はSardor Isleでのnagaの勢力を弱められる。どちらも我々に有利に働く見込みだ。", "{name}、与えられた任務の確認に来たのなら結構だ。私が求めているのはHatecrest scales 10枚だ。世間話をしに来たのなら、今はそのような些事に付き合う暇はない。\n\nこれだけは知っておけ。我々ナイトエルフは戦争屋ではない。我らの種族は平和と調和を守ることに身を捧げている。だが、それは我々が自らの利益を先んじて守らないという意味ではない。これこそがGeneral Feathermoonと、この砦に対する私の務めなのだ。", "よし、よし、このscalesは申し分ないどころではないな。実のところ、これはPrattのところへ送って見てもらおうと思う。彼ならこれで何か役に立つものを作れるかもしれん。\n\n君には、また別の任務に出てもらいたい。だがまずは、scalesの報奨金だ。将軍と、ひいてはFeathermoon Stronghold全体への君の変わらぬ奉仕は、逆境にあって何よりの恵みだ。", 0xbaae3916, 0xd7179155, 0xeb518da8, 0xfcde299e, 0x7ea356dc, "....." },
  [2870] = { "Lord Shalzaruとの対決", "Lord Shalzaruを始末し、彼が掘り出したMysterious RelicをFeathermoon StrongholdのLatronicus Moonspearのところへ持って行って下さい。", "{name}、新たな偵察報告で、nagaの指揮系統がかなり分かってきた。奴らの兵の中には王族がいて、そいつらがすべての命令を下しているのだ。\n\n具体的には、王族の中でも特に残忍な一人を、Lord Shalzaruだと突き止めた。斥候の報告によると、奴自身が、最近のnagaの発掘で奇妙なrelicを掘り出したという。場所は主要な遺跡の南、水を渡ったIsle of Dreadの洞窟だ。\n\n奴を止めることで、それを止めろ。そして奴のrelicを持ってこい。研究するのだ。", "Lord Shalzaruを倒せば、奴らの計画は数か月とは言わずとも、確実に数週間は遅れるだろう。その上、奴が掘り出したrelicは我々にとって間違いなく興味深いものだ。\n\n与えられた任務は果たしたか、{name}?", "見事だったぞ、{name}！Lord Shalzaruの死によって、nagaは永久にとは言わずとも、しばらくは混乱に陥るだろう。奴らの脅威はかつてないほど我々の制御下にあり、それは君のおかげだ。\n\nこれは砦の金庫から出た追加の報奨金だ……君は銅貨一枚残らず稼いだんだ。君と君の仲間は、いつでもFeathermoon Strongholdに歓迎されるよ、友よ。\n\n出発する前にもう1つだけ、{name}……もしよければ……", 0x5abae5df, 0x7d196789, 0x1ba18bcf, 0x9dbe60bd, 0x94b155f8, "....." },
  [2871] = { "遺物の配達", "Mysterious RelicをFeathermoon StrongholdのVestia Moonspearに届けて下さい。", "よければ、このrelicを妻のVestiaに届けてもらえるとありがたい。妻は我々の共同体の立派なプリーストであるだけでなく、どこを探してもそうはいないほど博識な学者でもあるんだ。私には、たとえ賭けがかかっていたって、この装置がさっぱり分からない。だが妻なら、これが何なのか分かる者がいるとすれば、妻だ……それに、我々はそれを知る必要がある！\n\n妻はすぐそこの角を曲がったところにいる。きっと研究中だろう。ありがとう、{name}。", "はい、何かご用かしら?\n\n待って、あなたはGeneral FeathermoonとLatroのnaga対策を手伝ってくれている{class}よね? 私はVestia、Latroの……いえ、Latronicusの妻です。お会いできて嬉しいわ!\n\nごめんなさい、もちろんお仕事で来たのよね。私に何か持ってきてくれたの……もしかして、彼から?", "興味深い……これはRuins of Solarsalから来たと言うのか？まあ、Latroの言うとおり、私が見るべきものだな。一見したところ、遺跡に元からあったものではなさそうだ。とはいえ、nagaの意匠でもない……これほど異質なものは。\n\nこの品を調べるには時間がかかりそうだ。調査が終わったら、君がこの辺りにいれば、その才能を借りるかもしれない。\n\nほら、余っている品を1つ持っていってくれ。何かの役に立つといいんだが！", 0x9554d08d, 0x0650d9f2, 0x4aa6c818, 0xd2302486, 0x691ff389, "....." },
  [2872] = { "Stoleyの借り", "Steamwheedle PortのStoleyと話して下さい。", "古い相棒のStoleyが、とびきり特別なラム酒を一本俺に借りてるんだ。あいつはKalimdorのTanarisにあるSteamwheedle Portで酒場をやっていて、そこのラム酒はBooty Bayで手に入るどんな酒よりも強いって約束しやがった。自信満々で、もし俺がそのラム酒を飲んで同意しなかったら、俺への借金を倍にするとまで言ったんだ！\n\nだがな、最後に話した時ほどの自信はもうないんだろうよ。今じゃあのラム酒を渡すのを怖がってやがる。だが俺は賭けから逃げたりしねえ。だから、俺の代わりにあいつと話してきてくれないか……", nil, "ああ、MacKinleyと話してきたんだな？\n\nあいつが思っているようなことじゃない！Steamwheedle Bilge Rumを渡すのが怖いわけじゃないんだ……\n\nただ、渡せるラム酒が手元にないだけなんだよ！", 0x5fe16894, 0x0eecc166, 0x10ebc4de, nil, 0x2b1e2d44, "...m." },
  [2873] = { "Stoley's Shipment", "Stoley's ShipmentをSteamwheedle PortのStoleyに渡して下さい。", "賭けの清算のために、Booty Bayの\"Sea Wolf\" MacKinleyにラム酒を借りてるんだが、ラム酒がすっかり切れちまったんだ！ Captain Cuergoの奴が俺の最後の積荷を盗んで、南にある壁に囲まれた海賊の町にしまい込んでやがる。\n\n俺のラム酒の積荷を見つけて持ち帰ってくれれば、Kalimdorの酒のほうがBooty Bayの酒よりもはるかに上だってことをMacKinleyに証明できるんだ！", "俺のラム酒のshipmentは見つかったか、{name}?", "すごい、取り返してくれて感謝してるよ! これでついにMacKinleyの奴と俺の賭けもけりがつけられる。", 0xebea37eb, 0x90075e4c, 0xd6d71b9a, 0x77e5cbb1, 0x532d7415, "....." },
  [2874] = { "MacKinleyへの配達", "Stoley's BottleをBooty Bayの\"Sea Wolf\" MacKinleyに届けて下さい。", "あんたにはもう一度礼を言うよ、{name}。これがSteamwheedleラム酒樽のボトルだ。こいつをMacKinleyのところへ持ってってやれば、Booty Bayの酒への心酔も落ち着くことだろうよ。", "Stoleyの奴、俺の酒を出したか?", "ふむ、試してみるか……\n\n信じられん！これは……ひどい味だ！最高じゃないか！\n\nまあ、Stoleyには借りている金をそのまま持たせておいてやろう。Steamwheedleのbilge rumについては、あいつは言葉通りの男だった。あれは砂利のようにどろりとしていて、溶岩のように焼けつくぞ！", 0x6a990bcc, 0xb6815583, 0x3a92f2f5, 0xfdfa4434, 0xdd7d2488, "....." },
  [2875] = { "お尋ね者: Andre Firebeard", "Andre's HeadをSteamwheedle PortのSecurity Chief Bilgewhizzleに渡して下さい。", "卑劣な海賊Andre Firebeardは、SteamwheedleおよびGadgetzanに対する罪により手配されている。\n\n統治評議会の布告により、これを読む者は皆、Andreおよびその共犯者の捕縛にあたり、致死的な武力を行使することをここに認められる。\n\nさらなる布告により、審問の時点でAndreが死亡しているか、あるいはその他の理由で出廷できない場合には、その首をもって代理とすることができる。そしてその首をSecurity Chief Bilgewhizzleに引き渡すことは、拘束力を有し、かつ履行可能な契約を構成するものとする。", "少しぼーっとしてるね。うちの法律文書でも読んでたのかい?", "ああ、Andreの首か。これなら結局あいつも裁判に出られるというわけだ！\n\n感謝する、{name}。さあ、ここに署名してくれれば、働きに対する支払いができる。\n\n細かい字の部分は気にするな。害はないし……それに、あれを読めるほど小さな拡大鏡などないと思うぞ。", 0xc88ca7ef, 0x26984e62, 0x0a8a207a, 0xd8992961, 0x7b9eba8f, "....." },
  [2876] = { "船の予定表", "Ship SchedulesをSteamwheedle Portの権力者に伝えて下さい。", "この巻物には、Steamwheedle PortとBooty Bayの間の積荷の運航予定が記されている。過去と今後の積荷の両方が船名とともに載っており、いくつかの船の航海の横には大きな「X」印が、別の船の横には「お宝たっぷり」や「激戦」といった書き込みがある。\n\nSteamwheedle Portの誰かが、この文書を見たがるだろう。", "息が切れてるね。何か知らせでもあるのかい?", "おやまあ、これは船の出港と入港の一覧のようですね。正確な日付も時刻も何もかも載っている！海賊船の船長がこれを手に入れたら、やりたい放題でしょう！\n\nこれを海賊から手に入れたと？それは穏やかではない知らせですね……\n\nありがとう、{name}。あなたが奴から奪ってくれてよかった。そしてその海賊が今は土を食らっているというのも、実によいことです！", 0xaf794933, 0x3f74c8bd, 0x53de1d3d, 0x4efbf817, 0xfe6ccd46, "....." },
  [2877] = { "Skulk Rockの掃除", "Green Sludgesを$N1体とJade Oozesを$N2体倒し、Aerie PeakのFraggar Thundermantleに報告して下さい。", "俺たちWildhammersは、Ironforgeの兄弟たちよりも過去をよく覚えてる。ここで仲間を作りたいなら、俺たちのために手を汚すんだな！\n\nHordeはHinterlandsのSkulk Rock周辺の陣地を捨てていった。今じゃ、汚らしいsludgesとoozesだらけだ。俺たちにはあの一帯についての計画があるんだが、まずは道を切り開く掃除屋が要る。\n\nそこでお前の出番だ、Sunshine！ あそこへ下りていって、green sludgesを十体とjade oozesを十体片づけて、ここの俺に報告しろ。行け！", "目の前の任務について交渉しようなどと思うなよ、{race}! 神々があのoozesを殺したいと思っていたなら、今ごろ奇跡でとっくに片付けているはずだろう?!", "おやおや、Wildhammerの手伝いをしてくれるとはな！お前さんは行動の{class}だ。そして行動こそ、ここで俺たちが重んじるものさ。\n\nお前さんのちょっとした掃除任務は、思ってるよりずっと重要なんだ。oozeやsludgeを減らしてくれる者がいれば、あっという間に俺たちの勢力圏を広げられる。ほら……Aerie Peakで新しい友を作れただけじゃなく、ちょっとした物もやろう！", 0x6eb9a3b3, 0x0979fe95, 0x047d59fd, 0xf3a93aaa, 0x8efbe603, "....." },
  [2879] = { "Stave of Equinex", "Troyas' Staveに力を込め、Equinex Monolithを見つけて下さい。", "このstaveは、Stave of Equinexかもしれません！ Stave of Equinexは実は鍵で、Dream Boughの西の本土にあるRuins of RavenwindのEquinex Monolithを開くために使われるものなのです。\n\nその遺跡で今も燃え続けている四つの炎、Samha、Imbel、Byltan、Lahassaを見つけてください。それらのエッセンスを集めたら、Equinex Monolithのそばに立って、エッセンスを使ってstaveに力を与えるのです。これが本当にStave of Equinexなら、Monolithを開いて、そこから神聖な遺物を手に入れられるでしょう。", "Equinex Monolithが廃墟の中に静かにそびえている。いったい何を秘めているのだろうか?", "エネルギーを帯びたstaveを握っているのはほとんど不可能だ。その力が体中を轟くように駆け巡る。\n\nEquinex Monolithの冷たい表面に手を伸ばす……\n\n小さな扉が開き、手を入れて中の遺物を取り出せるようになった。\n\n光の筋がEquinex Monolithの周囲を満たす。", 0x77176a60, 0xe2718895, 0xd421c18b, 0xea8f6acc, 0x5cf47a0c, "....." },
  [2880] = { "トロールの首飾りの懸賞金", "Troll Tribal Necklacesを$N1個、Aerie PeakのFraggar Thundermantleのところへ持って行って下さい。", "よく覚えとけ、{race}。俺たちはAllianceの一員なんかじゃない！ Wildhammersは独立してる。自分の価値を示すのは行いと働きで、何もしない態度をべらべらとしたおしゃべりで飾り立てる連中の戯言じゃないんだ！\n\nここで仲間を探してるなら、まず俺たちに価値を示せ！ Hinterlandsの丘の斜面にひしめく汚らわしいトロールどもは、ときどきtribal necklacesを持ってる。五つ持ってきたら、お前にとって正しい方向への一歩として記録しといてやる。", "トロールどもが身に着けているtribal necklacesを5つ欲しい。もっと詳しく言わなきゃ分からんのなら教えてやるが、奴らを1匹殺せば、1つ手に入る見込みは十分にあるぞ!\n\nWildhammersに己の価値を示せ!", "そうこなくっちゃ！ほらな……このnecklaceは、お前さんが手を汚すのをいとわないって証だ。俺たちWildhammerは、付き合う相手のそういうところを大事にするのさ。\n\nこの調子で続ければ、じきに俺たちに気に入られるだろうよ。", 0x53d7f0f7, 0xace2f057, 0x03782ded, 0xc50f9dc0, 0x7300fcde, "....." },
  [2902] = { "Woodpaw族の調査", "Camp Mojacheの南に向かい、gnollキャンプ地のどこかにある戦闘計画書を見つけて下さい。", "Gnollsは決して賢い連中ではないが、最近の行動について何らかの戦略を書き残しているはずだ。その計画書を見つけられれば、何が奴らをこれほど駆り立てているのか、もっとはっきりわかるだろう。\n\nWoodpawのところへ戻って、奴らの戦闘計画らしきものを何でもいいから見つけてきてほしい。何かあるはずだ。それなしでは、あれほど統率の取れた襲撃はできない。見つけたら、私のところへ戻ってきてくれ。", nil, "地図を調べると、これがHadoken Swiftstriderの求めている作戦図だと分かる。兵の動きを表すと思われる矢印が数多く描かれているが、そのほとんどはCamp Mojacheのある北ではなく、南へ向かっているようだ。\n\n地図の別の部分には、大型の昆虫らしきものの絵と、その下にいくつもの印が記されている。gnollどもの様子からすると、これは正体不明の虫たちに対する彼らの損害を表しているのかもしれない……", 0x04f1cc63, 0x5e53674b, 0xc7a041ff, nil, 0x54b4b8f0, "...m." },
  [2903] = { "戦闘計画書", "Woodpaw Battle PlansをCamp MojacheのHadoken Swiftstriderに渡して下さい。", "gnollの戦闘計画書を発見したので、あとはこの計画書をCamp MojacheのHadoken Swiftstriderのところへ持ち帰るだけだ。彼か、もしくはあそこにいる他の誰かならば、gnollが何を企んでいるのか見抜くことができるだろう。", "おかえり、{name}。gnollsの計画について、何か確かな証拠は見つかったか?", "ああ、まさにこれが必要だったのだ。この地図の走り書きの大半を読み解くほどの腕は私にはないが、これまでに十分な数の作戦図を見てきたから、gnollどもに何が起きているかは分かる。奴らは今、二正面の戦いをしているようだ。一方は我々との戦い……だが、奴らの力の大半は南にいる敵に向けられているらしい。\n\nここには見た目以上のものがある。奴らが相対しているもう一方の敵が何者なのか、そろそろ突き止める時かもしれん。", 0x77bc1308, 0x6b0805ca, 0x100a6847, 0xa2808308, 0xfa142672, "....." },
  [2904] = { "えらいめに遭って", "Clockwerk Run出口までKernobeeを護衛し、Booty BayのScootyに報告して下さい。", "<Kernobeeがうめく。> な……何があったんだ？\n\n最後に覚えているのは、dark ironのドワーフの一団に捕まって、死ぬ寸前まで殴られて、それからこの汚らしいtroggsと一緒にここへ放り込まれたことだ。\n\nここから出してくれ、{name}！\n\n計画はこうだ。僕を出口まで連れていってくれ。生きて出られたら、君はBooty Bayへ行ってScootyに知らせてくれ。僕がRatchetへ行って、あの超大型装置の製造にdark ironが関わっていることをTinkerwizに警告しに行ったってね。\n\nさあ、行こう！", "え? Kernobeeが生きてるって??", "Kernobeeを無傷で連れ戻してくれたことは報われるべきだと思う、{name}。Gnomereganへ戻ったら、このことが有利に働くかもしれない。あの能無しの裏切り者Mekgineer Thermapluggを倒すのに必要だろうから。", 0x63147a20, 0xac5b2106, 0x2a36e481, 0x0aeeadf6, 0x70f50dab, "....." },
  [2922] = { "Techbotの頭脳を救え!", "IronforgeのTinkmaster OversparkにTechbot's Memory Coreを渡して下さい。", "私たちの愛する都市Gnomereganが陥落した時、はぐれた火花が私の哀れな発明品、Techbotに衝撃を与えたに違いありません。かつては数え切れないほどの道具と無限の情報の蓄えで私と仲間たちを助けてくれたのですが、その陽電子頭脳が分極してしまったのです。今では陰電子頭脳になってしまい……Techbotの振る舞いは逆転してしまいました。狂乱状態でGnomeregan中をうろついているのです！\n\nでも、まだ救えるかもしれません。Techbotのmemory coreを取り戻して私のところへ持ってきてくれれば、分極の原因を突き止めて、哀れなTechbotを直せるかもしれません。", "Techbotは見つかった? そいつのmemory coreは回収できたの??", "おお、これは素晴らしい！ありがとう、{name}！すぐ作業にかかるよ！！\n\nかわいそうに、かわいそうなTechbot……気を落とすな。ちゃんと直してやるからな。\n\nさて、ハイドロジャック式スイベルスパナのあの差込みをどこに置いたかな……", 0x142b3f91, 0x989bf380, 0xa96aa51e, 0xa4a609b7, 0xbbc02495, "....." },
  [2923] = { "Tinkmaster Overspark", "IronforgeのTinkmaster Oversparkと話して下さい。", "Tinkmaster Oversparkは、自分の機械仕掛けの発明品、Techbotの運命にひどく心を痛めている。Techbotは、ノームたちにとって親切で役に立つ道具だったと覚えているが、Oversparkによると故障してしまったそうだ。\n\n実に悲しいことだ。だが運がよければ、直せるかもしれない！\n\nIronforgeのTinker TownにいるTinkmaster Oversparkと話してくれ。君の助けを歓迎するだろう。", nil, "ああそいつは本当さ。Techbotは統制の利かないはぐれロボットになっちまったんだ! 頼む、手伝ってくれるかい?", 0x50a40f08, 0x98ca0fa7, 0x226d20ab, nil, 0x8a6b241a, "...m." },
  [2924] = { "必要な人工部品", "IronforgeのKlockmort SpannerspanにEssential Artificial 12個を渡して下さい。", "ほぼ万能の機械部品――essential artificial――は、Gnomereganの技術者や鍛冶屋たちにとって大変役に立つものでした。ところが、都市から慌てて逃げ出した時、誰一人としてこの装置を持ち出すのを覚えていなかったのです！ そして、私がまもなく取りかかる仕事には、それが大量に必要なのです。\n\nどうか、Gnomereganへ行って、essential artificialsを取ってきてください。都市の深い区域にある、artificial extrapolatorsと呼ばれる容器の中に入っています。\n\nありがとう、{name}。どうか急いでください！", "essential artificialsは持ってきたかい?", "手に入れてくれたんだね！これで新しい実験を始められる！\n\n感謝してもしきれないよ、{name}！君の勇気がノームの研究を一足飛びに前進させてくれたんだ！", 0xd3e977d4, 0xc9a42ec8, 0xf08a62a3, 0x88153ec4, 0x0a9e26a6, "....." },
  [2925] = { "Klockmortに必要なもの", "IronforgeのKlockmort Spannerspanと話して下さい。", "ノームの友人、Klockmort SpannerspanがIronforgeから知らせを寄こしてきた。Gnomeregan――かつては偉大なノームの都市だったが、今では汚染され、狂ったノームとその装置であふれている――へ入る、危険だが重要な任務に助けが必要だそうだ。\n\n私はここを離れられないが、友を助けたくて胸が痛む。私の代わりに行ってくれるなら、大いに恩に着るよ。\n\nKlockmortはIronforgeのTinkertownにいる。", nil, "私だよ! Gnomereganの作戦に協力を求めているのは私だ。ところであんた、作戦にはうってつけの{class}だな!", 0xd1472bfc, 0x7fe3166f, 0x3f0bf57e, nil, 0x578dfce4, "...m." },
  [2926] = { "Gnogaine", "放射性降下物を集めるためにEmpty Leaden Collection PhialをIrradiated InvaderかIrradiated Pillagerに使用して下さい。瓶がいっぱいになったら、それを持ってKharanosのOzzie Togglevoltのところへ戻って下さい。", "あの事故以来、Gnoarnが考えることも話すことも、Gnomereganからtroggの蔓延を一掃することと、あの都市を蝕む病の治療法を見つけることばかりなんだ、{name}。\n\n幸い、Razzleと僕はある種の治療法にもう少しで手が届きそうなんだ――それか、ものすごく強いラム酒のレシピかもしれない。試してみるまではわからないよ！ 当然、僕らの理論を試すにはいくつか必要なものがある。つまり、Gnomereganの放射能を浴びたtroggsから出る放射性降下物だ。このphialを緑の輝きで満たして持ってきてくれ！", "ここでノームという種族を丸ごと治そうとしてるのが分からないのか??! 緑の輝きがもっと必要なんだ!", "上出来だ! 新たな処方を試す時がきたな。これが効果を示せば、捕まったleper gnomeを治療するだけじゃなく、私のふさふさの髪を取り戻せるはずだ! 下がって見てろ!", 0xf0c05f18, 0xdf69f0fb, 0xa76f5528, 0x20727b89, 0x9b4aacb0, "....." },
  [2927] = { "その次の日に", "KharanosにいるOzzie Togglevoltと話して下さい。", "わしが昔からハゲていたと思っとるのか？ とんでもないぞ、お前さん！ この悲劇的な抜け毛は、Gnomereganの放射能漏れのせいなんじゃ。あの日までは、わしはAzeroth中でただ一人のノーム・アフロの持ち主だったんじゃぞ。\n\n<Gnoarnは空中で拳を振り回す。>\n\n忌々しい、あの薄汚いtroggsめ――どいつもこいつも呪われてしまえ！！\n\nまだ手遅れじゃないかもしれん、{name}。まだ救えるかもしれん――都市のことじゃよ！ KharanosのOzzie Togglevoltと話してくれ。あいつと相棒のRazzleが解決策に取り組んでおる。", nil, "あの見事な頭髪を失って、彼はもう終わりだと思っていたよ。ところが生き延びたんだ！\n\n放射線の一撃を受けたとき、私はすぐ隣に立っていた。あの素敵な茶色の髪がごっそり床に落ちたんだ！束になってね！Gnoarnがすっかり取り乱したせいで、恐ろしさはいっそう増したよ！そうとも、取り乱したんだ！Gnoarnは信じられないという様子で禿げた頭に触れ、その目は復讐を叫んでいた、{name}！そして彼は怒りをtroggどもへ向けたんだ！\n\n<Ozzieは身をすくめる。>", 0xf43f453e, 0xba99320a, 0x80d33f0e, nil, 0xbb58d6a8, "...m.", nil, nil, 0xb6251687, nil, nil },
  [2928] = { "ジャイロドリル式掘削機", "Robo-mechanical Guts 24個をStormwindのShoniに渡して下さい。", "困ったことになったよ、{name}。gyrodrillmatic excavationatorsの車列をDun Moroghまで動かすのに、部品が足りそうにないんだ。\n\n必要なのは予備の部品なんだ、{name}。僕らの乗り物の予備部品を手に入れるのに、Gnomereganほどうってつけの場所があるかい？ あそこじゃボットやメカが放牧地の牛みたいにうろついてるって聞くよ。\n\nGnomereganへ行って、そのロボットたちをばらばらにしてきてほしいんだ。ロボットのgutsを持ち帰ってくれ。2ダースもあれば十分だろう。", "これが競走だったら、あんたはとっくに負けてるよ。", "これはよく使えそうね、{name}。gyrodrillmatic excavationatorが一機修理完了。残り398機。", 0x7c11ff31, 0x78ec2936, 0x740676eb, 0x3fc85274, 0xaf06627a, "....." },
  [2929] = { "重大な裏切り", "Gnomereganに侵入し、Mekgineer Thermapluggを殺して下さい。その仕事を完了したらHigh Tinker Mekkatorqueのところへ戻って下さい。", "私はThermapluggを信頼していたのだ、{race}。まさか彼が私を、そしてノームの民すべてを裏切るとは思いもしなかった。それも何のためだ？ 権力か？ 富か？ いずれも時が来れば手にできたものばかりだ。今や我々は故郷を追われ、あの狂人が支配している。何もない国の王だ……\n\n我々はGnomereganを奪還する、{name}。都市を取り戻すまで、我々は止まらない。我々の戦いに加わりたいのなら、簡単な頼みがある。裏切り者を倒せ。Mekgineer Thermapluggを滅ぼすのだ。", "任務は終わったか? 奴は寛大な処置を乞うたか? 慈悲を??", "奴が地面に崩れ落ちた時、最後に頭に思い浮かべたのが君の足であったと思いたいものだな、{race}。Thermapluggの死によって、Gnomereganを取り戻すという我々の計画は一歩実現へと近づいたのだ。", 0xc7223d52, 0xfb52e324, 0x8bff6fc1, 0xada3365b, 0x5ff1117b, "....." },
  [2930] = { "データ救出", "IronforgeのMaster Mechanic CastpipeにPrismatic Punch Cardを渡して下さい。", "Gnomereganから逃げ出した時、たくさんのデータを置いてきてしまったんだ！ 極めて重要なデータを！\n\nGnomereganの奥深くにあるMatrix Punchograph $N1-D高セキュリティ端末から、prismatic punch cardにデータを取り出す必要があるんだ。その端末にアクセスしなきゃならないけど、そのためにはまず許可が必要で……それを得るにはもっと低いセキュリティの端末――-A、-B、-Cの各モデル――にアクセスしなきゃならない。そしてそれをするには、白から始まるセキュリティのpunch cardsが必要なんだけど……punch cardsは全部都市に置いてきちゃったんだ。\n\n大惨事だよ！ 手伝ってくれるかい？", "prismatic punch cardは持ってる??", "やったな！prismatic punch cardを見つけ、失われたデータを取り戻してくれた！我々が一瞬たりとも欠かすことのできない、極めて重大で、決定的で、計り知れないほど重要なデータをだ！\n\nノームたちへのあなたの功績は長く記憶されるだろう、{name}。", 0xb572ead8, 0x0d6cb3dd, 0x55478e87, 0xa5d0b260, 0x9a4bbb5a, "....." },
  [2931] = { "Castpipeの仕事", "IronforgeのMaster Mechanic Castpipeと話して下さい。", "IronforgeのMaster Mechanic Castpipeが冒険者を求めているよ！ 最高機密かつ最重要のデータ回収任務のために、Gnomereganへ再突入する隊を編成しているんだ。\n\nCastpipeは僕みたいにEnlightened Assembly of Arcanology, Alchemy and Engineering Sciencesの会員じゃないかもしれないけど、それでも賢いノームだからね。彼が重要だと思うなら、僕の計算では、本当に重要である確率は84パーセントだ！\n\nなかなかの確率だろう！", nil, "わしはGnomereganにおけるデータ抽出作戦を計画しておる。そのためにここへ来たんなら、よく聞け!", 0x95ff10c3, 0x3809bbd3, 0x4d68d41f, nil, 0x3d0d0c09, "...m." },
  [2932] = { "不吉な知らせ", "Witherbark Skullsを集めてNimboya's Pikeに載せる。Nimboya's Laden PikeをHinterlandsにあるWitherbark Villagesの一つに立て、StranglethornのNimboyaのところへ戻って下さい。", "WitherbarkのトロールどもはかつてHordeの味方だった。だが奴らはThrallを裏切った……その報いは受けさせねばならん！\n\nさあ、俺のpikeを持って、はるか北のHinterlandsへ行け。Tarren Millの北東にある。Tarren Millは我らの味方、Forsakenが押さえる村だ。\n\nHinterlandsに入ったら、Witherbarkのトロールどもを狩れ。奴らのskullsを集め、奴らの小さな村の一つ、Hiri'wathaかZun'wathaに俺のpikeを突き立てろ。\n\n奴らの卑劣な行いには報いがあると思い知らせてやれ！", "お前はまだ俺の頼んだ仕事を終えていないぞ、{name}。", "お前の行いは耳に届いている。陰惨な行いだが、名誉あるものだ。Witherbarkどもがお前の伝言に耳を傾けることを願おう。", 0xe9a63c1c, 0xc51a95c3, 0xd856795d, 0xd1a502bf, 0x2a9c90c2, "....." },
  [2933] = { "毒の瓶", "Venom BottleをTarren Millにいる薬剤師に渡して下さい。", "これらの瓶には、おぞましい緑色の毒液が入っている。\n\nこの村にある瓶の数からすると、Witherbarksにとってこれは非常に重要なものに違いない。近くのTarren Millの薬師なら、サンプルを欲しがるかもしれない。", "やあ、優しき{class}。今日は長い一日だったが、実験は一つとして成功しなかった……良い知らせを持ってきてくれたことを願うよ。", "あ、それ何だ? 毒みたいだな……蜘蛛系の生き物から採取したものだろう。そんでこれはどこで手に入れた?", 0x11490f01, 0xab4467b2, 0x215c3182, 0xc797364c, 0x24dc19cf, "....." },
  [2934] = { "Undamaged Venom Sac", "Undamaged Venom SacをTarren MillのApothecary Lydonに渡して下さい。", "お前が持ってきた毒液の新鮮なサンプルがどうしても必要だ。それが採れた蜘蛛はHinterlandsに棲んでいるに違いない――undamaged venom sacが見つかるまで狩って、私のところへ持ってこい。トロールの都市Shadra'Alorの近くに多くの蜘蛛がいるはずだ。\n\nぐずぐずするな、{name}。届ける時にvenom sacが新鮮でなければならんのだからな。", "undamaged venom sacは持ってきたかね、{name}? 新鮮な毒で実験したくてたまらないのだよ。試すための小さくてとても可愛い動物たちも、もう取り寄せてあるのだ!", "おおすごい! この毒は実に新鮮だし、非常に致死性が高いに違いない。ありがとうよ!", 0x5787f979, 0xc1297cc7, 0x4adfb552, 0x3d50077f, 0x0b4e96a0, "....." },
  [2935] = { "Master Gadrinとの相談", "Sen'jin VillageのMaster Gadrinと話して下さい。", "broodguardsの毒液は、お前が最初に持ってきた毒液ほど強力ではなかった。別の蜘蛛から採れたものに違いない。\n\nあの毒液の新鮮なサンプルが欲しい。それがどこから来たのかを突き止めるには、Witherbarkをよく知るトロールに相談しなければならん――Sen'jin VillageのMaster Gadrinだ。Durotarへ行ってGadrinと話せ。運がよければ、Witherbarksがどこから毒液を得ているのか知っているだろう。", nil, "ああ、witherbark族の蜘蛛から新鮮な毒を集めたいのかね? まあ、お座り……私が教えなきゃならんことは、好きになれんだろうねえ。", 0xf6fc7c51, 0x0c77979e, 0x4a620828, nil, 0x49a2f284, "...m." },
  [2936] = { "蜘蛛神", "Witherbark族の蜘蛛神の名を調べるためにTablet of Thekaを読み取り、Master Gadrinのところへ戻って下さい。", "Witherbarksは蜘蛛の神を崇めていて、その神から最も強力な毒液を集めている。だから毒液が欲しいなら、奴らの神を呼び出さねばならん！\n\nそのためには神の真の名を知らねばならん。その名は、Tanarisにあるトロールの都市Zul'Farrakの、Theka the Martyrが守る墓に埋められた石板に記されている。\n\nThekaを倒し、その石板を見つけて読み、蜘蛛の神の名を突き止めろ。名がわかったら、俺のところへ戻ってこい。", "蜘蛛の神の名は分かったか?", "ああ、Elortha no Shadra……この名はささやき声でのみ口にせよ。その言葉は霊の領域において大きな重みを持つのだからな。\n\nこの名を羊皮紙に記し、お前のために召喚の呪文を作ってやろう……", 0x182b3641, 0xa80ea123, 0xcebbae4a, 0xf8b345e3, 0x1158639f, "....." },
  [2937] = { "Shadraの召喚", "Shadra'Alorの祭壇でShadraを倒し、毒をTarren MillのApothecary Lydonに渡して下さい。", "この羊皮紙を持って行き、Hinterlandsにあるwitherbark族の領地奥深くにあるShadra'Alorの祭壇で読みなさい。蜘蛛神Shadraを召喚できよう。", "毒は手に入れたか?", "最高だよ、手に入れたなんて!", 0x1fe0036d, 0x8b5c3f22, 0x5866afa8, 0xe57d19f5, 0xbda6f99d, "....." },
  [2938] = { "毒をUndercityへ", "Faranell's ParcelをUndercityのMaster Apothecary Faranellに渡して下さい。", "お前がWitherbarkの蜘蛛の神から集めた毒液は、実に大した発見だ！ たった一滴で、2ダース近くのウサギを殺せたのだからな。確かに、そのウサギの中にはごく幼く、手のひらに収まるほど小さいものもいたから、毒への抵抗力が低かったのは間違いない。だが、この毒が強力であることは否定できん！\n\nこのサンプルを、UndercityのApothecariumにいる私の上司、Apothecary Faranellに送りたい。きっとご自身で試したがるはずだ。", "お前が来ることは知らされていた、{name}。私宛てのparcelを持っているのか?", "ああ、実によい。Lydonが言うには、この包みの毒は彼がこれまで触れた中で最も強力なもので、今はその新たな用途の研究に追われているそうだ。\n\n運が良ければ、用途はいくつも見つかるだろう。\n\n礼を言う、{name}。Royal Apothecary Societyへのお前の功績は疑いようがない。", 0xb56a1970, 0x1d054150, 0xe4abef06, 0x979bec03, 0x29675c90, "....." },
  [2939] = { "知識を求めて", "Rut'theran VillageのDaryn Lightwindと話して下さい。", "Feralasの遺跡はかなり危険ですが、ここで何が起きたのかについて多くを語ってくれます。\n\n数日前に南のがれきの中を探していたとき、ごく普通の杖に見えるものを見つけました。でも、何かそれ以上のものがあるという気がしてならないのです。Angelasと私はここにある本を読みあさっていますが、それについては何一つ見つかりません。\n\nDarnassusに、これが何なのか教えてくれるかもしれない同僚がいます、{name}。彼女のところへ行って、力を貸してもらえないか聞いてきてくれませんか？", nil, "ああ、Troyas Moonbreezeに言われて来たのか?\n\n<ぶつぶつと呟く。>……いつも大事なものを見つけたなんて突拍子もない考えで、私を煩わせて……\n\nいいかい、{name}、はっきり言おう。Troyasはいつも、あの遺跡で何か大事なものを見つけたと思い込んでいるんだ。実際のところ、本当に価値のあるものは、今あそこに棲みついているogresかharpiesが、とうの昔にため込んでしまっただろう。\n\n見て回るのは構わないが、ここに君の役に立つ本があるかどうかは分からないな。", 0x024ac15b, 0x27801142, 0x9fe00bd1, nil, 0x3aed02fb, "...m." },
  [2940] = { "Feralas: A History", "Daryn Lightwindに、彼女の本を借りてもいいか尋ねて下さい。", "この本は、ずいぶん長い間誰にも開かれていないようだ。表紙はかなりすり切れ、ページは黄ばんでいるが、よく調べてみると、これこそTroyasが探しているものかもしれないと気づく。\n\n手に取ったものの、借りる前に一言断っておいた方がよさそうだと思い直す。", nil, "では、Feralas: A Historyを借りたいと?\n\n考えさせてくれ……\n\nこの本を貸してあげよう、{name}。ただし、まず私の頼みを聞いてくれたらだ。", 0xad9c7cd2, 0xcddd8fc5, 0xe6f4dd42, nil, 0x5487bf1c, "...m." },
  [2941] = { "借り主", "手紙をTanarisのCurgle Cranklehopのところへ持って行って下さい。", "私はこれまで多くの分野を研究してきたが、最近夢中になっているのはHinterlandsの浜辺に棲むsnapjawだ。特に見てみたい一匹がいてね。Gammeritaという名の巨大なsnapjawだ。自分で行きたいところだが、研究があってここを離れられない。彼女の写真があれば、それが次善の策だと思う。\n\nこの手紙をTanarisのCurgle Cranklehopに届けてくれ。彼女が私のために、写真を撮れる発明品を作ってくれたのだ。「スナップショット」と呼んでいたと思うが……", "手紙……私に?", "君もDarynのインターンの一人かい? 彼女はとても博識な歴史家だよ、{name}。彼女の指導の下で学べることに感謝するべきだね。\n\nさて、Super Snapper FXを持ってこよう。きっと気に入るよ!", 0xbf91965a, 0x1d265812, 0x87f31ae2, 0x84f49355, 0x65e2b535, "....." },
  [2942] = { "Morrow Stone", "Sparkling StoneとStave of EquinexをFeathermoon StrongholdのTroyas Moonbreezeのところへ持ち帰って下さい。", "遺物がMonolithから取り外された瞬間、Stave of Equinexの力が薄れ始めるのを感じる。", "戻ってきてくれて嬉しいです、{name}。あなたが何を見つけたのか、早く聞きたいのです。", "あなたが出発してから、ずっと文献を読んでいました、{name}。あなたが見つけたこの石はMorrow Stoneと呼ばれるものです。その目的はまだはっきりとは分かりませんが、あのようにEquinex Monolithの中に隠されていたのですから、非常に重要なものであることは間違いありません。\n\n私は研究を続けます。これからもあなたを頼りにできればと思っています、{name}。いろいろと助けてくれてありがとうございました。", 0x213c00cf, 0x61b177ca, 0x34c7ce0d, 0x1fded39e, 0xab29960a, "....." },
  [2943] = { "Troyasのもとへ戻る", "本をFeathermoon StrongholdのTroyas Moonbreezeに届けて下さい。", "はい、どうぞ、{name}。どうか、私の本を大事に扱ってくださいね。\n\nさあ、急いで。Troyasがきっとあなたの帰りを待ちわびていますよ。", "こんにちは、{name}。Darnassusへは行ってきましたか?", "本を持ってきてくれたのか。素晴らしい!", 0xff5baae2, 0xcfcf05ac, 0xb4df8e98, 0x38e98959, 0xab1081ea, "....." },
  [2944] = { "Super Snapper FX", "Super Snapper FXを使ってGammeritaの写真を撮り、Rut'theran VillageのDaryn Lightwindのところへ戻って下さい。", "私の新しい発明品を一番に見せてあげる、{name}。撮りたいものを何でも狙って、ボタンを押すだけでいいの。\n\nHinterlandsの、あなたが言っていたあの生き物は何だったかしら？ Gammerita？ まあ、見つけられるといいわね。あなたが持ち帰るスナップショットを、Darynはきっととても喜ぶわ。\n\nとにかく、これがSuper Snapperよ。楽しんでね！", "ようやく戻ったか、{name}。それにCurgleが私のために作った装置も持ってきてくれたんだな……完璧だ。", "よし! Curgleの発明品は期待どおりの働きをしたな。\n\nあまり浮かれるなよ。だが、君の仕事ぶりには満足していると知っておいてくれ、{name}。\n\nさて、あの本をどこに置いたかな……", 0x84039a5c, 0x80739a43, 0x92f501a3, 0x8dbec39e, 0x39c63785, "....." },
  [2945] = { "Grime-Encrusted Ring", "Grime-Encrusted Ringの汚れを除去する方法を見つけて下さい。", "Dark Iron族ドワーフの死体から指輪らしきものを発見した。どういった指輪であるとは言い難い。埃と硬化した滓がこれを覆い尽くしており、指にはめられなくなっている。滓の下に貴金属のかすかな光沢と宝石の輝きが辛うじて見えるように思える。\n\nこの指輪を使えるようにするなら、硬化した滓を取り除く物を見つけなければならないだろう。", "目の前のノームの装置には「The Sparklematic 5200」と書かれた銘板が付いている。銘板の下の説明書を読むと、この機械の要点は、品物についた汚れをこすり落とすことらしい。機械には硬貨の投入口があり、品物を中に入れたあと銀貨を3枚入れると作業が始まる。\n\n以前見つけたgrime-encrusted ringは、まさにこの機械で試すのにうってつけのようだ!", "Sparklematic 5200の中に指輪を入れ、硬貨投入口に銀貨を入れた。\n\n機械が激しくガタガタと動き始めると、耐え難いほどの耳障りな音がした。機械の中の指輪に何が起きているか、想像するしかできない……。\n\n機械は突然停止し、停止したことをただ「カーン!」と音で知らせた。器が開くと、きちんと赤いリボンでちょうちょ結びをされた小さな箱が現れた。Sparklematic 5200はプレゼントをラッピングする機械でもあったらしい!", 0xf8a3263a, 0xc110cf2f, 0xab7d0f3c, 0x344cc60a, 0x3a2498fd, "....." },
  [2946] = { "何が起こるか見届けて", "小さなプラチナの円盤をTanarisのUldumの門へ持って行き、両者のつながりについて手がかりを探して下さい。", "見つけた小さな円盤を、Uldumの封印された門へ持っていってほしい。我々は……そうしたら何が起きるのか、確かなことは分からない。\n\n危険に聞こえるのは確かだ。それは認める。だが、何も起きないかもしれない。円盤を何かに使う必要があるのかもしれない。円盤を持っていれば扉が開くのかもしれない。何でも試す気持ちで、何が起きても大丈夫なように備えておいてくれ。\n\n何が起きるか分かったら、Ironforgeへ戻ってきてくれ。君が済ませてくれたら、分析することが山ほどあるはずだ！", "見覚えのある台座が熱い砂から突き出している。ここにあることには何か意味があるのかもしれない……", "台座に触れると、背負い袋の中でUldamanの小さな円盤が唸りを上げて光り出す。覚えのあるうずくような感覚が両手を包み、Uldumの門の前に、もう一体のStone Watcherの姿が浮かび上がる。\n\n「ごきげんよう。私は入口の守護者です。アクセスに使用された円盤には、正しい入口用の円盤であるPlates of Uldumが欠けています。これらの石板を円盤の構造に組み込み、アクセス手順を再度実行してください。ありがとうございました。」", 0x7446c0c8, 0xec67bdb9, 0x5f1b449a, 0xd9076687, 0x2a4c8eea, "....." },
  [2947] = { "指輪の返却", "指輪を自分の物として持っていることもできますし、指輪の内側に刻印されている所有者の関係者を捜すこともできます。", "Sparklematic 5200 の作った箱を開けると、期待していたもの……輝く指輪が現れた! 指輪を身につけると、魔法の力が体中を駆け巡るのが感じられた。\n\n指輪の内側には小さいけれども判別可能な Ironforge の印が刻印されていた。その隣には、'TdK'とイニシャルが三文字彫られていた。これは前の所有者か、指輪の製作者のイニシャルを意味しているのだろう。指輪を自分のものにするか……この人物に返すか。決断、決断……。", "おいおい、落ち着けよ相棒。俺はとっても重要な実業家なんだぞ! 家賃を届ける使いがちょっと遅れてるだけに決まって……待てよ……あんた、大家じゃないな。\n\nそりゃそうだよな、俺としたことが! あんたはIronforgeで一番の宝石職人、呪われた品なんか絶対に作らない職人を探して来たんだろ! そうだとも!\n\nえーと……何の用だい?", "指輪だって? どれ……ああ、私が作った指輪だよ。あれまあ。\n\nGnomeregan が破滅する前、あそこに小さな店を持っていたんだよ。多分、丘へ逃げる前に置いてきた奴だ。このシンプルなデザインは、似たようなのをいくつか作ったね。逃げなかった誰かが持ってたものだろうねえ。\n\nDark Iron 族ドワーフが持ってたって? そうか、そいつはまた謎に次ぐ謎を投げかけるもんだなあ。関係者は知りたがるだろうね。私じゃ力になれんな。\n\nじゃ、指輪の話に戻ろう……。", 0x9b2297a2, 0x8cbc1bad, 0x463d3a78, 0xf03132b6, 0x9157f220, "....." },
  [2948] = { "ノームの改良", "IronforgeのTalvash del Kisselに、Brilliant Gold Ring・Silver Bar 1本・Moss Agate 1つ・銀貨30枚を渡して下さい。", "いいかい{name}、この指輪は君のだ……でも、もっといいのを作ってあげられるんだ! このデザインは、さっき言ったようにとても単純だ。私も今は腕を上げたから、たった銀貨30枚の料金でもっと洒落たのにしてあげよう! えっと、本当は銀貨30枚と他にもちょっと……。\n\n今ちょうどお金に困っててね。金属の在庫が無くなってしまったんだよ。Silver Bar 1本とMoss Agateひとつを持ってきてくれたら、銀と瑪瑙の格子模様を追加してもうちょっと指輪が派手になるぞ!\n\n任せろ!", "必要な材料は持ってきたかい? ツキに見放されてなきゃ、あんたに頼んだりしないんだけどな……", "ああ、まさしく欲しかったものだ! いつかこの赤字から抜け出せたら、君やAzeroth中のみんなに最高のアクセサリーを作るつもりだ! それまでは、材料について物わかりのいい人には感謝だな。通常はこの品質の指輪で請求するのは、君に請求した金額の10倍なんだ……。\n\n指輪といえば、これが君の新しいやつだ!", 0xaf868c64, 0x1a07e711, 0x8547b93f, 0x965ed2bb, 0xd8803d0d, "....." },
  [2949] = { "指輪の返還", "指輪をそのまま持っていることもできますが、指輪の裏側に彫り込まれた名前に関係のある人物を捜すこともできます。", "Sparklematic 5200 に渡された箱を開けると、輝く指輪が現れた! 指輪を身につけると、体に魔法の力がみなぎるのが感じられた。\n\n指輪の裏側には、小さいがしかしはっきりと識別できる Orgrimmar の標章が刻まれていた。その隣には文字が刻まれていたが、研磨後もなおはっきりと読み取れるのは、最初の3文字 'NOG' だけだった。\n\n前の持ち主か指輪制作者か、どちらかの頭文字を意味しているのかもしれない。指輪をこのまま持っているか……あるいは 'NOG' を見つけるか。決断、決断……。", "俺たちだけで、あの汚らしいちびのノームどもを出し抜く方法くらい見つけられると思うだろ。そもそもあの装置だって、奴らが俺たちから盗んだものだと賭けてもいいね! ふん、あの脂ぎった、薄汚い……えー、はい? 何か用かい?", "Gnomeregan で見つけた指輪? 見せてくれ……こいつはオレのじゃない。でも、面白いね。\n\nGnomeregan の件は……素敵な馬鹿どもの身にしか起こらんよ。ずっと前からあいつらは笑い種さ。今じゃほとんど一夜にしてオレたちよりいい装備を作ってるのかねえ?\n\nDark Iron 族のドワーフがこの指輪を持っていたのか? そいつはもっと面白い! そうだ、多分ノームは Dark Iron 族のドワーフからすんごいゴーレムの設計書を盗んで、改変したんだ。確実に Dark Iron 族は大規模な仕返しをしようとするだろう。こいつは確かに調査のしがいがあるぞ。\n\nいいかい、この指輪についてだが……", 0x9b2297a2, 0x8cbc1bad, 0xb84d59f3, 0xe22ff9bc, 0x4e5317a9, "....." },
  [2950] = { "Noggの指輪リフォーム", "OrgrimmarのNoggに、Brilliant Gold Ring・Silver Bar・Moss Agate・銀貨30枚を渡して下さい。", "いや、いや、いや。この指輪はオレのもんだなんて、いきなり言ってるんじゃないよ。普通はこんなことしないんだけど、Dark Iron族についての情報はすごく役に立った。この指輪は君のために改良するつもりだよ。この質素で小さな指輪を作った誰かが今までに作れたものより、ずっと良いものにね。恐らくノームだろうね……\n\nSilver BarとMoss Agateと骨折りの代価として銀貨30枚を持ってきてくれたら、指輪の秘めた魔力を高める銀と瑪瑙の格子模様を付け加えてあげるよ。興味ある?", "必要な材料は持ってきたかい? 頼んだものが全部そろわないと、このデザインは改良できないんだ。", "これが、前より良くなった指輪だよ。Dark Iron族ドワーフに関する情報に改めて感謝するよ。ゴブリン的な閃きをノームたちがどうやって突然思いついたのか説明する、筋の通った糸口のように見えるんだ。", 0xe9be8e28, 0xc0fbbadd, 0x13b26acd, 0x95624713, 0x48a5420b, "....." },
  [2951] = { "Sparklematic 5200!", "Sparklematic 5200 に Grime-Encrusted Item を投入し、機械を作動させるには銀貨3枚を必ず入れて下さい。", "この奇妙な機械は、部屋の外の狂気に対して持ち堪えているノームの中でもひときわ目立っている。装置につけられている小さな飾り板には 'The Sparklematic 5200' とある。さらに説明文が続いている。\n\n「汚れとカスがあなたの光り物を台無しにしている? Sparklematic 5200 が素敵な輝きを取り戻します! あなたが綺麗にしたい品物を入れて、銀貨3枚を硬貨投入口に入れて下さい。Sparklematic 5200 の作動が終わるまでしばらく待って、ほら出来上がり! 大切なものは綺麗にぴかぴかになって出てきます!」", "どうやらこの装置を動かすには、きれいにするための汚れのこびりついた品と、銀貨3枚が必要なようだ。その両方がそろっていれば、Sparklematic 5200は動くはずだ……", "汚れに覆われた物を入れ、Sparklematic 5200 に銀貨を3枚入れた。機械は得体の知れない物から汚れを取り除くべく、ほとんど怒り狂ったかのように揺れた。機械の中心からは大きく騒々しい撹拌の音が発せられている。左右に揺れると、金属のフレームの鼓動はぎいぎいと軋み、唸りを上げた……。", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [2952] = { "Sparklematic 5200!", nil, nil, nil, "動き始めるやいなや、Sparklematic 5200 は不意に停止した。簡素な「カーン」という音が聞こえ、機械の口が回転しながら開いた。Sparklematic 5200 の中には小さなリボンで包装された小さな箱が入っていた。汚れを除去した後、物体を包装するようだ。たとえ機械が動作しなくとも、少なくとも品物は可愛らしい箱に収められている。\n\nとにかく、品物が綺麗になっているかどうかを調べる方法はただひとつだ……。", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [2954] = { "石の番人", "Stone Watcher of Norgannonの目的を知り、Tanaris砂漠のUldum Pedestalと話をして下さい。", "「ごきげんよう――我は入口の守護者なり。汝のディスク一式にPlates of Uldumがすでに組み込まれていない限り、Uldumの施設への立ち入りは許可しない。」\n\nStone Watcher of Norgannonが姿を現したのは、プラチナのディスクを持たせてあなたをTanarisの砂漠へ送り出した際に期待されていた反応に違いない。指示されたとおり、先へ進む前に、Stone Watcherにまつわる話を突き止める必要がある。", "先へ進む前に、石の番人の目的を知らねばならない……", "石の監視者の声が、力と威厳をもって響き渡る。\n\n「汝の円盤は、台座に触れた後に返される。Plates of Uldumを手に入れ、それを手持ちの円盤一式に組み込んだとき、汝はこの施設へ入ることが許される。」", 0xb5f90fe3, 0xdfcdd726, 0x98d8abcb, 0xa2bcd4ef, 0xa04cfcc1, "....." },
  [2962] = { "唯一の治療法はもっと緑色発光体を手に入れること", "Gnomereganへ行き、High Potency Radioactive Falloutを持ち帰る。注意すること。この放射性降下物は不安定で、かなり早く崩壊してしまう。\n\n任務が終わったら、OzzieはあなたのHeavy Leaden Collection Phialも必要としています。", "君のサンプルは量が足りなかっただけじゃなく、不純物も混じっていた。\n\n必要なのは、もっと多くの緑の輝きだ。troggsは、僕らの必要を満たすほど十分には被曝していないのは明らかだ。Gnomereganへ行って、蛇口から直接出てくるようなradioactive falloutを持ち帰ってもらわなきゃならない。僕が言っているのは、放射能を浴びたslimes、lurkers、horrorsのことだ。気をつけてくれ、この種の降下物を封じ込めるのは難しい。ちゃんとしたサンプルが採れるまで、phialで何度か試す必要があるかもしれない。", "ふむ、光ってはいないな。いい兆候だ。", "<Ozzieはあなたを観察する。> 大したもんだ、手足がまだ全部そろってるじゃないか。さあ、こいつに何ができるか確かめる時だ！", 0xc891dea0, 0x4e7ea0ad, 0x6fc2256f, 0x66e8e057, 0x6eeec372, "....." },
  [2963] = { "Uldum の前兆", "Ironforge 内の Hall of Explorers にいる Historian Karnik と話して下さい。", "また会ったな、{name}! Uldaman でのお主の発見は Explorers' League を興奮で騒然とさせたぞ。Explorers' League はお主が見つけたミニチュアプラチナディスクの秘密の解明に取り掛かっとる。偶然通りかかってくれたお陰で、面白いものを見つけた可能性があると連絡できるわい!\n\nTanaris 砂漠の Valley of the Watchers の本当の起源に関する重要な手掛かりをHistorian Karnik が突き止めたんだ。一刻も早くお主と話したいと思っとるだろうな!", nil, "お主が探索への関心を失っていなくて嬉しいぞ、{name}! その闘志と天性の才能があれば、わしらが想像もしたことがない秘密を解き明かすことが可能になるだろう!\n\nUldaman にある Discs of Norgannon は膨大な情報の宝庫。言うなれば、お主はそこに蓄えられた情報の最上層にしかアクセスを許されなかったのだ。創造主たちは Azeroth 中に他にも情報の宝庫を設置したと噂されている。それでわしらは Uldum へ赴くのだ……。", 0xb4588354, 0x552c0a0b, 0x0dfef97f, nil, 0xbb6292ae, "...m." },
  [2964] = { "これからの任務", "IronforgeのHigh Explorer Magellasと話して下さい。", "さて{name}……ここで一時的に行き詰まってしまったようだ。何が必要かは分かっている。Plates of Uldumだ。だが、それがどこにあるのか見当もつかない。しっかりした攻略の計画を立てるには、かなり調査をする必要がある。どこから探し始めるか、いくつか考えはある。近いうちに、君にそれを取り戻しに行ってもらうことになると大いに期待しているよ。\n\nHigh Explorerにこのことを知らせる必要がある、{name}。きっと彼も、またしてもLeagueに力を貸してくれた君に、じきじきに礼を言いたいはずだ。", nil, "では全員の意見が一致したな。最善の策は、石板が隠されていそうな場所を絞り込めるまで、ひとまずこれを保留にすることだ。ここまで来られたのは君のおかげだ、{name}。我々皆のためにUldumを開くべく、再び現地へ向かうのは君であってほしいと願っているよ!\n\nそれまでの間、この謝礼を受け取ってくれ。我々を手伝う中でかかった費用を賄えるはずだし、少しおまけも付けておいた。近いうちにまた顔を出してくれよ……Uldumが呼んでいる!", 0xa21b81b7, 0x886ee345, 0xf6da6a06, nil, 0xa20f123f, "...m." },
  [2965] = { "Uldumの前兆", "Thunder BluffのElder RiseにいるNara Wildmaneと話して下さい。", "おお、{name}。思いがけずまた私のところへ来たな。Uldaman発掘現場での君の発見は、我々賢者のあいだに多くの議論を巻き起こした。私はちょうどドルイドのうちの一人Nara Wildmaneと議論していてね、我々が進むべき次の段階に関しては、彼女の経験がかなり重要になるのではないかと分かってきた。\n\nTanaris砂漠にあるValley of the Watchersへの旅のことについて、彼女と話をしてほしい。彼女はElder Riseで君を待っている。", nil, "Tanaris砂漠の奥深くに、Valley of the Watchersと呼ばれる場所があります。あなたが見つけたディスク……翻訳された象形文字は、Uldumという場所について述べていました。ほとんどの人は、その場所を神話のものだと思っています。\n\nでもそれは間違いです。Uldumは存在しています。私はそこに行ったことがあるのです。そう……いずれにせよ外側ですが。\n\n最も大事な点はここです、{name}。私たちはディスクとUldumの間に関連があると考えています。そこで、あなたにUldumへ向かってもらいたいのです。", 0xb4588354, 0xbe3df8e8, 0x29622ce1, nil, 0xfe5763d3, "...m." },
  [2966] = { "何が起こるか見てみる", "miniature platinum discsをTanarisにあるUldumの門まで持って行き、それらの関連性について手がかりを探して下さい。", "Sage Truthseekerと私からお願いしたいことがあります。このディスクをUldumの封印された門まで持って行ってほしいのです。\n\n私たち……私たちには、その時何が起こるか確信が持てません。\n\n危険かもしれない……ええ、それは私たちも認めます。しかし、何も起こらないかもしれません。そのディスクは、何かに使う必要がありそうです。恐らく、あなたがディスクを所持している時、扉は開かれるでしょう。何でも試してみる気持ちで臨み、そして起こりうる全ての事態に備えて下さい。\n\n出来る限りのことを学び、そして私のところへ戻ってきて下さい。私たちには、議論すべきことがたくさんあります。", "見覚えのある台座が熱い砂から突き出している。ここにあることには何か意味があるのかもしれない……", "あなたが台に触れると、Uldamanの小さなディスクは微かに振動し、鞄の中で輝いた。覚えのある感触がびりびりと手に押し寄せ、別のStone Watcherの姿がUldumの門前に浮かび上がった。\n\n「ご挨拶申し上げます。私は門番です。お使いになられたディスクは、正しいエントリーディスクPlates of Uldumがありません。Plates of Uldumを合わせてディスクを構成し、利用手続きを続行して下さい。以上です。」", 0x7446c0c8, 0xec67bdb9, 0xdf0e40da, 0xd9076687, 0x2a4c8eea, "....." },
  [2967] = { "Thunder Bluffへの帰還", "Thunder BluffのNara Wildmaneと話して下さい。", "再び台座にアクセスすると、プラチナのディスクが突然また背負い袋の中に現れる。\n\nstone watcherについての知識を得てディスクも手元に戻った今、Thunder Bluffへ戻り、Nara Wildmaneに発見を報告する時が来た。", "おかえり、{name}。円盤をうまく役立てられたか、それとも無駄骨だったか?", "円盤がいくつか足りなかったのか？興味深いことに、Norgannonの円盤は完全な一式の一部にすぎないようだ。言うなれば、鍵束についた鍵のようなものだな。\n\nPlates of Uldumを見つけられれば、Uldumの施設そのものに入ることも実際にできるかもしれん。その見込みに心を躍らせるべきか、恐れるべきか、私には分からんよ。\n\n我々を皆滅ぼしかねない、大地が守り続けるあの秘密が、秘密のままであり続けるようにするためなら、すべてを賭ける必要があるかもしれん。", 0xb5d4ecc4, 0xc2d0c05d, 0x81744d92, 0x2e60b4a9, 0xa1778115, "....." },
  [2968] = { "将来の課題", "Thunder BluffのSage Truthseekerと話してください。", "さて{name}……私たちは不運な行き詰まり状態にあるようです。Plates of Uldumが必要なのだと分かっていながら、それがどこにあるのか知らないのです。それについて調べ、そしてしっかりした着手計画を考えるつもりです。どこから探し始めるかについては、私に少し考えがありますから、すぐにでも取りかかりたいと思っています。真実を発見するための取り組みに、また加わってくれるようお願いします。\n\nSage Truthseekerにこのことを知らせる必要があります、{name}。恐らく、あなたが再び呼びかけに耳を傾けてくれたことに、彼も直接感謝の気持ちを伝えたいことでしょう。", nil, "我々は皆合意に達している。最善策は、このプレートが隠されていそうな場所が絞り込めるまで待つことだ。{name}、そなたのおかげで我々はここまで来られた。そなたが再び、Uldumの秘密に立ち向かってくれることを期待している。\n\nひとまず、この謝礼を受け取ってはくれないか。我々を手助けする際の必要経費をすべて補えるだろう。それと、ほんの気持ちだ。必ずすぐ、再度連絡してほしい……Uldumは我々皆を手招きしているのだ、若者よ。", 0xa21b81b7, 0x657f6ac8, 0xa1458715, nil, 0xd483c647, "...m." },
  [2969] = { "すべての生き物に自由を", "Bamboo Cage Keyを使って、Grimtotemの野営地の囲いからSprite Dartersを解放する。少なくとも$N1匹のSprite DartersとKindal Moonweaverが生き残らなければならない。\n\nKindalが退却すべきだと判断するまでの時間は$N2分。それを過ぎるとクエストは失敗になる。", "あの汚らわしいGrimtotem氏族が、faerie dragonsを捕らえているの、{name}。Jer'kaiにも私にも、彼らがそれをどうするつもりなのかは分からないけれど、何か良からぬことを企んでいるのは明らかよ。\n\n私たちには、野営地に斬り込んで捕らわれたdragonsを解き放つほどの力はないわ。でも、あなたの助けがあれば……\n\nその気があって、強い仲間がいるなら、このkeyで檻から生き物たちを解き放って、無事に逃げられるよう見届けてちょうだい。私はずっとあなたのそばにいるわ。Jer'kaiはここに残るの。", "Grimtotem氏族にこの美しい生き物たちを滅ぼさせるわけにはいきません。彼らを捕らわれの身から解き放たなければ!", "Eluneに感謝を、{name}! あなたは私たちにとって、そしてあなたが救ったdarterたちにとって、大いなる恵みです。Jer'kaiと私だけでは、とてもdragonたちを助けることはできなかったでしょう。Grimtotemのたくらみにあなたが介入してくれたことは、決して忘れられません。\n\nさあ、Jer'kaiと話してください……私は報復の準備をしなければなりません。faerie dragonが解放されたからといって、そのまま自由でいられるとは限りません。Jer'kaiと私は、これから攻勢に出ます。", 0x60dfaf24, 0x29b71855, 0xcb35a513, 0xafa50ad5, 0x27463b33, "....." },
  [2970] = { "正義の執行", "Grimtotem Naturalistsを$N1体、Grimtotem Raidersを$N2体、Grimtotem Shamansを$N3体倒してから、FeralasのJer'kai Moonweaverのところへ戻って下さい。", "彼女がもう話したとおり、Kindalと俺はこれからGrimtotemに戦いを仕掛ける。二人でも、大した危険を冒さずにトーレンを何人か仕留められるはずだ。だが、君にその気と力があるなら、ぜひ手を貸してほしい。\n\n下の野営地はもう見ただろうが、東にもまだある。君自身の戦術で、トーレンにできるだけ多くの打撃を与えてくれ。奴らがKindalの矢と君の武器の痛みを味わったら、皆でここに戻ってこよう。", "Kindalには準備の時間が必要だが、我々が仕留めた数はもう何十にもなる。Grimtotem氏族はこの一帯に我々がいることを十分に承知していて、毒蛇のように我々を探し回っている。\n\n奴らは我々の首を胴から切り離すためなら、どんなことでもするだろう。油断するなよ……君も手を出した以上、奴らは君も狙ってくるはずだ。", "Kindalの言ったとおりでした、{name}。あなたには確かにこういうことの才能があります。あなたは私たち二人よりも経験豊かな冒険者です。そのことに感謝します。\n\nGrimtotem氏族は、ほとんどのトーレンよりもはるかに敵対的です……同族も彼らの行いを快く思っていないのではないでしょうか。そうだとしても驚きません。おそらくご存じのとおり、Azerothの多くの種族には、あまり友好的でない同類がいるものです。\n\nですが、その話はまたの機会にしましょう。", 0xe759ef95, 0x5bc3d94a, 0x657cbf89, 0x01f4f7af, 0xf5841753, "....." },
  [2972] = { "正義の執行", "Jer'kai's Signet RingをDarnassusのHigh Priestess Tyrande Whisperwindのところへ持って行って下さい。", "この荒野では、Kindalと俺には君の助けに報いる手立てが乏しい。だが、報われないと思ってほしくはない。俺のsignet ringを受け取ってくれ。もしTeldrassilの大枝を訪れることがあれば、Darnassusの中心にあるTemple of the Moonへ行ってくれ。そこに我らがHigh Priestess Tyrande Whisperwindがおられる。この指輪を見れば、我々が無事であることが彼女に伝わり、君の話の裏付けにもなる。\n\n二人とも君に感謝している、{name}。", "我が子よ、こんにちは。この神殿に、より力ある冒険者の方を迎えられるのは私たちの喜びです。お時間があれば、若い冒険者たちに話を一つか二つ聞かせてあげてくれませんか？ 多くの者があなたの知恵から学ぶことがあるはずです。\n\nごめんなさい、なんと失礼なことを。あなたは私たちの助けを求めて神殿へいらしたのに、私はあなたに頼みごとをしてしまいました。どうか、お許しください。光の僕である私たちがあなたのために何ができるか、お聞かせください。", "驚くべき話ですね、{name}。あなたがdragonkindを助けてくれただけでなく、私たちの同胞である女司祭まで助けてくれたことを嬉しく思います。Jer'kaiがあなたを私のもとへ送ったのは正しかったのです。彼女の指輪は必ず本人に返しましょう。近いうちにFeralas方面へ向かう斥候たちがいます。任務の間に調べることが一つ増えるだけです。\n\nあらためてありがとう。ここにいる間は、どうぞくつろいでください。", 0xe759ef95, 0x80a8a598, 0x107eafc3, 0x8b166337, 0x9a5eb049, "....." },
  [2973] = { "新しい外套の輝き", "Camp MojacheのKrueg SkullsplitterにIridescent Sprite Darter Wing 10枚を渡して下さい。", "よく来た、{class}。俺は仲間たちとFeralasまで旅してきた。Orgrimmarの主人たちのための任務でな。\n\n俺の伴侶Korrinは新しい服が大好きでな、faerie dragonsの薄く透ける翼で飾った新しいマントを作ってやりたいんだ。手を貸してくれないか？ 俺が欲しい見事な翼を持つSprite dartersは、Camp Mojacheの西にいる。", "sprite dartersは怒らせると危険な生き物だ。相手にするときは気をつけろ、{class}。それに、この辺りにいるナイトエルフにはもっと気をつけろ。あの厄介な馬鹿どもも森に潜んでいることが多いからな。\n\nwingsが十分に集まったら知らせてくれ。たっぷり報酬をはずんでやる!", "素晴らしい、{class}！これで十分です。Korrinのマントを作るには足りますし、もっと作れるかもしれません！ありがとう。\n\n旅はあまり危険ではありませんでしたか？Feralasの一帯は容赦のないことで知られていますが、あなたは十分にやり遂げたようですね。\n\n改めて感謝します、{class}。", 0x2bae8b1f, 0x8f85dbac, 0xf48da494, 0xeb9d3196, 0x75713903, "....." },
  [2974] = { "恐ろしい発見", "Camp MojacheのKrueg SkullsplitterにGrimtotem Horn 20個を渡して下さい。", "なんだと！？ この辺りでトーレンに出くわしたって？ 冗談だろう！ どんな見た目だった！？\n\nGrimtotemの氏族だ！ 奴らに出くわしたのか？ 俺たちの主人の一人、Belgromが奴らに関心を持っていてな……懸賞金までかけているんだ。\n\n戻るんだ、{class}。戻って奴らのhornsを持ってこい……できるなら山ほどな。Grimtotemは侮ったり甘く見たりしていい相手じゃない。戻って奴らを斬り伏せろ。Feralasの川を奴らの穢れた血で赤く染めてやれ。", "私の言葉を真剣に受け止めろ、{class}。Grimtotem氏族は邪悪だ。奴らの居場所を突き止めたのなら、戻って奴らの氏族に最初の一撃を加えるのは君の役目だ……奴らが我々の土地に入り込み、我々の村を焼き払ったり、我々の土地を略奪したりする前にな。", "いい角だな、{class}。よくやったぞ。お前からもらったこの角を持って、すぐにでもOrgrimmarへ戻りBelgromに伝えておいてやろう。もう二度も手伝ってくれて、感激している。今後、お前を支えられると思う! 幸運を祈る。", 0x19acaa18, 0x3bb8eb7f, 0xe57e61d4, 0x902d12ef, 0x8d25b8ba, "....." },
  [2975] = { "FeralasのOgres", "Camp MojacheのRok Orhanは、Gordunni Ogre・Gordunni Ogre-Magiを10人、Gordunni Bruteを5人殺すよう求めています。", "ここ一帯でのGordunni族の影響は見過ごせなくなってきているわ。周りを見て、{name}。まさに奴らという存在は、この地に傷跡を残したのよ。奴らがさらにFeralasへ勢力を拡大する前に、私たちは押し戻さなくてはならない。\n\nそこの川に沿って北へ行くと、前哨基地があるわ。奴らの数を減らしてちょうだい、{name}。ここにはogreなんて必要ないってことを、見せつけてやらなきゃならない。", "急げ、{name}。それとも、私の頼んだ仕事は難しすぎるか?", "素晴らしいわ、{name}。時が経てば、この地も癒えていくでしょう。あきらめてはいけない。", 0xf4ef25e1, 0x2da654a4, 0x7826014c, 0x0c264015, 0x3680d0c7, "....." },
  [2976] = { "恐ろしい発見", "Crate of Grimtotem HornsをOrgrimmarのBelgrom Rockmaulのところへ運んで下さい。", "なんだって！？\n\nああ、確かに懸賞金のことを言ったんだったな？ まあ、口を滑らせるとこうなるって教訓だな。\n\n働いたのはお前だ。だから一番大きな報酬を受け取るのがお前なのは当然だろう。hornsを持っていけ、crateに詰めさせておく。Valley of HonorにいるBelgrom Rockmaulを訪ねろ。お前が見たことを知りたがるだろうし、働きに報いてくれるはずだ。\n\n達者でな、{class}。お前がしてくれたすべてのことに、改めて礼を言う。", "急いでくれ、{class}。今日はやらねばならぬことが山ほどある。", "Grimtotemだと！？これは興味深い。Feralasで狩りをしている最中に出くわしたというのか？本当か？\n\n私の同輩たちもこの知らせを聞きたがるだろう、{class}。もっと詳しく話してくれ、その間に金を数えておく。\n\nそれと、行く前に言っておく。今日伝えてくれた情報に感謝する。", 0x19acaa18, 0x0b354058, 0xfd2f5a60, 0x6657fe16, 0x079d9f20, "....." },
  [2977] = { "Ironforgeへ戻る", "IronforgeのHistorian Karnikと話して下さい。", "再び台座に触れると、platinumの円盤が突然、またリュックの中に現れる。\n\nstone watcherの知識を得て、円盤も手元に戻った。Ironforgeへ戻り、Explorers' Leagueにこの発見を知らせる時が来た。", "おかえり、{name}。円盤をうまく役立てられたか、それとも無駄足に終わったか?", "円盤がいくつか足りなかったって？ 面白いことに、Norgannonの円盤は完全な一式の一部にすぎないようなんだ。言うなれば、キーリングに付いた鍵のようなものだね。\n\nPlates of Uldumを見つけられれば、Uldumの施設そのものに実際に入れるかもしれない！ 大きなシャベルを持ってこなくても、創造主が働いていた場所を実際に探検できるなんて、想像してごらんよ！\n\nシャベルが悪いってわけじゃないけどね……穴掘りだって……", 0x144eacea, 0xb620dcc9, 0x8d9f3fda, 0x32dd35e3, 0xdf62418e, "....." },
  [2978] = { "Gordunni Scroll", "Gordunni ScrollをCamp MojacheのRok Orhanに渡して下さい。", "汚れた巻物を拾い上げると、集会か式典のようなものが描かれているのに気付いた。Rok Orhanはこの巻物と、Gordunni族にとって意味を持つ可能性のあることに興味を示すだろう。", "これは何だ?", "この巻物は……Gordunni Outpostで見つけたのですか?", 0x554179ae, 0xf2ae9223, 0x43ca625e, 0x1eb006e5, 0xb8e81d0b, "....." },
  [2979] = { "暗黒の儀式", "Camp MojacheのRok OrhanはGordunni Orbを見つけるよう求めています。", "これは何かの闇の儀式の計画書のようだな、{name}。私に読み取れる範囲では、この儀式はGordunniのメイジロードたちが執り行っているようだ。\n\nそのメイジロードの一人を見つけ出し、そいつからorbを手に入れてこい。\n\nメイジのorbには大きな力が宿っている。この儀式について、そしてGordunniが操る魔法について、もっと知る助けになるだろう。", "Gordunniがなぜここにいるのか、もっと突き止めねばならない、{name}。", "この宝珠はGordunni族に関する知識を明かしてくれるでしょう……そして奴らの破滅を計画する際に用いるつもりです、{name}。", 0x060947fa, 0x932d7c0e, 0xd39fd8ff, 0xa62d29eb, 0x400573ef, "....." },
  [2980] = { "FeralasのOgres", "Camp MojacheのRok Orhanは、Gordunni Shaman・Gordunni Warlockを10人、Gordunni Maulerを5人殺すよう求めています。", "真の戦士であることを証明してくれたから、この先の任務を続ける勇気があなたにあると信じてる。\n\nここの南西にあるHigh Wildernessへ行ってちょうだい。かつてナイトエルフのものだった土地にある、破壊され棄てられた建物のところに奴らがいるわ。遺跡を探して、枯れ木と冒涜された土地が見えたら、Gordunniを見つけられるはず。奴らを押し戻して。\n\n{name}、あのogreたちは、前にあなたが立ち向かったのよりずっと強い。注意して。", "遺跡は見つかったか、{name}?", "己が信頼に値する頼もしい協力者だとあなたは証明したのよ、{name}。", 0xf4ef25e1, 0x74a8f3bf, 0x8518f41b, 0x8268bddc, 0x5265cbe1, "....." },
  [2981] = { "Feralasの脅威", "Camp MojacheのRok Orhanと話すようBelgrom Rockmaulは求めています。", "熟練の{class}が己を高めるのに、Feralasは理想的な場所だ。Gordunniというogre部族の支配的軍隊があり、その数は増えている。奴らが我々のFeralas駐留を脅かす前に、止めなくてはならない。\n\n私の知っているRok Orhanという名の戦士が、FeralasのCamp Mojacheに住んでいる。彼女のところへ行け。着いたら、彼女が詳しい状況を教えてくれるだろう。", nil, "それで、Belgromがあなたを寄越したのね。ちょうどいい時にきてくれたわ、{race}。\n\n状況の説明をさせてちょうだい。挑戦するかどうかは決めるのはそれからでいいわ……。でもBelgromが寄越したのなら、あなたの勇気は疑うべくも無いはずね。", 0xd950ff93, 0x52a53a53, 0xda33d9df, nil, 0x4b012670, "...m.", nil, nil, 0x52a7f7e7, nil, nil },
  [2982] = { "High Wilderness", "Angelas Moonbreezeは、Gordunni Warlocksを$N1体、Gordunni Shamanを$N2体、Gordunni Brutesを$N3体倒してほしいと言っています。", "危険ではありますが、Troyasと私はFeralasの森を覆う遺跡を調査してきました。\n\nでも最近、TroyasはひとりでHigh Wildernessへ出かけていて、私は彼のことが本当に心配なのです。Gordunni Ogresがあの一帯を乗っ取っていて、縄張りに入る者には容赦しません。\n\n南東の遺跡へ行って、ogresを何体か片づけてもらえないでしょうか。私のTroyasにとって少しでも安全にしてくだされば、とてもありがたく思います。", "Gordunniの周りでは用心しろ、{name}。奴らの魔法は、奴らが立っている土地そのものを荒廃させているようだ。", "これをやってくれて、本当に感謝しています。\n\nさて、どうか、このことはTroyasには一言も言わないでくださいね……", 0x94041dc4, 0x8a52c7e6, 0xb1f60eb1, 0xdcbfe250, 0x198dd9f4, "....." },
  [2983] = { "火の呼び声", "BarrensでKranal Fissを見つけて下さい。", "前回試練を受けてからしばらく経つな、{name}。これまで修行に辛抱強く取り組んできたが、そろそろより大きな力について学ぶ時だ……真の力を学ぶ時だ。代価を払う覚悟があるなら、火の元素はお前のものだ。\n\nBarrensのKranal Fissを探せ。Crossroadsの北にある小さな住まいに住んでいる。だが気をつけろ、忌々しいナイトエルフの土地まで来てしまったら、行き過ぎだ。", nil, "ふむ、Swartがお前を私のところへ寄越したのか？\n\nそうか、Swartはいつでも信頼できる男だった。ならばお前は次のsapta――火のsaptaを受ける用意ができているということだな。\n\nその目にもう見えているぞ、燃えるような渇望がな。お前は力を味わい、さらなる力を求める用意ができている。焦るな、{name}。大地が教えたことを忘れるな。力と破壊は容易く手に入るが、いつ手を止めるべきかを知らねばならん。", 0x53f3b76b, 0xb1158d84, 0x0c7a07c5, nil, 0xbe75ed09, "...m." },
  [2984] = { "火の呼び声", "BarrensでKranal Fissを見つけて下さい。", "あなたが最後に試されてから、長い時が経ちました、{name}。あなたはこれまでの修行で辛抱強さを示してきましたが、さらに学ぶ時が来たのです。破壊……そして混沌について学ぶ時が来ました。火のエレメンタルはあなたのものです。その代償を払う覚悟があるなら、理解できるでしょう。\n\nBarrensのKranal Fissを探しなさい。Crossroadsの北にある小さな住まいに住んでいます。ですが気をつけて。ナイトエルフの土地まで来てしまったら、行き過ぎです。", nil, "ふむ、Narmがお前を寄越したのだな?\n\nならばよい。Narmはいつでも信頼できる男だ。つまりお前は、次のsapta――火のsaptaを受ける用意ができているということだ。\n\nお前の目にはもう見える。燃えるもの、渇望だ。お前は力を味わい、今やもっと欲している。焦るな、{name}。大地が教えてくれたことを忘れるな。力と破壊は容易く手に入るが、いつ手を止めるべきかも知らねばならん。", 0x53f3b76b, 0xb1158d84, 0x0f02e651, nil, 0xd20cd47c, "...m." },
  [2985] = { "水の呼び声", "BarrensのIslen Waterseerを見つけて下さい。", "次の試練を受ける準備ができたようだな、{name}。修行に辛抱強く取り組んできたが、もっと多くを学ぶ時が来た。水の純粋さについて学ぶ時が来たのだ。\n\nBarrensのIslen Waterseerを探せ。彼女はSouthfury RiverとRatchetの南、東の海岸沿いにいる。釣り小屋にいるはずだ。幸運を祈る、{name}。", nil, "風は地平の彼方から足早にお前へ近づき、大地はお前の足元で揺るぎなくあり、そしてお前の魂はすでに火に温められている――ならば今こそ、水の清らかさについて学ぶ時だろう。\n\nお前の道はここまで導いてきた。そしてお前の魂は、さらに先へ進む力を与えてくれる。だが最初の一歩を踏み出すのは、お前自身だ。", 0x1f0e11aa, 0x52f30fbd, 0x2f9a1a5e, nil, 0xf9228c66, "...m." },
  [2986] = { "水の呼び声", "BarrensのIslen Waterseerを見つけて下さい。", "あなたが最後に試されてから、長い時が経ちました、{name}。あなたはこれまでの修行で辛抱強さを示してきましたが、さらに学ぶ時が来たのです。水の清らかさについて学ぶ時が来ました。\n\nBarrensのIslen Waterseerを探しなさい。Southfury RiverとRatchetの南、東の海岸沿いにいます。釣り小屋で見つかるでしょう。幸運を祈ります、{name}。", nil, "風は地平の彼方から足早にお前へ近づき、大地はお前の足元で揺るぎなくあり、そしてお前の魂はすでに火に温められている――ならば今こそ、水の清らかさについて学ぶ時だろう。\n\nお前の道はここまで導いてきた。そしてお前の魂は、さらに先へ進む力を与えてくれる。だが最初の一歩を踏み出すのは、お前自身だ。", 0x1f0e11aa, 0x52f30fbd, 0x7363625e, nil, 0xf9228c66, "...m." },
  [2987] = { "Gordunni Cobalt", "Camp MojacheのOrwin Gizzmickは、Gordunni Cobaltのサンプルを12個求めています。", "Feralasに着いたばかりなんだが、ここの荒野に住むGordunni Ogresが面白い鉱物を持っていると聞いてね。奴らが何をたくらんでいるかは知らないが、あの物をずいぶん大事にしているのは確かだ！ そこらに放っておいたりはしない。いや、私みたいな連中の手に渡らないように埋めているんだ。\n\nその気があるなら、私のシャベルを貸そう。ここから北のGordunni Outpostへ行って、Gordunni cobaltを掘り出してきてくれ。青い輝きを探して、そこを掘るんだ！", "さっさと上に行って掘り始めな!\n\nこっちは行くところも会う相手もあるんだ。時は金なりだよ!", "完璧だ！旅を続けながらこれを持っていくとしよう、{name}。このcobaltに大枚を払う相手はきっと見つかるさ。\n\nほら、手間をかけた分だ、受け取ってくれ。", 0x8fe31774, 0xcd9a26c2, 0x2dd1e0e3, 0x59e88299, 0x4cc222f9, "....." },
  [2988] = { "Witherbark族の檻", "Witherbark族のふたつの村にある檻を調べ、その後Gryphon Master Talonaxeの元へ戻って下さい。", "我らの最も強きgryphonの息子がいなくなった！ Swiftwingの跡継ぎSharpbeakが、数日前に両親と狩りをしている最中に行方不明になったのだ。トロールどもが連れ去ったのだと我々は考えている。\n\n力を貸してくれ！ Witherbarkのトロールの村2つで檻を探し、Sharpbeakがいないか確かめてくれ。", "檻は調べたか、{name}? Sharpbeakを見つけねば!", "Sharpbeakは村にいなかった? うーん……厳しい知らせだな。あの子は次世代のgryphonを率いることになってたんだ。あの子がいなくなってしまったら、我ら飛行部隊の力も気持ちも、恐ろしく落ち込むことになるだろう。", 0xd2ed808e, 0x7500a89e, 0x0bd1ca1e, 0xc6517c8f, 0xae95575d, "....." },
  [2989] = { "Altar of Zul", "Altar of Zulの最上部を調べ、Gryphon Master Talonaxeのところへ戻って下さい。", "SharpbeakはWitherbark族トロルのところにはいなかったのか。ならVilebranch族トロルが捕まえたんだろう。Vilebranch族の縄張りの西端にあるAltar of Zulへ行って、gryphonの子を探してきてくれ。", "急げ、{name}! VilebranchのトロールどもがSharpbeakを捕らえているなら、彼に何をしているか分かったものではない!", "Sharpbeakはそこにいなかったのか？悪い知らせだが、良い知らせでもある……\n\nAltar of Zulにいなかったのは幸いだ。Vilebranchのトロールどもは生け贄の儀式を行うことで知られているからな。\n\nこれまでの助力すべてに感謝する。だが残念ながら、この先にはさらに大きな務めが待っている。", 0x17765c2d, 0x87ae2e16, 0x8dc2c1ee, 0xa11ece19, 0x348c2bb1, "....." },
  [2990] = { "Thadius Grimshade", "Blasted LandsのThadius Grimshadeに、Sharpbeak's Featherを渡して下さい。", "このfeatherを占い師のThadius Grimshadeのところへ持っていってくれ。奴は何年も前に、より暗い知識を求めてAerie Peakを去った。だが心の中では今もWildhammerなのだ！\n\n奴の才能なら、Sharpbeakを見つける助けになるかもしれん。\n\nこのfeatherは、あのgryphonの子が眠る巣から取ってきたものだ。これをThadiusに渡せば、運がよければ、占いの魔法でSharpbeakを見つけてくれるだろう。\n\n幸運を祈る、{name}。ThadiusはBlasted LandsのNethergarde Keepにあるメイジの塔にいる。", "{name}、贈り物を持ってきてくれたのか?", "ああ、そうだ。この羽根は見事なグリフォンのものだ。大いなる運命を背負った一羽の……傷つかずに成鳥まで生き延びられればの話だがな。\n\n彼を見つけたいのか？ならばよく聞け、勇敢なる{class}よ……", 0x544cdf02, 0xf32d217d, 0x7a4689be, 0x0c71e9f6, 0xe9dbc04a, "....." },
  [2991] = { "Nekrum's Medallion", "Nekrum's MedallionをBlasted LandsのThadius Grimshadeに渡して下さい。", "お前のgryphonの居場所は突き止めてやろう。だがその前に、私のために一仕事してもらう。Zul'Farrakにいるトロール、Nekrum Gutchewerが、私がぜひとも調べたいmedallionを持っている。そのMedallionを持ってくれば、私の力でSharpbeakを見つけてやろう。\n\nZul'Farrakは海を越えた西、Tanarisの砂漠にある。", "Nekrum's Medallionは持っているか、{name}? その中には隠された力があり、私はそれを早く解き明かしたいのだ。", "ああ、Nekrumのメダルか。これがあのトロールに不自然なほどの長寿を与えたと噂されているが、代償もあったという。私は、その……不快な副作用を避けつつ、メダルの力を得る方法を見つけたいのだ。\n\nお前は私のために働いてくれた、{name}。では、こちらも取引の約束を果たすとしよう。", 0xd0e71ef2, 0x69d044e5, 0x23900882, 0xb6e9fb8f, 0x5ceb3a7c, "....." },
  [2992] = { "占い", "Grimshadeが占いの儀式を行うまで待って下さい。", "占いの儀式を行う間、離れていろ。お前が持ってきたfeatherとその持ち主とのつながりを見つけ出し、そのつながりをたどってSharpbeak自身のもとへ行き着いてみせる。\n\nつまり……すべて計画どおりにいけば、の話だがな。そうでなければ……目を閉じておいたほうがいい。", nil, "儀式は成功だ。Sharpbeakが見えたから、Sharpbeakの見つけ方を教えてやれるぞ。", 0xf42df580, 0xa6313eaf, 0x9aae3f04, nil, 0xd58e9db1, "...m." },
  [2993] = { "Hinterlandsへの帰還", "Gryphon Master Talonaxeと話して下さい。", "Sharpbeakは、HinterlandsのJintha'Alorの頂上、高い崖の上の檻に閉じ込められている。その檻の鍵は、Vilebranchトロールの大巫女、Vile Priestess Hexxが持っている。\n\nさあ、私の役目は果たした。お前のクエストに幸運を祈る、{name}。", nil, "Grimshadeと話したのか？彼は何と言っていた？\n\n……何だと？VilebranchのトロールどもがSharpbeakを捕らえている？耐えられん！奴を取り戻すために部隊を編成せねば！", 0x5419b47b, 0x4ba254df, 0x0fa70323, nil, 0x98f33a86, "...m." },
  [2994] = { "Sharpbeakの救出", "Jintha'Alor最上部までの道を切り開き、Sharpbeakの檻の鍵を手に入れるためにVile Priestess Hexxを殺してSharpbeakを救って下さい。", "Sharpbeakを救わねばならん！\n\nVilebranchの領地の中心にあるJintha'Alorの頂上まで戦い抜き、邪悪なPriestess HexxからSharpbeakの檻の鍵を奪い、そしてSharpbeakを見つけて救い出すのだ！", "Sharpbeakを救え!", "SwiftwindとKeenclawがついさっき子を連れて戻ってきた。新米の親のように子にかかりきりだ。あの二羽が再び揃った姿を見ると、この老いたドワーフでさえ目が霞むというものだ……\n\nあなたがしてくれたことには到底報いきれない、{name}。Aerie peakのグリフォンたちも、その乗り手たちも、あなたの名を長く長く歌い継ぐだろう。", 0x64daaa65, 0x7af19d1c, 0x68d07569, 0x180edb9f, 0x5cb3cadc, "....." },
  [2995] = { "通信網", "UndercityのOran Snakewritheは、Hinterlandsへ行きHighvale Records・Highvale Report・Highvale Notesを燃やすよう求めています。", "Quel'Danil Lodgeは、Hinterlandsのハイエルフたちの連絡の中心だ。奴らの大使たちは他の種族との関係を築こうと動いていて、Hinterlands南部に住むWitherbarkトロールについての知識をその者たちと分かち合っている。その連絡に関する文書はすべて、あのロッジに保管されている。\n\nHighvaleの連中に、他の者たちと同盟を結ばせるわけにはいかない、{name}。\n\nHighvaleの文書を破壊しろ。奴らの連絡網を焼き払う必要がある……文字通りにな。", "Highvale elvesを孤立させておくことが肝心だ。ロッジは見つかったか?", "完璧です、{name}。Highvaleが失った情報を回復しようとしている間、当分通信網を封じることができるでしょう……。", 0x0715ee1f, 0x3448961e, 0xb2af364f, 0x725c34a5, 0x7a1c4449, "....." },
  [2996] = { "Strahadを捜して", "RatchetのStrahad Farsanと話して下さい。", "これまで私がお前に技を教えてきたが、別の者がお前を教える時が来た。その者はRatchetにいて、名はStrahadという。彼は人間だが、それで弱いと思い込んで侮るな。小柄かもしれないが、彼は強大だ。より強力な召喚について教えてくれるだろう――お前にはその準備ができていると私は感じている。今すぐ彼のもとへ行け。彼はRatchetにいる……港町の上、彼の塔の隣だ。", nil, "Ratchetは今日も賑わっているな。港町の営みを眺めるのは実に楽しい。謎に満ち、冒険に満ち……そして無知に満ちている。\n\nその目に見えるのは憎しみか、{name}？よろしい、それは有効に使わせてもらおう。", 0x884bfbbe, 0x0c866240, 0x442728fe, nil, 0x44d961f5, "...m." },
  [2997] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "こんにちは、{name}。Dun Moroghの人々を助けるのに忙しいのはわかっておるが、時間ができたらIronforgeまで上っていって、わしらの中でも最も尊敬されている一人、Tiza Battleforgeと話すといい。若いパラディンたちが光について、そして自分たちに何が求められているかについてもっと学ぶ時が来ると、訪ねていくのが彼女なんじゃ。\n\n彼女はHall of Mysteriesの上の階におる。行ったことがないなら、Mystic Wardにあるぞ。幸運を祈るよ、{name}。", nil, "ご機嫌よう、{name}。「光」があなたに真の道をお示し下さり、邪悪から守って下さりますよう願っていますよ。", 0x85861feb, 0x04be03fc, 0x4e98a6c9, nil, 0x942f654d, "...m." },
  [2998] = { "Tome of Divinity", "StormwindのDuthorian Rallに話しかけて下さい。", "ごきげんよう、同胞よ。我々の中でも特に影響力のあるパラディンの一人、Duthorian Rallが最近あなたのことを話していました。そろそろあなたを試す時だと彼が話しているのを耳にしたのです……それに、これまでのあなたの働きぶりをとても褒めてもいましたよ。\n\n私があなたなら、時間のあるときにStormwindへ行って彼と話しますね。きっとCathedral of Lightにいるはずです――彼はほとんどの時間をそこで過ごしていますから。", nil, "ここStormwindは美しいでしょう？\n\n実のところ、これ以上ないほどよい時に来てくれました、{name}。", 0x85861feb, 0x0f3ca705, 0x35944d83, nil, 0x3fd2197e, "...m.", nil, nil, 0xa8a5e826, nil, nil },
  [2999] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "こんにちは、{name}。Dun Moroghの民を助けるので忙しいのは分かっていますが、時間があったら上の階へ行って、我々ドワーフの尊敬を受けているTiza Battleforgeに話しかけて下さい。駆け出しのパラディンが「光」やあなたに期待されていることについてもっと詳しく学ぶ時には、彼女のところへ行くのです。", nil, "ご機嫌よう、{name}。「光」があなたに真の道をお示し下さり、邪悪から守って下さりますよう願っていますよ。", 0x85861feb, 0xafea0004, 0xdacc6f34, nil, 0x942f654d, "...m." },
})
